'use strict';
/* The Motor Trade v0.4: UI for fictional vehicle dossiers, without any API calls. */
(() => {
  const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
  const miles=n=>new Intl.NumberFormat('en-GB').format(n)+' miles';
  const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function render(car,kind,{open=false,inspected=false,price=null,inspectionClosed=false}={}) {
    if(!car?.profile)return '';
    const p=car.profile,E=window.MotorTradeEngine;
    const evidence=window.MotorTradeAccuracy?.lookup(car)||
      {status:'pending',note:'No specification source registry available.'};
    const proof=evidence.status==='manufacturer'?
      '<div class="vehicle-spec-proof"><strong>UK MODEL SPECIFICATION SOURCED</strong>'+
      '<p>'+esc(evidence.note)+'</p><a target="_blank" rel="noopener noreferrer" href="'+
      esc(evidence.url)+'">VIEW MANUFACTURER EVIDENCE</a></div>':
      evidence.status==='corroborated'?
      '<div class="vehicle-spec-proof vehicle-spec-pending"><strong>SPECIFICATION CORROBORATED · NOT FACTORY VERIFIED</strong>'+
      '<p>'+esc(evidence.note)+'</p><a target="_blank" rel="noopener noreferrer" href="'+
      esc(evidence.url)+'">VIEW SUPPORTING SOURCE</a></div>':
      '<div class="vehicle-spec-proof vehicle-spec-pending"><strong>MODEL SPECIFICATION · REVIEW PENDING</strong>'+
      '<p>'+esc(evidence.note)+'</p></div>';
    const quote=kind==='stock'?null:E.quote(car,kind,price,inspected);
    const totalPrep=p.basePrep+(p.hiddenFault?.cost||0);
    const booked=car.workshop?.repairCost||0;
    const outstanding=car.workshop?.stage==='ready'?car.prepSpent:
      (['in-progress','quality-check'].includes(car.workshop?.stage)?
        booked:totalPrep);
    const prepLabel=car.workshop?.stage==='ready'?'ACTUAL REPAIR SPEND':
      booked?'BOOKED REPAIR COST':'INITIAL REPAIR BUDGET';
    const showExtra=inspected||
      (kind==='stock'&&(car.workshop?.stage!=='unassessed'||!!p.inspected));
    const hidden=showExtra?
      (p.hiddenFault?esc(p.hiddenFault.item)+' — '+money(p.hiddenFault.cost):
        'No additional issue revealed in this simulated assessment'):
      'Not yet verified. A paid inspection may reveal additional repairs.';
    const numbers=quote?[
      ['TRADE VALUE',p.trade],['LIKELY SALE',p.likelySale],
      ['RECOMMENDED MAX',quote.maxBid],['EST. CONTRIBUTION',quote.expectedMargin]
    ]:[
      ['LIKELY SALE',p.likelySale],[prepLabel,outstanding],
      ['BUY COST',car.cost],['PROJECTED CONTRIBUTION',p.likelySale-car.cost-outstanding]
    ];
    const stats='<div class="intel-numbers">'+numbers.map(([label,value],i)=>
      '<div><span>'+label+'</span><strong'+(quote&&i===3?' id="projection-'+esc(car.id)+'"':'')+
      (value<0?' class="intel-loss"':'')+'>'+money(value)+'</strong></div>').join('')+'</div>';
    const forecast=quote?'<p class="intel-formula">Forecast: likely sale − offer − fees − expected repairs − inspection if paid. '+
      (inspected?'Inspected cost estimate.':'Uninspected risk allowance included.')+'</p>':'';
    const breakdown=quote?'<h4>MAXIMUM BID / OFFER WORKING</h4>'+
      '<div class="intel-repair"><span>Likely achieved sale</span><strong>'+money(quote.likelySale)+'</strong></div>'+
      '<div class="intel-repair"><span>Expected repair allowance</span><strong>− '+money(quote.prep)+'</strong></div>'+
      '<div class="intel-repair"><span>Buyer fees</span><strong>− '+money(quote.fee)+'</strong></div>'+
      '<div class="intel-repair"><span>Pre-purchase inspection if paid</span><strong>− '+money(quote.inspection)+'</strong></div>'+
      '<div class="intel-repair"><span>Target trading contribution</span><strong>− '+money(quote.targetMargin)+'</strong></div>'+
      '<div class="intel-repair intel-repair-total"><span>Indicative maximum offer (rounded)</span><strong>'+
        money(quote.maxBid)+'</strong></div>'+
      '<p class="intel-small">At your entered offer of '+money(quote.price)+
        ', estimated contribution is '+money(quote.expectedMargin)+
        '. A negative value indicates an expected loss before overheads.</p>':'';
    const known=p.knownRepairs.map(r=>
      '<div class="intel-repair"><span>'+esc(r.item)+'</span><strong>'+money(r.cost)+'</strong></div>').join('');
    const openReport=open?'<div class="intel-expanded"><div class="intel-grid">'+
      '<div><small>ENGINE / POWERTRAIN</small><strong>'+esc(p.engine)+'</strong></div>'+
      '<div><small>PREVIOUS KEEPERS (SIMULATED)</small><strong>'+p.owners+'</strong></div>'+
      '<div><small>CONDITION GRADE</small><strong>'+p.grade+' / 5</strong></div>'+
      '<div><small>SERVICE HISTORY</small><strong>'+esc(car.history)+'</strong></div>'+
      '<div><small>MOT (SIMULATED)</small><strong>'+esc(p.mot.result)+' · '+p.mot.monthsRemaining+' MONTHS LEFT</strong></div>'+
      '<div><small>LAST RECORDED MOT MILEAGE</small><strong>'+miles(p.mot.recordedMiles)+'</strong></div>'+
      '<div><small>LOCAL DEMAND</small><strong>'+esc(p.demand)+'</strong></div>'+
      '<div><small>RETAIL ASKING GUIDE</small><strong>'+money(p.retail)+'</strong></div></div>'+
      proof+
      '<p class="intel-disclaimer">Mileage, prior keepers, MOT, service history, buying and selling valuations are fictional gameplay estimates. They are not DVLA, DVSA, CAP HPI or Auto Trader records. Manufacturer evidence, when linked, verifies only the model derivative and powertrain.</p>'+
      '<h4>MOT ADVISORIES</h4><p class="intel-small">'+
        (p.mot.advisories.length?esc(p.mot.advisories.join(' · ')):'No advisories recorded in this fictional report')+'</p>'+
      '<h4>KNOWN PREPARATION ITEMS</h4>'+known+
      '<div class="intel-repair intel-repair-total"><span>Known repair estimate</span><strong>'+money(p.basePrep)+'</strong></div>'+
      '<h4>ADDITIONAL CONDITION RISK</h4><p class="intel-small">'+hidden+'</p>'+breakdown+
      (kind==='stock'?'<p class="intel-small">Original diagnosed repair budget: '+
         money(totalPrep)+'. '+(car.workshop?.stage==='ready'?
           'Actual completed repairs: '+money(car.prepSpent)+'.':
           booked?'Workshop charges already booked: '+money(booked)+'.':
           'The workshop will issue a separate paid quotation. Sales are blocked until final quality control passes.')+
         '</p>':'')+
      '<div class="intel-foot">'+(kind==='stock'?'':inspected?
        '<span class="intel-inspected">INSPECTION PAID · '+money(p.inspectionFee)+'</span>':
        inspectionClosed?'<span class="intel-closed">LOT CLOSED · INSPECTION UNAVAILABLE</span>':
        '<button type="button" class="trade-button trade-button-secondary" data-action="inspect-lead" data-id="'+esc(car.id)+
          '" data-kind="'+kind+'">BUY INSPECTION · '+money(p.inspectionFee)+'</button>')+'</div></div>':'';
    return '<section class="intel-panel"><div class="intel-top">'+
      '<span>VEHICLE FILE '+esc(p.ref)+' · GRADE '+p.grade+'</span>'+
      '<button type="button" class="intel-toggle" data-action="toggle-report" data-id="'+esc(car.id)+
      '" data-kind="'+kind+'" aria-expanded="'+String(open)+'">'+(open?'HIDE REPORT':'VIEW FULL REPORT')+' ▾</button>'+
      '</div>'+stats+forecast+openReport+'</section>';
  }
  window.MotorTradeVehicleView=Object.freeze({render});
})();

people-view.js:
'use strict';
/* v0.9.32 employment desk. Data is fictional and escaped for HTML strings. */
(() => {
  const esc=x=>String(x).replace(/[&<>"']/g,ch=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  })[ch]);
  const gbp=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',
    maximumFractionDigits:0}).format(n);
  const roleName={sales:'SALES EXECUTIVE',buyer:'VEHICLE BUYER',technician:'PREP TECHNICIAN',supervisor:'STAFF SUPERVISOR'};
  const traits={
    sales:[['Sales', 'sales'],['Negotiation','negotiation'],['Customer care','care'],['Reliability','reliability']],
    buyer:[['Negotiation','negotiation'],['Vehicle knowledge','knowledge'],['Reliability','reliability'],['Customer care','care']],
    technician:[['Diagnostics','diagnostics'],['Efficiency','efficiency'],['Reliability','reliability'],['Customer care','care']],
    supervisor:[['People leadership','care'],['Staff communication','negotiation'],['Reliability','reliability'],['Trade knowledge','knowledge']]
  };
  const bar=(name,value)=>
    '<div class="people-trait"><span>'+esc(name)+'</span><div class="people-track">'+
    '<span style="width:'+value*5+'%"></span></div><b>'+value+'/20</b></div>';
  function header(person){
    return '<div class="people-head"><div><span class="people-role">'+
      esc(roleName[person.role])+'</span><h3>'+esc(person.name)+'</h3>'+
      '<small>'+person.experience+' YEARS EXPERIENCE</small></div>'+
      '<span class="people-salary">'+gbp(person.monthlySalary)+'<small>BASE / MONTH</small></span></div>';
  }
  const labels={
    sales:'Creates more enquiries, gets buyers to view sooner and improves test-drive conversion and negotiations. Higher performers earn a larger share of positive gross margin.',
    buyer:'Can secure more competitive private-seller agreements and provide auction rival-bid intelligence.',
    technician:'Runs one assigned in-house repair at a time. More technicians enable parallel preparation, but wages and parts still cost money.',
    supervisor:'Manages routine rota and morale check-ins automatically each week. Escalates costed staff-support proposals to you for approval or refusal. One supervisor maximum; salary continues daily.'
  };
  function salesForecast(person,P){
    if(person.role!=='sales')return '';
    const p=P.salesProfile(person);
    return '<div class="people-caption"><strong>SALES IMPACT:</strong> +'+p.enquiryLift+
      ' percentage points to enquiry chance · +'+p.driveLift+
      ' to drive conversion · '+(p.fastViewing?'NEXT-DAY VIEWINGS':'UP TO 48-HOUR VIEWINGS')+
      ' · '+Math.round(p.commissionRate*100)+'% commission on positive gross margin.</div>';
  }
  function applicants(state,P){
    const candidates=P.applicants(state.day);
    const cards=candidates.map(candidate=>{
      const already=state.staff.some(e=>e.name===candidate.name);
      const filled=state.staff.filter(e=>e.role===candidate.role).length>=
        P.roleLimit(state,candidate.role);
      const paused=state.staff.length>=P.staffLimit(state);
      const traitsHtml=traits[candidate.role].map(([a,k])=>bar(a,candidate.skills[k])).join('');
      const quote=P.hireQuote(state,candidate);
      const costText='REQUIRES '+gbp(quote.required)+' TOTAL CASH · '+P.WAGE_COVER_DAYS+
        ' DAYS WAGE COVER · PROTECTED REPAIRS '+gbp(quote.protectedStock)+
        (quote.shortfall?' · SHORT BY '+gbp(quote.shortfall):' · AFFORDABLE NOW');
      return '<article class="people-card">'+header(candidate)+
        '<div class="people-traits">'+traitsHtml+'</div>'+
        '<p class="people-caption">'+esc(labels[candidate.role])+'</p>'+
        salesForecast(candidate,P)+
        '<div class="people-card-footer"><span>'+costText+'</span>'+
        '<button type="button" class="trade-button" data-action="hire-staff" data-id="'+
          esc(candidate.id)+'"'+(already||filled||paused||!!quote.shortfall?' disabled':'')+'>'+
          (already?'ALREADY HIRED':filled?(candidate.role==='technician'?'TECHNICIAN PLACES FULL':'ROLE FILLED'):
            paused?'TEAM FULL':quote.shortfall?'NOT ENOUGH CASH':'HIRE EMPLOYEE')+
          '</button></div></article>';
    });
    const names={sales:'SALES EXECUTIVES',buyer:'VEHICLE BUYERS',technician:'WORKSHOP TECHNICIANS',supervisor:'STAFF SUPERVISORS'};
    return '<p class="trade-alert">Applicants refresh every seven game days. Choose one staff supervisor to manage routine morale concerns and propose owner-approved interventions. Hire technicians up to your unlocked workshop capacity. '+
      'Each hire needs a £'+P.HIRING_FEE+' onboarding charge, protected repair funds and '+P.WAGE_COVER_DAYS+
      ' days of team wages; monthly salaries continue afterward. A new employee starts the following game day.</p>'+
      ['supervisor','technician','sales','buyer'].map(role=>
        '<section class="people-recruit-group"><h3>'+names[role]+' · '+
        candidates.filter(c=>c.role===role).length+' CANDIDATES · '+
        state.staff.filter(e=>e.role===role).length+'/'+P.roleLimit(state,role)+' HIRED</h3>'+
        '<div class="people-recruit-grid">'+candidates.filter(c=>c.role===role).map(c=>
          cards[candidates.indexOf(c)]).join('')+'</div></section>').join('');
  }
  function roster(state,P){
    if(!state.staff.length)return '<div class="trade-empty"><h2>OWNER OPERATED.</h2>'+
      '<p>You handle vehicle sourcing, sales and workshop coordination. Hiring adds expertise and ongoing expenses.</p></div>';
    return state.staff.map(employee=>{
      const active=P.isActive(state,employee);
      const assigned=employee.role==='technician'?state.vehicles.find(v=>
        v.workshop?.technicianId===employee.id&&v.workshop.method==='internal'&&
        ['in-progress','quality-check'].includes(v.workshop.stage)):null;
      const status=state.payrollArrears>0?'PAYROLL OVERDUE':
        state.day<employee.startDay?'STARTS DAY '+employee.startDay:
        employee.trainingUntil!==null&&state.day<employee.trainingUntil?
        'TRAINING UNTIL DAY '+employee.trainingUntil:
        active?(assigned?'ASSIGNED TO STOCK '+assigned.id:'AVAILABLE'):'UNAVAILABLE';
      return '<article class="people-card">'+header(employee)+
        '<div class="people-meta">'+
        (employee.origin==='opening-team'?'<span>OPENING TEAM</span>':'')+
        '<span>'+esc(status)+'</span>'+
        '<span>MORALE '+employee.morale+'/100</span>'+
        '<span>'+employee.deals+' DEALS · '+employee.workDone+' PREP JOBS</span></div>'+
        '<div class="people-traits">'+traits[employee.role].map(([a,k])=>bar(a,employee.skills[k])).join('')+'</div>'+
        '<p class="people-caption">'+esc(labels[employee.role])+'</p>'+salesForecast(employee,P)+
        '<div class="people-card-footer"><span>DAILY WAGE PROVISION '+gbp(P.dailyCost(employee))+'</span>'+
        '<div class="people-actions"><button type="button" class="trade-button trade-button-secondary" data-action="train-staff" data-id="'+employee.id+'">TRAIN · '+gbp(P.TRAINING_FEE)+'</button>'+
        '<button type="button" class="trade-button people-release" data-action="release-staff" data-id="'+employee.id+'">RELEASE</button></div></div></article>';
    }).join('');
  }
  const levels=[
    {min:0,max:19,name:'NEW TRADER',benefit:'Starting reputation tier'},
    {min:20,max:39,name:'LOCAL DEALER',benefit:'First forecourt expansion becomes eligible'},
    {min:40,max:59,name:'TRUSTED DEALER',benefit:'Extra sales and technician hiring capacity'},
    {min:60,max:79,name:'REGIONAL SPECIALIST',benefit:'Regional standing; luxury market needs 65+ and cash'},
    {min:80,max:100,name:'PRESTIGE DEALER',benefit:'Highest staff capacity and premises eligibility'}
  ];
  function reputation(state){
    const score=Math.max(0,Math.min(100,state.reputationScore));
    const current=levels.find(l=>score>=l.min&&score<=l.max)||levels[0];
    const next=levels.find(l=>l.min>score)||null;
    const points=next?next.min-score:0;
    const pct=Math.max(0,Math.min(100,score));
    const sales=state.sold||[];
    const totalTurnover=sales.reduce((n,row)=>n+row.price,0);
    const events=Array.isArray(state.reputationHistory)?state.reputationHistory:[];
    const latest=[...events].reverse();
    const recent=events.filter(e=>e.day>=Math.max(1,state.day-29));
    const delta=recent.reduce((n,e)=>n+e.delta,0);
    const deltaLabel=(delta>0?'+':'')+delta;
    const deltaTone=delta>0?' rep-good':delta<0?' rep-bad':'';
    const payroll=state.payrollArrears||0;
    const premises=state.premises?.arrears||0;
    const firstTarget=next?next.min:100;
    const earnedTier=levels.findIndex(x=>x===current);
    const tierRows=levels.map((l,i)=>{
      const standing=i===earnedTier?'CURRENT':i<earnedTier?'BELOW CURRENT':'NOT YET REACHED';
      const cls=i===earnedTier?' rep-current':i<earnedTier?' rep-passed':' rep-locked';
      return '<div class="rep-stage'+cls+'"><span class="rep-stage-no">'+
        String(i+1).padStart(2,'0')+'</span><div class="rep-stage-name">'+
        '<strong>'+esc(l.name)+'</strong><small>'+esc(l.benefit)+'</small></div>'+
        '<span class="rep-stage-range">'+l.min+'–'+l.max+'</span>'+
        '<em>'+standing+'</em></div>';
    }).join('');
    const entry=row=>{
      const positive=row.delta>0,negative=row.delta<0;
      return '<div class="rep-change"><span>DAY '+row.day+'</span>'+
        '<strong class="'+(positive?'rep-good':negative?'rep-bad':'')+'">'+
        (row.delta>0?'+':'')+row.delta+'</strong>'+
        '<p>'+esc(row.reason)+'</p></div>';
    };
    const last=latest.slice(0,2);
    const newest=last.length?last.map(entry).join(''):
      '<div class="rep-empty">No reputation changes recorded yet. Completed deals and '+
      'operating issues will appear here.</div>';
    const more=latest.slice(2);
    const cashNumber=gbp(totalTurnover);
    const risk=payroll?
      '<div class="rep-risk"><strong>PAYROLL NEEDS ATTENTION</strong><span>'+
        gbp(payroll)+' in unpaid staff obligations can affect trust.</span>'+
        '<button type="button" data-page="staff">OPEN STAFF DESK</button></div>':
      premises?
      '<div class="rep-risk"><strong>PREMISES BILLS OUTSTANDING</strong><span>'+
        gbp(premises)+' due. Extended arrears can lower reputation.</span>'+
        '<button type="button" data-page="finance">VIEW FINANCES</button></div>':
      '<div class="rep-priority"><strong>KEEP THE MOMENTUM</strong>'+
        '<span>Prepare vehicles properly, price realistically and complete quality handovers.</span>'+
        '<button type="button" data-page="workshop">VIEW WORKSHOP</button></div>';
    const scoreHero='<section class="rep-hero" aria-label="Current dealership reputation">'+
      '<div class="rep-hero-id"><div><small>YOUR DEALERSHIP STANDING</small>'+
        '<h2>'+esc(current.name)+'</h2>'+
        '<p>'+esc(state.name)+' · Day '+state.day+'</p></div>'+
        '<div class="rep-score"><strong>'+score+'</strong><span>/ 100</span></div></div>'+
      '<div class="rep-progress" role="progressbar" aria-label="Reputation score" '+
        'aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+score+'">'+
        '<div style="width:'+pct+'%"></div></div>'+
      '<div class="rep-next"><span>'+(next?
        '<strong>'+points+' POINT'+(points===1?'':'S')+' TO '+esc(next.name)+'</strong>'+
        ' · NEXT TIER AT '+firstTarget:
        '<strong>HIGHEST REPUTATION TIER</strong> · KEEP CUSTOMER TRUST HIGH')+
        '</span><span>CURRENT SCORE '+score+' / 100</span></div></section>';
    const metrics='<div class="rep-kpis">'+
      [['VEHICLES HANDED OVER',String(sales.length),'Completed retail sales'],
       ['LIFETIME SALES TURNOVER',cashNumber,'Completed sales only'],
       ['LAST 30 GAME DAYS',deltaLabel+' POINTS','Recorded reputation change'],
       ['PAYROLL OBLIGATIONS',gbp(payroll),'Outstanding staff wages / notice']].map(
        ([label,value,note],i)=>'<div class="rep-kpi'+(i===2?deltaTone:i===3&&payroll?' rep-alert':'')+'">'+
          '<small>'+label+'</small><strong>'+esc(value)+'</strong><span>'+note+
        '</span></div>').join('')+'</div>';
    const main='<div class="rep-main-grid">'+
      '<section class="rep-panel"><div class="rep-panel-head"><div><small>CAREER PROGRESSION</small>'+
        '<h3>REPUTATION LEVELS</h3></div><span>5 TIERS</span></div>'+
        '<div class="rep-stage-list">'+tierRows+'</div>'+
        '<p class="rep-panel-note">Tier limits are recalculated from your current score. '+
        'Staffing and premises changes also require available capacity and cash.</p></section>'+
      '<section class="rep-panel"><div class="rep-panel-head"><div><small>WHAT SHAPES THE SCORE</small>'+
        '<h3>BUILDING TRUST</h3></div><span>REAL GAME EVENTS</span></div>'+
        '<div class="rep-drivers"><div><strong>BUILDS REPUTATION</strong>'+
        '<p>Completed handovers of good-condition cars; strong customer care and fair prices.</p></div>'+
        '<div><strong>CAN DAMAGE REPUTATION</strong>'+
        '<p>Poor-condition stock, inflated retail prices and unresolved payroll or long-overdue premises bills.</p></div></div>'+
        risk+
        '<div class="rep-quick-links"><button type="button" data-page="sales">SALES OFFICE</button>'+
        '<button type="button" data-page="stock">VEHICLE STOCK</button>'+
        '<button type="button" data-page="reports">MANAGEMENT REPORTS</button></div>'+
      '</section></div>';
    const history='<section class="rep-panel rep-history"><div class="rep-panel-head">'+
        '<div><small>RECORDED CUSTOMER & STAFF OUTCOMES</small>'+
        '<h3>REPUTATION HISTORY</h3></div><span>'+events.length+' EVENTS RECORDED</span></div>'+
      '<div class="rep-history-preview">'+newest+'</div>'+
      (more.length?'<details class="rep-more"><summary>VIEW '+more.length+
        ' MORE RECORDED CHANGES</summary><div class="rep-history-all">'+
        more.map(entry).join('')+'</div></details>':'')+'</section>';
    const future='<details class="rep-future"><summary>LONG-TERM PRESTIGE TARGET & MARKET ELIGIBILITY</summary>'+
      '<div class="rep-future-body"><p><strong>Live market rules:</strong> Modern stock needs £18,500 opening cash and 15 reputation; '+
      'premium stock needs £42,000 and 40 reputation; luxury stock needs £110,000 and 65 reputation. '+
      'The market checks cash and the monthly starting reputation, not just the tier name.</p>'+
      '<p><strong>Future development concept:</strong> a separate prestige-seller milestone of 80+ reputation '+
      'and £500,000 lifetime sales turnover. You currently have '+score+
      ' reputation and '+cashNumber+' in completed turnover. '+
      'That separate milestone is not an additional unlock in this version.</p></div></details>';
    return '<div class="rep-control">'+scoreHero+metrics+main+history+future+
      '<p class="rep-disclosure">Reputation and trading results are fictional simulation values. '+
      'A higher score alone does not guarantee customers, profitable stock or cash.</p></div>';
  }
  function totals(state,P){
    const wages=state.staff.reduce((sum,employee)=>sum+P.dailyCost(employee),0);
    const total=state.staff.reduce((sum,employee)=>sum+employee.monthlySalary,0);
    const technicians=state.staff.filter(s=>s.role==='technician').length;
    const salespeople=state.staff.filter(s=>s.role==='sales').length;
    const next=state.reputationScore<40?'6 technician places at 40 reputation':
      state.reputationScore<80?'8 technician places at 80 reputation':null;
    return '<div class="people-metrics"><div><span>EMPLOYEES</span><strong>'+
      state.staff.length+' / '+P.staffLimit(state)+'</strong></div>'+
      '<div><span>DAILY WAGE SETTLEMENT</span><strong>'+gbp(wages)+'</strong></div>'+
      '<div><span>MONTHLY BASE PAY</span><strong>'+gbp(total)+'</strong></div>'+
      '<div><span>UNPAID PAYROLL / NOTICE</span><strong>'+gbp(state.payrollArrears)+'</strong></div>'+
      '<div><span>IN-HOUSE TECHNICIANS</span><strong>'+technicians+' / '+P.technicianLimit(state)+'</strong></div>'+
      '<div><span>SALES EXECUTIVES</span><strong>'+salespeople+' / '+P.salesLimit(state)+'</strong></div>'+ 
      '</div><p class="trade-alert">You can hire four technicians immediately, subject to a clear three-day wage buffer. '+
      'Each works on a separate vehicle. You can hire one sales executive at first, two at 40 reputation and three at 80, alongside one buyer. '+
      (next?'NEXT UNLOCK: '+next+'.':'All eight technician places are unlocked.')+'</p>';
  }

  /* v0.9.31 — Staff control centre. Read-only view over existing people rules. */
  const DESK_MODES=Object.freeze(['team','candidates']);
  const DESK_ROLES=Object.freeze(['all','sales','buyer','technician','supervisor']);
  const groupName={sales:'SALES',buyer:'BUYING',technician:'WORKSHOP',supervisor:'MANAGEMENT'};
  function employeeStatus(state,P,e){
    const assigned=e.role==='technician'?state.vehicles.find(v=>
      v.workshop?.technicianId===e.id&&v.workshop.method==='internal'&&
      ['in-progress','quality-check'].includes(v.workshop.stage)):null;
    if(state.payrollArrears>0)return {name:'PAYROLL OVERDUE',tone:'warning'};
    if(state.day<e.startDay)return {name:'STARTS DAY '+e.startDay,tone:'waiting'};
    if(e.trainingUntil!==null&&state.day<e.trainingUntil)
      return {name:'TRAINING TO DAY '+e.trainingUntil,tone:'waiting'};
    if(!P.isActive(state,e))return {name:'UNAVAILABLE',tone:'warning'};
    if(assigned)return {name:'WORKING · STOCK '+assigned.id,tone:'busy'};
    return {name:'AVAILABLE',tone:'available'};
  }
  function recruitStatus(state,P,c){
    const hired=state.staff.some(e=>e.name===c.name);
    const roleFull=state.staff.filter(e=>e.role===c.role).length>=P.roleLimit(state,c.role);
    const teamFull=state.staff.length>=P.staffLimit(state);
    const quote=P.hireQuote(state,c);
    const reason=hired?'ALREADY EMPLOYED':roleFull?'ROLE CAPACITY FULL':
      teamFull?'TEAM FULL':quote.shortfall?'INSUFFICIENT CASH':'CAN HIRE';
    return {reason,quote,canHire:!hired&&!roleFull&&!teamFull&&!quote.shortfall};
  }
  function deskCounts(state,P){
    const candidatePool=P.applicants(state.day);
    const employed=state.staff;
    return {employed:employed.length,active:employed.filter(e=>P.isActive(state,e)).length,
      techniciansFree:P.availableTechnicians(state).length,
      daily:employed.reduce((n,e)=>n+P.dailyCost(e),0),
      monthly:employed.reduce((n,e)=>n+e.monthlySalary,0),
      rolesUsed:employed.length,rolesTotal:P.staffLimit(state),
      candidates:candidatePool.length,
      hireable:candidatePool.filter(c=>recruitStatus(state,P,c).canHire).length};
  }
  function staffRow(state,P,person,mode,selected){
    const hired=mode==='team',info=hired?employeeStatus(state,P,person):
      recruitStatus(state,P,person);
    const label=hired?info.name:info.reason;
    const tone=hired?info.tone:info.canHire?'available':'warning';
    const id=hired?'e:'+person.id:'c:'+person.id;
    return '<button type="button" class="sd-person'+(selected?' sd-person-active':'')+
      '" data-action="select-person" data-person="'+esc(id)+'"'+
      ' aria-pressed="'+String(selected)+'">'+
      '<span class="sd-person-main"><small>'+esc(roleName[person.role])+'</small>'+
      '<strong>'+esc(person.name)+'</strong><span>'+gbp(person.monthlySalary)+
      ' / MONTH · '+person.experience+' YEARS EXPERIENCE</span></span>'+
      '<em class="sd-tag sd-tag-'+tone+'">'+esc(label)+'</em></button>';
  }
  function skillSection(person,P){
    const roleInfo=person.role==='sales'?'ROLE IMPACT & COMMISSION':'HOW THIS ROLE HELPS';
    return '<section class="sd-competence"><div class="sd-section-head"><h4>SKILLS & EXPERIENCE</h4>'+
      '<span>RATINGS OUT OF 20</span></div><div class="sd-skills">'+
      traits[person.role].map(([name,key])=>bar(name,person.skills[key])).join('')+
      '</div><details class="sd-role-impact"><summary>'+roleInfo+'</summary>'+
      '<p>'+esc(labels[person.role])+'</p>'+salesForecast(person,P)+'</details></section>';
  }
  function employeeDetail(state,P,e){
    const info=employeeStatus(state,P,e);
    const dayRate=P.dailyCost(e);
    const notice=dayRate*7;
    const protectedFunds=P.hireQuote(state,e).protectedStock;
    const cooldown=e.lastTrainingDay&&state.day-e.lastTrainingDay<14;
    const training=e.trainingUntil!==null&&state.day<e.trainingUntil;
    const affordable=state.cash>=P.TRAINING_FEE+protectedFunds+state.payrollArrears;
    const block=training?'ALREADY TRAINING':cooldown?
      'NEXT TRAINING DAY '+(e.lastTrainingDay+14):!affordable?'INSUFFICIENT UNRESERVED CASH':'';
    return '<div class="sd-dossier"><header class="sd-file-head"><div><small>EMPLOYEE FILE · ID '+
      e.id+' · '+esc(roleName[e.role])+
      (e.origin==='opening-team'?' · OPENING TEAM':'')+
      '</small><h3>'+esc(e.name)+'</h3></div>'+
      '<span class="sd-tag sd-tag-'+info.tone+'">'+esc(info.name)+'</span></header>'+
      '<div class="sd-staff-summary">'+
      '<div><small>MONTHLY BASE WAGE</small><strong>'+gbp(e.monthlySalary)+'</strong></div>'+
      '<div><small>DAILY PAYROLL</small><strong>'+gbp(dayRate)+'</strong></div>'+
      '<div><small>MORALE</small><strong>'+e.morale+' / 100</strong></div>'+
      '<div><small>START DATE</small><strong>DAY '+e.startDay+'</strong></div></div>'+
      '<div class="sd-person-detail"><div>'+skillSection(e,P)+
      '<div class="sd-performance"><div><small>RETAIL DEALS</small><strong>'+e.deals+
      '</strong></div><div><small>PREPARATION JOBS</small><strong>'+e.workDone+
      '</strong></div><div><small>HIRED DAY</small><strong>'+e.hiredDay+
      '</strong></div></div></div><div class="sd-control"><div class="sd-section-head">'+
      '<h4>EMPLOYEE DECISIONS</h4><span>CONFIRMED ACTIONS</span></div>'+
      '<div class="sd-action-panel"><h5>STAFF TRAINING</h5>'+
      '<p>Costs '+gbp(P.TRAINING_FEE)+'. The employee is unavailable for two game days. '+
      'Role-specific skills and morale improve; wages still continue.</p>'+
      (block?'<p class="sd-issue">'+esc(block)+'</p>':'')+
      '<button type="button" class="trade-button" data-action="train-staff" data-id="'+e.id+'"'+
      (block?' disabled':'')+'>AUTHORISE TRAINING · '+gbp(P.TRAINING_FEE)+'</button></div>'+
      '<details class="sd-release"><summary>RELEASE EMPLOYEE / NOTICE COST</summary>'+
      '<p>Seven game days of provisional notice pay: <strong>'+gbp(notice)+'</strong>. '+
      'This may create unpaid payroll obligations if funds are insufficient. '+
      'The employee immediately leaves the team.</p>'+
      '<button type="button" class="trade-button people-release" data-action="release-staff" '+
      'data-id="'+e.id+'">RELEASE '+esc(e.name.toUpperCase())+'</button></details>'+
      '</div></div></div>';
  }
  function candidateDetail(state,P,c){
    const info=recruitStatus(state,P,c),q=info.quote;
    const todayCash=state.cash;
    const currentDaily=state.staff.reduce((n,e)=>n+P.dailyCost(e),0);
    const staffDaily=P.dailyCost(c);
    return '<div class="sd-dossier"><header class="sd-file-head"><div><small>RECRUITMENT FILE · '+
      esc(roleName[c.role])+'</small><h3>'+esc(c.name)+'</h3></div>'+
      '<span class="sd-tag sd-tag-'+(info.canHire?'available':'warning')+'">'+
      esc(info.reason)+'</span></header>'+
      '<div class="sd-staff-summary">'+
      '<div><small>MONTHLY BASE WAGE</small><strong>'+gbp(c.monthlySalary)+'</strong></div>'+
      '<div><small>DAILY PAYROLL ADDED</small><strong>'+gbp(staffDaily)+'</strong></div>'+
      '<div><small>EXPERIENCE</small><strong>'+c.experience+' YEARS</strong></div>'+
      '<div><small>ROLE CAPACITY</small><strong>'+
      state.staff.filter(e=>e.role===c.role).length+' / '+P.roleLimit(state,c.role)+
      '</strong></div></div>'+
      '<div class="sd-person-detail"><div>'+skillSection(c,P)+
      '</div><div class="sd-control"><div class="sd-section-head"><h4>HIRING DECISION</h4>'+
      '<span>STARTS NEXT GAME DAY</span></div>'+
      '<div class="sd-hire-figures">'+
      '<div><span>DEALERSHIP CASH TODAY</span><strong>'+gbp(todayCash)+'</strong></div>'+
      '<div><span>ONE-OFF ONBOARDING FEE</span><strong>'+gbp(P.HIRING_FEE)+'</strong></div>'+
      '<div><span>PROTECTED VEHICLE REPAIRS</span><strong>'+gbp(q.protectedStock)+'</strong></div>'+
      '<div><span>TEAM WAGES PER DAY AFTER HIRE</span><strong>'+gbp(q.dailyWages)+'</strong></div>'+
      '<div><span>3-DAY WAGE COVER</span><strong>'+
      gbp(q.dailyWages*P.WAGE_COVER_DAYS)+'</strong></div>'+
      (state.payrollArrears?'<div><span>EXISTING PAYROLL ARREARS</span><strong>'+
        gbp(state.payrollArrears)+'</strong></div>':'')+
      '<div class="sd-required"><span>TOTAL CASH NEEDED TO HIRE</span><strong>'+
      gbp(q.required)+'</strong></div></div>'+
      (q.shortfall?'<p class="sd-issue">SHORT BY '+gbp(q.shortfall)+
        '. Increase cash before taking on this salary.</p>':'')+
      (!info.canHire&&!q.shortfall?'<p class="sd-issue">'+esc(info.reason)+
        '. This role or candidate cannot be hired right now.</p>':'')+
      '<button type="button" class="trade-button" data-action="hire-staff" data-id="'+
      esc(c.id)+'"'+(info.canHire?'':' disabled')+'>'+
      (info.canHire?'HIRE '+esc(c.name.toUpperCase())+' · '+gbp(P.HIRING_FEE):
        'CANNOT HIRE · '+esc(info.reason))+'</button>'+
      '<p class="sd-fine">Hiring charges only the onboarding fee now. '+gbp(staffDaily)+
      ' daily wages begin thereafter. Cash is reserved for three days of total payroll, '+
      'existing arrears and outstanding vehicle preparation.</p>'+
      '</div></div></div>';
  }
  function staffDesk(state,P,{mode=null,role='all',selectedId=null}={}){
    const counts=deskCounts(state,P);
    const activeMode=DESK_MODES.includes(mode)?mode:
      state.staff.length?'team':'candidates';
    const f=DESK_ROLES.includes(role)?role:'all';
    const source=activeMode==='team'?state.staff:P.applicants(state.day);
    const filtered=source.filter(person=>f==='all'||person.role===f);
    const chosen=filtered.find(p=>(activeMode==='team'?'e:':'c:')+p.id===selectedId)||
      filtered[0]||null;
    const chosenId=chosen?(activeMode==='team'?'e:':'c:')+chosen.id:null;
    const week=Math.floor((state.day-1)/7);
    const nextRefresh=(week+1)*7+1;
    const quick='<div class="sd-kpis">'+[
      ['EMPLOYEES HIRED',counts.employed+' / '+counts.rolesTotal],
      ['ACTIVE TODAY',String(counts.active)],
      ['DAILY WAGE BILL',gbp(counts.daily)],
      ['CANDIDATES ON MARKET',String(counts.candidates)]
    ].map(([title,value])=>'<div><small>'+title+'</small><strong>'+value+
      '</strong></div>').join('')+'</div>';
    const alert=state.payrollArrears?
      '<div class="sd-cash-alert"><strong>UNPAID WAGES '+gbp(state.payrollArrears)+'</strong>'+
      '<span>Employees are unavailable while payroll arrears remain outstanding.</span></div>':
      state.cash<counts.daily*3&&counts.employed?
      '<div class="sd-cash-alert"><strong>PAYROLL RISK</strong><span>Cash '+gbp(state.cash)+
      ' is less than three days of wages ('+gbp(counts.daily*3)+').</span></div>':'';
    const toolbar='<div class="sd-toolbar"><div class="sd-tabs" role="group" aria-label="Employee or candidate records">'+
      '<button type="button" data-action="staff-desk-mode" data-mode="team" aria-pressed="'+
      String(activeMode==='team')+'">YOUR TEAM <b>'+counts.employed+'</b></button>'+
      '<button type="button" data-action="staff-desk-mode" data-mode="candidates" aria-pressed="'+
      String(activeMode==='candidates')+'">AVAILABLE CANDIDATES <b>'+counts.candidates+'</b></button>'+
      '</div><div class="sd-roles" role="group" aria-label="Filter employment roles">'+
      DESK_ROLES.map(id=>'<button type="button" data-action="staff-desk-role" data-role="'+id+
        '" aria-pressed="'+String(f===id)+'">'+
        (id==='all'?'ALL ROLES':groupName[id])+'</button>').join('')+
      '</div></div>';
    const listing=filtered.length?filtered.map(p=>staffRow(state,P,p,activeMode,p===chosen)).join(''):
      '<div class="sd-no-results">'+(activeMode==='team'?
        'No employees in this role yet. Review candidates to fill the vacancy.':
        'No candidates match this role this week.')+'</div>';
    const body=chosen?(activeMode==='team'?employeeDetail(state,P,chosen):
      candidateDetail(state,P,chosen)):
      '<div class="sd-dossier sd-no-results">No '+(activeMode==='team'?
        'staff records':'applicants')+' to display. Select a different role or tab.</div>';
    const context=activeMode==='team'?
      '<span>ACTIVE TECHNICIANS FREE '+counts.techniciansFree+
      ' · MONTHLY BASE PAY '+gbp(counts.monthly)+'</span>':
      '<span>'+counts.hireable+' AFFORDABLE / ELIGIBLE TO HIRE · REFRESHES DAY '+
      nextRefresh+'</span>';
    return {mode:activeMode,role:f,selectedId:chosenId,counts,
      html:quick+alert+toolbar+
      '<div class="sd-context">'+context+'</div>'+
      '<div class="sd-layout"><aside class="sd-register" aria-label="'+
      (activeMode==='team'?'Current employees':'Candidate shortlist')+'">'+
      '<div class="sd-register-head">'+(activeMode==='team'?'CONTRACTED EMPLOYEES':'WEEKLY RECRUITMENT SHORTLIST')+
      '<span>'+filtered.length+' SHOWN</span></div>'+
      '<div class="sd-register-list">'+listing+'</div></aside>'+body+'</div>'+
      '<details class="sd-policy"><summary>EMPLOYMENT RULES & PAYROLL EXPLANATION</summary>'+
      '<p>Staff join on the following game day. Training takes two days, during which their work stops. '+
      'Base wages are settled daily at approximately 1/30 of the monthly salary. Bonuses and '+
      'provisional notice charges can increase payroll. Employer taxes, pensions, UK contracts '+
      'and statutory notice rules are not simulated. Candidates change every seven game days. '+
      'Hiring is limited by staffing places, role capacity and protected cash.</p></details>'};
  }

  window.MotorTradePeopleView=Object.freeze({applicants,roster,reputation,totals,
    staffDesk,deskCounts,employeeStatus,recruitStatus,DESK_MODES,DESK_ROLES});
})();

monthly-view.js:
'use strict';
/* v0.9.29 compact monthly management report UI. Uses recorded events only. */
(() => {
  const esc=x=>String(x).replace(/[&<>"']/g,c=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',
    maximumFractionDigits:0}).format(n);
  const signed=n=>(n>0?'+':'')+money(n);
  function cell(label,value,detail='',flag=''){
    return '<div class="report-metric '+flag+'"><small>'+esc(label)+'</small>'+
      '<strong>'+esc(value)+'</strong>'+(detail?'<span>'+esc(detail)+'</span>':'')+'</div>';
  }
  function amount(label,value,positive=false){
    return '<div class="report-line"><span>'+esc(label)+'</span><strong'+
      (value<0?' class="report-negative"':positive?' class="report-positive"':'')+'>'+
      money(value)+'</strong></div>';
  }
  function countLine(label,value){
    return '<div class="report-line"><span>'+esc(label)+
      '</span><strong>'+value+'</strong></div>';
  }
  function progress(actual,target,label,asMoney=false){
    const pct=target>0?Math.min(100,Math.round(actual*100/target)):100;
    return '<div class="report-progress"><div class="report-progress-head"><span>'+esc(label)+
      '</span><strong>'+(asMoney?money(actual)+' / '+money(target):actual+' / '+target)+'</strong></div>'+
      '<div class="report-track"><span style="width:'+pct+'%"></span></div></div>';
  }
  function liveGoals(state,M){
    const r=M.statement(state);
    const remaining=Math.max(0,state.monthPlan.endDay-state.day);
    const toGo=Math.max(0,r.targetUnits-r.soldUnits);
    return '<div class="report-teaser"><div><small>MONTH '+r.month+' · '+remaining+
      ' DAYS REMAINING</small><h3>MONTHLY SALES TARGET</h3>'+
      '<p>'+r.soldUnits+' / '+r.targetUnits+' units completed · '+toGo+
      ' still required</p></div><div class="report-teaser-side"><strong>'+
      Math.round(r.soldUnits/Math.max(1,r.targetUnits)*100)+'%</strong>'+
      '<button type="button" data-page="reports" class="secondary-button">OPEN MONTHLY REPORT ↗</button></div></div>';
  }
  function archivePicker(state,chosen){
    const completed=[...state.monthlyReports].reverse();
    return '<div class="report-picker"><button type="button" data-action="select-report" data-month="current"'+
      (chosen==='current'?' aria-current="true"':'')+'>CURRENT MONTH '+state.monthPlan.month+
      '</button>'+completed.map(x=>'<button type="button" data-action="select-report" data-month="'+x.month+'"'+
      (String(x.month)===String(chosen)?' aria-current="true"':'')+'>'+
      'MONTH '+x.month+' · '+(x.targetMet?'TARGET HIT':'TARGET MISSED')+'</button>').join('')+'</div>';
  }
  const nameByCategory={
    auctionPurchases:'Auction vehicle purchases',sellerPurchases:'Direct seller acquisitions',
    partExchangePurchases:'Part-exchange allowances',preparation:'Stock preparation',
    inspections:'Pre-purchase inspections',payroll:'Wages paid',
    commission:'Sales commission paid',recruitment:'Recruitment / onboarding',
    training:'Staff training',staffExit:'Staff exits / notice',other:'Other recorded cash movements',
    premisesPayments:'Rent and utilities paid',premisesInvestment:'Premises capital investment'
  };
  function renderReport(state,M,selected='current'){
    const historical=String(selected)!=='current';
    const chosen=historical?state.monthlyReports.find(x=>String(x.month)===String(selected)):null;
    const r=chosen||M.statement(state);
    const isClosed=!!chosen;
    const currentPlan=state.monthPlan;
    const remaining=isClosed?0:Math.max(0,currentPlan.endDay-state.day);
    const status=isClosed?(r.targetMet?'MONTH CLOSED · TARGET MET':'MONTH CLOSED · TARGET MISSED'):
      r.targetMet?'ON TRACK · TARGET REACHED':'MONTH IN PROGRESS';
    const outcome=r.targetMet?'report-good':'report-risk';
    const historicLabel=r.partial?'PARTIAL RECORD · UPGRADED CAREER':'FULL OPERATING PERIOD';
    const gap=r.targetUnits-r.soldUnits;
    const companyWarning=r.soldUnits>=r.targetUnits&&
      (r.operatingContribution??r.grossMargin)<=0?
      'Sales volume reached, but costs consumed the margin. This does not count as achieving the company goal.':'';
    const reportHeader='<header class="report-heading '+(isClosed?outcome:'')+'">'+
      '<div><small>MONTH '+r.month+' · GAME DAYS '+r.startDay+'–'+r.endDay+
      ' · '+(isClosed?historicLabel:'LIVE BUSINESS POSITION')+'</small>'+
      '<h2>MANAGEMENT REVIEW</h2>'+
      '<p>'+(isClosed?esc(r.managementComment):
        'This is the live position. The result is locked when day '+r.endDay+
        ' finishes. Targets are fixed until the next operating month.')+'</p>'+
      '</div><span>'+status+'</span></header>';
    const badges='<div class="report-metric-grid">'+
      cell('VEHICLES SOLD',String(r.soldUnits),'Target: '+r.targetUnits+' vehicles',
        gap<=0?'report-value-positive':'')+
      cell('RETAIL SALES TURNOVER',money(r.turnover),'Planning guide: '+money(r.targetTurnover))+
      cell('GROSS TRADE MARGIN',money(r.grossMargin),
        'Planning guide: '+money(r.targetMargin),r.grossMargin<0?'report-value-negative':'')+
      cell('AFTER STAFF COSTS',money(r.grossAfterStaff),
        'Before premises rent, utilities and tax',r.grossAfterStaff<0?'report-value-negative':'')+
      cell('OPERATING CONTRIBUTION',money(r.operatingContribution??r.grossAfterStaff),
        'After recorded staff and premises costs · before tax, finance and depreciation',
        (r.operatingContribution??r.grossAfterStaff)<0?'report-value-negative':'')+
      cell('CASH AT END OF PERIOD',money(r.closingCash),'Opening: '+money(r.openingCash))+
      cell('REPUTATION',r.closingReputation+'/100',
        'Starting '+r.startingReputation+'/100')+
      '</div>';
    const targets='<section class="panel-card report-section"><h3>MONTHLY OBJECTIVES</h3>'+
      progress(r.soldUnits,r.targetUnits,'Mandatory dealership unit target')+
      progress(r.turnover,r.targetTurnover,'Sales turnover guidance')+
      progress(Math.max(0,r.grossMargin),r.targetMargin,'Gross trading margin guidance')+
      (companyWarning?'<p class="report-alert">'+companyWarning+'</p>':'')+
      '<p class="report-muted">Target outcome requires the unit count AND a positive operating contribution after staff and premises charges. '+
      'Turnover and margin figures are secondary benchmarks, not additional mandatory gates. '+
      (isClosed?'This target was set at the start of the period.':
      'Targets change for the next month if reputation changes.')+'</p></section>';
    const source=r.ledgerBreakdown;
    const cash='<section class="panel-card report-section"><h3>CASH FLOW & FINANCES</h3>'+
      amount('Opening cash',r.openingCash)+
      amount('Total cash received',r.cashIn,true)+
      amount('Total cash paid',-r.cashOut)+
      amount('Net cash movement',r.netCashChange)+
      amount('Closing cash',r.closingCash,true)+
      '<hr/>'+amount('Retail sales proceeds',source.retailReceipts,true)+
      Object.entries(nameByCategory).map(([key,label])=>
        amount(label,source[key]??0)).join('')+
      '<hr/>'+amount('Vehicle gross trading margin',r.grossMargin)+
      amount('Recorded staff expenses paid',-r.staffCosts)+
      amount('Gross margin less staff costs',r.grossAfterStaff)+
      amount('Premises expenses accrued',-(r.premisesExpense??0))+
      amount('Premises arrears outstanding',r.premisesArrears??0)+
      amount('Operating contribution after premises costs',r.operatingContribution??r.grossAfterStaff)+
      '<p class="report-muted">Gross margin is recognised when a vehicle sells, whereas buying and preparation affect cash immediately. '+
      'Some inspection costs may remain outside realised vehicle margin until stock is sold. '+
      'Recurring premises costs are accrued daily even if unpaid; investment reduces cash but is capital expenditure, not immediate operating expense. These are game management figures, not statutory accounts, taxable profit or a VAT calculation.</p></section>';
    const saleLine='<section class="panel-card report-section"><h3>SALES & PURCHASING</h3>'+
      countLine('Cash retail sales',r.salesModes.cash)+
      countLine('Retail sales with part-exchanges',r.salesModes.partExchange)+
      amount('Acquisition expenditure',r.totalAcquisitions)+
      amount('Preparation spending',r.prepCost)+
      amount('Average gross margin per sold vehicle',r.averageMargin)+
      '<div class="report-highlow"><p><small>HIGHEST MARGIN VEHICLE</small>'+
      esc(r.bestDeal||'No sales yet')+'</p><p><small>LOWEST MARGIN VEHICLE</small>'+
      esc(r.worstDeal||'No sales yet')+'</p></div></section>';
    const stockTable=r.stock.length?r.stock.map(v=>
      '<div class="report-stock-row"><span>'+esc(v.title)+
      '<small>'+esc(v.status.toUpperCase())+' · '+v.age+' DAYS HELD · '+esc(v.source.toUpperCase())+
      '</small></span><strong>'+money(v.cashInvested)+'</strong></div>').join(''):
      '<p class="report-muted">No unsold stock held at this period close.</p>';
    const inventory='<section class="panel-card report-section"><h3>STOCK & WORKING CAPITAL</h3>'+
      countLine('Vehicles on forecourt',r.stockCount)+
      amount('Acquisition / prep cash tied in stock',r.stockCapital)+
      countLine('Cars aged 14+ days',r.agedStock)+
      countLine('Cars awaiting preparation',r.stockAwaitingPrep)+
      (Number.isSafeInteger(r.workshopInProgress)?
        countLine('Active workshop repairs',r.workshopInProgress)+
        countLine('Final quality checks outstanding',r.workshopQualityChecks)+
        countLine('Unassessed or unbooked stock',r.workshopWaiting):
        '<p class="report-muted">Historical report: detailed workshop breakdown not recorded.</p>')+
      (Number.isSafeInteger(r.wholesaleUnits)?
        countLine('Wholesale stock disposals',r.wholesaleUnits)+
        amount('Trading contribution from wholesale exits',r.wholesaleProfit):'')+
      stockTable+'</section>';
    const peopleRows=r.sellers.length?r.sellers.map(s=>
      '<div class="report-staff-row"><div><strong>'+esc(s.name)+'</strong>'+
      '<span>'+(s.employedAtClose?'EMPLOYED':'LEFT DEALERSHIP')+
      (s.exempt?' · SHORT TENURE':'')+'</span></div>'+
      '<div><strong>'+s.sold+' / '+s.unitTarget+'</strong><small>SALES / TARGET</small></div>'+
      '<div><strong>'+money(s.turnover)+'</strong><small>TURNOVER</small></div>'+
      '<div><strong>'+money(s.grossMargin)+'</strong><small>GROSS MARGIN</small></div>'+
      '<span class="report-staff-result">'+(s.exempt?'NOT ASSESSED':s.hit?'TARGET HIT':'TARGET MISSED')+
      '</span></div>').join(''):
      '<p class="report-muted">No employed salesperson had a target in this period. The owner handles customer sales.</p>';
    const staff='<section class="panel-card report-section"><h3>SALES TEAM SCORECARDS</h3>'+
      peopleRows+
      '<p class="report-muted">A salesperson is credited only for deals closed while actively working. '+
      'Training and late recruitment can reduce their individual target. At month end, performance affects employee morale. '+
      'Staff costs are separate from gross vehicle margin.</p></section>';
    const recent=r.customerTrustEvents.length?[...r.customerTrustEvents].reverse().slice(0,10).map(e=>
      '<div class="report-event"><span>DAY '+e.day+'</span>'+
      '<b class="'+(e.delta<0?'report-negative':'report-positive')+'">'+(e.delta>0?'+':'')+e.delta+
      '</b><p>'+esc(e.reason)+'</p></div>').join(''):
      '<p class="report-muted">No recorded reputation changes in this operating period.</p>';
    const trust='<section class="panel-card report-section"><h3>CUSTOMER TRUST & RISKS</h3>'+
      countLine('Reputation opening',r.startingReputation)+
      countLine('Reputation closing',r.closingReputation)+
      amount('Outstanding staff wages / notice',r.payrollArrears)+
      '<h4>RECORDED REPUTATION EVENTS</h4>'+recent+
      '<p class="report-muted">Customer surveys, warranty claims and formal complaints are not simulated yet. '+
      'This report includes only trust signals and financial events that the current game actually records.</p></section>';
    const journey=r.customerJourney;
    const customerSection=journey?
      '<section class="panel-card report-section"><h3>RETAIL CUSTOMER JOURNEY</h3>'+
      countLine('Customer enquiries',journey.enquiries)+
      countLine('Viewings booked',journey.appointments)+
      countLine('Attended viewings',journey.attended)+
      countLine('Customer no-shows',journey.noShows)+
      countLine('Test drives held',journey.testDrives)+
      countLine('Test drives declined',journey.declinedTestDrives)+
      countLine('Agreements reached',journey.agreements)+
      countLine('Deposits received into separate holding',journey.deposits)+
      countLine('Deposits refunded',journey.refunds)+
      (Number.isSafeInteger(journey.retainedDeposits)?
        countLine('Customer deposits partially or fully retained',journey.retainedDeposits)+
        amount('Retention applied against real preparation costs',journey.retainedAmount):'')+
      (Number.isSafeInteger(r.customerPreparationExpense)?
        amount('Customer-specific preparation expenses',r.customerPreparationExpense)+
        amount('Direct costs recovered from cancelled deals',r.cancellationCostRecovery):'')+
      (Number.isSafeInteger(r.customerHoldingAtClose)?
        amount('Customer deposits currently held separately',r.customerHoldingAtClose):'')+
      countLine('Vehicles handed over',journey.completedSales)+
      '<p class="report-muted">Deposits are separate part-payments, not sales on receipt. Buyer withdrawals may lead to cost-based retention; dealer fault refunds are required. Only completed handovers count towards sales targets.</p></section>':
      '<section class="panel-card report-section"><h3>RETAIL CUSTOMER JOURNEY</h3>'+
      '<p class="report-muted">This historical record was created before customer appointment metrics were available.</p></section>';
    const d=r.dealDay;
    const dealDaySection=d?'<section class="panel-card report-section"><h3>MONTH-END DEAL DAY REVIEW</h3>'+
      '<p class="report-muted">Market conditions: <strong>'+esc(d.label)+
      '</strong>. Demand was generated by this month’s fictional market model, not guaranteed.</p>'+
      countLine('Private-seller enquiries offered across five sessions',d.sellerEnquiries)+
      countLine('Retail sales completed on Deal Day',d.retailSales)+
      amount('Retail turnover on Deal Day',d.turnover)+
      amount('Gross trade margin on Deal Day',d.grossMargin)+
      '<p class="report-muted">Available enquiries are not guaranteed purchases. Results depend on which cars you listed, negotiations, available funds and customer demand. A busy month can still be unprofitable.</p></section>':
      '<section class="panel-card report-section"><h3>MONTH-END DEAL DAY REVIEW</h3>'+
      '<p class="report-muted">'+(isClosed?
        'This historical report predates detailed Deal Day market tracking. No figures have been invented.':
        'Deal Day outcomes are not known yet. The completed results will be recorded when the month closes.')+
      '</p></section>';
    const contribution=r.operatingContribution??r.grossAfterStaff;
    const needed=Math.max(0,r.targetUnits-r.soldUnits);
    const flags=[];
    if(needed)flags.push([isClosed?'SALES TARGET MISSED':'SALES REQUIRED',needed+' handover'+(needed===1?'':'s')+(isClosed?' short of the final target':' still needed')]);
    if(contribution<0)flags.push(['OPERATING LOSS',money(contribution)+' after staff and premises']);
    if(r.agedStock)flags.push(['AGEING STOCK',r.agedStock+' vehicle'+(r.agedStock===1?'':'s')+' held for 14+ days']);
    if(r.stockAwaitingPrep)flags.push(['WORKSHOP BACKLOG',r.stockAwaitingPrep+' vehicle'+(r.stockAwaitingPrep===1?'':'s')+' unprepared']);
    if((r.payrollArrears||0)+(r.premisesArrears||0))flags.push(['UNPAID BILLS',
      money((r.payrollArrears||0)+(r.premisesArrears||0))+' in outstanding obligations']);
    const alerts=(flags.length?flags:[['NO IMMEDIATE FLAGS','No flagged exceptions']]).slice(0,4).map(item=>
      '<div class="mr-flag"><strong>'+item[0]+'</strong><span>'+item[1]+'</span></div>').join('');
    const top='<div class="mr-overview"><div class="mr-head"><div><small>MONTH '+r.month+' · DAYS '+
      r.startDay+'–'+r.endDay+' · '+(isClosed?'ARCHIVED RESULT':'LIVE POSITION')+
      '</small><h2>MANAGEMENT REVIEW</h2></div><b>'+status+'</b></div>'+
      '<div class="mr-kpis">'+
      cell('VEHICLES HANDED OVER',r.soldUnits+' / '+r.targetUnits,'Monthly target')+
      cell('OPERATING CONTRIBUTION',money(contribution),'After staff and premises costs',
        contribution<0?'report-value-negative':'report-value-positive')+
      cell(isClosed?'CLOSING CASH':'CURRENT CASH',money(r.closingCash),'Opening '+money(r.openingCash))+
      cell('CASH INVESTED IN STOCK',money(r.stockCapital),r.stockCount+' unsold vehicles')+'</div>'+
      '<div class="mr-focus"><section class="mr-panel"><h3>ARE WE ON TARGET?</h3>'+
      progress(r.soldUnits,r.targetUnits,'Completed handovers')+
      progress(r.turnover,r.targetTurnover,'Turnover guide',true)+
      progress(Math.max(0,r.grossMargin),r.targetMargin,'Gross margin guide',true)+
      '<p>Company success requires enough handovers and positive operating contribution.</p></section>'+
      '<section class="mr-panel"><h3>WHAT NEEDS ATTENTION?</h3>'+alerts+'</section></div>'+      '<div class="mr-mini"><div><small>GROSS TRADE MARGIN</small><strong>'+money(r.grossMargin)+'</strong></div>'+      '<div><small>STOCK AGED 14+ DAYS</small><strong>'+r.agedStock+'</strong></div>'+      '<div><small>RETAIL ENQUIRIES</small><strong>'+(r.customerJourney?r.customerJourney.enquiries:'NOT RECORDED')+'</strong></div>'+      '<div><small>REPUTATION</small><strong>'+r.closingReputation+'/100</strong></div></div></div>';
    const detail=(title,body)=>'<details class="mr-detail"><summary>'+title+
      ' · EXPAND</summary>'+body+'</details>';
    const detailsBody=detail('MONTHLY OBJECTIVES',targets)+detail('CASH FLOW & FINANCES',cash)+
      detail('SALES & PURCHASING',saleLine)+detail('STOCK & WORKING CAPITAL',inventory)+
      detail('SALES TEAM SCORECARDS',staff)+detail('RETAIL CUSTOMER JOURNEY',customerSection)+
      detail('CUSTOMER TRUST & RISKS',trust)+detail('DEAL DAY RESULTS',dealDaySection);
    return archivePicker(state,selected)+top+
      '<details class="mr-records" aria-label="Detailed Management Records">'+
      '<summary class="mr-records-summary"><strong>DETAILED MANAGEMENT RECORDS</strong>'+
      '<span>8 REPORTS · EXPAND</span></summary>'+
      '<div class="mr-records-body"><p>Choose a report below to examine the supporting figures.</p>'+
      '<div class="mr-details">'+detailsBody+'</div></div></details>'+
      '<p class="mr-note">Fictional management figures only; not statutory UK accounts. VAT, tax and some liabilities are not modelled.</p>';
  }
  window.MotorTradeMonthlyView=Object.freeze({renderReport,liveGoals});
})();

events-view.js:
'use strict';
/* v0.9.30 — compact Deal Day, board meeting and management diary screens. */
(() => {
  const esc=x=>String(x).replace(/[&<>"']/g,c=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
  const D=()=>window.MotorTradeEvents;
  function banner(state){
    const d=D();
    if(d.isDealDay(state.day)){
      const p=d.dealSession(state),climate=d.outlook(state);
      return '<div class="event-banner event-deadline-banner"><div><small>FINAL DAY OF MONTH '+d.monthOf(state.day)+
        ' · '+esc(p.time)+' · '+(state.deadlineSession+1)+' OF 5</small>'+
        '<h3>DEAL DAY · '+esc(climate.label)+'</h3>'+
        '<p>Auctions are closed. '+esc(climate.description)+
        ' New enquiries and better terms are never guaranteed. Advance each session to check trading conditions.</p></div>'+
        '<button type="button" class="secondary-button" data-page="events">'+
        (state.deadlineSession>=d.PHASES.length-1?'CLOSE MONTH ↗':'OPEN DEAL DAY ↗')+
        '</button></div>';
    }
    if(d.meetingDue(state)){
      return '<div class="event-banner event-meeting-banner"><div><small>DAY 1 OF MONTH '+
        d.monthOf(state.day)+(state.day===1?' · START-UP BRIEFING':' · ACTION REQUIRED')+
        '</small><h3>MONTHLY MANAGEMENT MEETING</h3><p>'+
        (state.day===1?'Set your opening priorities and review your first sales objective.':
          'Review the last 30 days, your staff and cash position, then choose a new management focus before advancing.')+
        '</p></div><button type="button" class="secondary-button" data-page="events">ENTER MEETING ↗</button></div>';
    }
    const days=30-state.day%30;
    return '<div class="event-banner event-neutral-banner"><div><small>MONTHLY EVENTS</small>'+
      '<h3>NEXT DEAL DAY IN '+days+' GAME DAYS</h3><p>On day '+
      (Math.floor((state.day-1)/30)+1)*30+
      ', a customer-only Deal Day takes place. The result varies: some months may be very quiet, while others are busy. No auctions run that day.</p></div>'+
      '<button type="button" class="secondary-button" data-page="events">VIEW CALENDAR ↗</button></div>';
  }
  function deadline(state){
    const d=D(),p=d.dealSession(state),phase=state.deadlineSession;
    const climate=d.outlook(state);
    const sellerCount=d.leadCount(state.day,
      state.monthPlan.startingReputation,phase,state.name);
    const listed=state.vehicles.filter(x=>x.status==='listed').length;
    const prep=state.vehicles.filter(x=>x.status==='acquired').length;
    const today=state.sold.filter(x=>x.day===state.day);
    const total=today.reduce((sum,x)=>sum+x.price,0);
    const month=state.monthPlan;
    const monthSold=state.sold.filter(x=>x.day>=month.startDay&&x.day<=state.day).length;
    const phases=d.PHASES.map((x,i)=>
      '<div class="eo-phase '+(i===phase?'eo-phase-current':i<phase?'eo-phase-done':'')+'"'+
      (i===phase?' aria-current="step"':'')+'><strong>'+esc(x.time)+
      '</strong><span>'+esc(x.name)+'</span></div>').join('');
    const last=phase===d.PHASES.length-1;
    const next=last?'CLOSE MONTH':'NEXT SESSION';
    return '<div class="eo-desk eo-deal-day">'+
      '<header class="eo-heading"><div><small>MONTH '+d.monthOf(state.day)+
      ' · FINAL TRADING DAY · NO AUCTIONS</small>'+
      '<h2>DEAL DAY</h2><p>'+esc(climate.label)+' · '+esc(climate.description)+'</p></div>'+
      '<div class="eo-heading-status"><span>SESSION '+(phase+1)+' / '+d.PHASES.length+
      '</span><strong>'+esc(p.time)+'</strong><small>'+esc(p.name)+'</small></div></header>'+
      '<div class="eo-timeline" aria-label="Five Deal Day sessions">'+phases+'</div>'+
      '<div class="eo-kpis">'+
      '<div><small>PRIVATE SELLERS THIS SESSION</small><strong>'+sellerCount+'</strong></div>'+
      '<div><small>VEHICLES ADVERTISED</small><strong>'+listed+'</strong></div>'+
      '<div><small>RETAIL HANDOVERS TODAY</small><strong>'+today.length+'</strong></div>'+
      '<div><small>MONTHLY SALES TARGET</small><strong>'+monthSold+' / '+month.unitTarget+'</strong></div>'+
      '</div>'+
      '<div class="eo-session-summary"><strong>TODAY’S RETAIL TURNOVER '+money(total)+'</strong>'+
      '<span>'+prep+' vehicle'+(prep===1?'':'s')+' need preparation · '+
      (sellerCount?'Private-seller enquiries available now':'No private sellers in this session')+
      '</span></div>'+
      '<div class="eo-activities">'+
      '<section class="eo-activity"><div><small>RETAIL OPPORTUNITY</small>'+
      '<h3>SELL TO CUSTOMERS</h3>'+
      '<p>'+(listed?
        'Check buyer interest, negotiate offers and progress any collection-ready deals.':
        'No advertised cars are available for retail enquiries. Prepare and advertise stock first.')+
      '</p></div><button type="button" class="trade-button" data-page="sales">OPEN SALES OFFICE</button></section>'+
      '<section class="eo-activity"><div><small>DIRECT BUYING</small>'+
      '<h3>BUY FROM PRIVATE SELLERS</h3>'+
      '<p>'+(sellerCount?
        sellerCount+' owner '+(sellerCount===1?'enquiry is':'enquiries are')+
        ' available in this session. Check margins, prep costs and capacity.':
        'No seller leads have arrived. Another session may be different.')+
      '</p></div><button type="button" class="trade-button" data-page="auctions">'+
      'OPEN BUYING DESK</button></section></div>'+
      '<div class="eo-next-action"><strong>NEXT: '+next+'</strong>'+
      '<span>Use the top-right '+next+' control. '+
      (last?'The 17:00 session is the final chance to trade before the month closes.':
        'The next session changes the clock, not the game day or daily expenses.')+
      '</span></div>'+
      '<details class="eo-details"><summary>DEAL DAY RULES & SESSION EXPIRY</summary>'+
      '<p>Auctions are closed today. Retail demand and direct-seller enquiries vary: no sales are guaranteed. '+
      'Unresolved offers and seller leads expire when you move to the next session; paid inspection fees are not refunded. '+
      'Cash, repairs and forecourt capacity still matter. The final 17:00 session leads into month-end reporting.</p>'+
      '</details></div>';
  }
  function suggestions(report){
    if(!report)return ['Set a realistic retail price before accepting offers.',
      'Preserve enough cash to repair and advertise your first vehicles.',
      'Avoid hiring more employees than your current sales can support.'];
    const result=[];
    if(report.dealDay?.type==='quiet'||report.dealDay?.type==='subdued')
      result.push('Month-end customer traffic was '+report.dealDay.label.toLowerCase()+
        ' with '+report.dealDay.sellerEnquiries+
        ' private-seller enquiries offered. Do not assume the deadline will always rescue a missed sales target.');
    if(report.customerJourney){
      const j=report.customerJourney;
      if(j.noShows>0)result.push(j.noShows+
        ' customer(s) missed their viewing. Review follow-up procedures and avoid assuming booked appointments will convert.');
      if(j.enquiries>0&&j.completedSales*3<j.enquiries)
        result.push('Only '+j.completedSales+' of '+j.enquiries+
          ' recorded enquiries converted to completed handovers. Examine pricing, test drives and objections.');
      if(j.deposits>j.completedSales)
        result.push('Some customers paid deposits but have not collected. Check reserved stock and pending appointments.');
    }
    if(report.soldUnits<report.targetUnits)
      result.push('Sales volume was '+report.soldUnits+'/'+report.targetUnits+
        '. Review advertised pricing, customer conversions and whether enough cars were prepared.');
    else result.push('Sales volume reached the target of '+report.targetUnits+
      '. Keep quality and margins healthy rather than chasing volume at any cost.');
    if(report.grossAfterStaff<0)
      result.push('Gross vehicle margin after recorded staff costs was '+money(report.grossAfterStaff)+
        '. Consider staffing affordability and buying prices before committing to more costs.');
    else result.push('Gross margin after paid staff expenses was '+money(report.grossAfterStaff)+
      '. Protect cash flow and stock preparation reserves as the business grows.');
    if(report.agedStock>0)result.push(report.agedStock+
      ' vehicle(s) were held for 14 days or more. Review condition, pricing and seller interest.');
    if(report.payrollArrears>0)result.push('Outstanding employee obligations total '+
      money(report.payrollArrears)+'. Resolve these before expansion.');
    if(report.sellers.some(x=>!x.exempt&&!x.hit))
      result.push('Some sales employees missed their individual targets. Review coaching, training and stock availability.');
    if(report.sellers.length===0)
      result.push('No sales employees had a target. You handled the dealership’s retail sales personally.');
    return result.slice(0,6);
  }
  function meeting(state){
    const d=D(),month=d.monthOf(state.day),done=state.meetingHeldMonth===month;
    const previous=state.monthlyReports.at(-1)||null;
    const notes=suggestions(previous);
    const selectedFocus=d.FOCI[state.meetingFocus];
    const metrics=previous?[
      ['PREVIOUS SALES',previous.soldUnits+' / '+previous.targetUnits],
      ['TURNOVER',money(previous.turnover)],
      ['OPERATING CONTRIBUTION',money(previous.operatingContribution??previous.grossAfterStaff)],
      ['CLOSING CASH',money(previous.closingCash)]
    ]:[
      ['NEW MONTH SALES TARGET',String(state.monthPlan.unitTarget)],
      ['CURRENT CASH',money(state.cash)],
      ['REPUTATION',state.reputationScore+' / 100'],
      ['STAFF ON PAYROLL',String(state.staff.length)]
    ];
    const cards=metrics.map(([label,value])=>
      '<div><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong></div>').join('');
    const choices=Object.entries(d.FOCI).map(([id,focus])=>{
      const isSelected=done&&state.meetingFocus===id;
      return '<button type="button" class="eo-focus-choice'+(isSelected?' eo-focus-selected':'')+
        '" data-action="hold-meeting" data-focus="'+id+'"'+(done?' disabled':'')+
        ' aria-pressed="'+String(isSelected)+'">'+
        '<strong>'+esc(focus.label)+'</strong><span>'+esc(focus.description)+'</span>'+
        '<small>'+(isSelected?'SELECTED PRIORITY':done?'NOT SELECTED':'CHOOSE THIS PRIORITY')+'</small></button>';
    }).join('');
    const staff=previous?.sellers.length?previous.sellers.map(x=>
      '<div class="meeting-staff-row"><span>'+esc(x.name)+'</span>'+
      '<strong>'+x.sold+' / '+x.unitTarget+' sold</strong><span>'+
      esc(x.exempt?'EXEMPT':x.hit?'TARGET HIT':'TARGET MISSED')+'</span></div>').join(''):
      '<p class="event-note">No individual sales staff results to review yet.</p>';
    const record=state.meetings.slice(-4).reverse().map(x=>
      '<div class="meeting-minute"><span>MONTH '+x.month+'</span><strong>'+
      esc(d.FOCI[x.focus]?.label||x.focus)+'</strong><span>Previous sales '+
      x.sold+'/'+x.target+'</span></div>').join('');
    return '<div class="eo-desk eo-meeting">'+
      '<header class="eo-heading"><div><small>MONTH '+month+
      ' · FIRST GAME DAY · MANAGEMENT OFFICE</small><h2>BOARD MEETING</h2>'+
      '<p>'+esc(state.name)+' · Review results and set a focus for this month.</p></div>'+
      '<span class="eo-heading-chip '+(done?'eo-completed':'eo-required')+'">'+
      (done?'MEETING COMPLETED':'DECISION REQUIRED')+'</span></header>'+
      '<div class="eo-kpis">'+cards+'</div>'+
      (done?'<div class="eo-confirm"><strong>MEETING COMPLETED.</strong> '+
        'Your monthly priority is '+esc(selectedFocus?.label||'Routine operations')+
        '. This decision is recorded in your career.</div>':
        '<div class="eo-meeting-warning"><strong>ACTION REQUIRED</strong>'+
        '<span>Agree one management priority before advancing beyond the first game day.</span></div>')+
      '<section class="eo-priority"><div class="eo-section-heading"><div><small>MONTH '+month+
      ' STRATEGY</small><h3>AGREE ONE MANAGEMENT PRIORITY</h3></div>'+
      '<span>'+(done?'DECISION LOCKED':'SELECT ONE OPTION')+'</span></div>'+
      '<div class="eo-focus-grid">'+choices+'</div>'+
      '<p>Each priority has a modest, defined effect. It does not create free money or guarantee a sale.</p></section>'+
      '<div class="eo-meeting-sub"><div><small>THIS MONTH’S UNIT TARGET</small>'+
      '<strong>'+state.monthPlan.unitTarget+' COMPLETED HANDOVERS</strong></div>'+
      '<div><small>TURNOVER GUIDANCE</small><strong>'+
      money(state.monthPlan.turnoverTarget)+'</strong></div>'+
      '<div><small>REPUTATION</small><strong>'+state.reputationScore+' / 100</strong></div></div>'+
      '<details class="eo-details"><summary>MANAGEMENT DISCUSSION & PREVIOUS RESULTS</summary>'+
      '<div class="eo-detail-grid">'+
      '<section><h3>MANAGEMENT DISCUSSION</h3><div class="meeting-notes">'+
      notes.map((x,i)=>'<div><b>'+String(i+1).padStart(2,'0')+'</b><p>'+
        esc(x)+'</p></div>').join('')+'</div></section>'+
      '<section><h3>SALES TEAM REVIEW</h3>'+staff+
      '<h3>NEW MONTH’S TARGETS</h3><p>Dealership target: '+state.monthPlan.unitTarget+
      ' handovers with positive operating contribution after staff and premises costs. '+
      'Turnover guidance: '+money(state.monthPlan.turnoverTarget)+'.</p>'+
      '</section></div></details>'+
      (record?'<details class="eo-details"><summary>RECENT MEETING MINUTES</summary>'+
        '<div class="eo-minute-list">'+record+'</div></details>':'')+
      (previous?'<button type="button" class="secondary-button eo-report-link" '+
        'data-page="reports">OPEN PREVIOUS MONTH’S FULL REPORT</button>':'')+
      '</div>';
  }
  function render(state){
    const d=D();
    if(d.isDealDay(state.day))return deadline(state);
    if(d.isMeetingDay(state.day))return meeting(state);
    const month=d.monthOf(state.day);
    const next=month*30,until=next-state.day,meetingDay=next+1;
    const current=state.monthPlan;
    const sold=state.sold.filter(x=>x.day>=current.startDay&&x.day<=state.day).length;
    const listed=state.vehicles.filter(x=>x.status==='listed').length;
    const preparing=state.vehicles.filter(x=>x.status==='acquired').length;
    const focus=state.meetingHeldMonth===month?d.FOCI[state.meetingFocus]:null;
    return '<div class="eo-desk eo-calendar"><header class="eo-heading">'+
      '<div><small>MANAGEMENT DIARY · MONTH '+month+
      '</small><h2>UPCOMING EVENTS</h2>'+
      '<p>Two fixed milestones every 30-game-day operating month.</p></div>'+
      '<span class="eo-heading-chip">NORMAL TRADING</span></header>'+
      '<div class="eo-kpis">'+
      '<div><small>DAYS UNTIL DEAL DAY</small><strong>'+until+'</strong></div>'+
      '<div><small>MONTHLY HANDOVERS</small><strong>'+sold+' / '+current.unitTarget+'</strong></div>'+
      '<div><small>VEHICLES ADVERTISED</small><strong>'+listed+'</strong></div>'+
      '<div><small>CASH BALANCE</small><strong>'+money(state.cash)+'</strong></div>'+
      '</div><div class="eo-calendar-grid">'+
      '<section class="eo-schedule"><div><small>UPCOMING · GAME DAY '+next+'</small>'+
      '<h3>MONTH-END DEAL DAY</h3><strong>FIVE SESSIONS · 09:00–17:00</strong>'+
      '<p>Five sessions from 09:00 to 17:00. Buyers and private sellers may appear, '+
      'but demand is never guaranteed. Auction houses are closed on Deal Day.</p></div>'+
      '<div class="eo-schedule-foot">PREPARE: '+listed+' LISTED · '+
      preparing+' AWAITING PREPARATION</div>'+
      '<button type="button" class="trade-button" data-page="stock">CHECK VEHICLE STOCK</button></section>'+
      '<section class="eo-schedule"><div><small>NEXT MONTH · GAME DAY '+meetingDay+'</small>'+
      '<h3>MONTHLY BOARD MEETING</h3><strong>REVIEW & SET THE NEXT PRIORITY</strong>'+
      '<p>The first day of the next month is for reviewing results and choosing a sales, buying or customer-care focus.</p></div>'+
      '<div class="eo-schedule-foot">CURRENT PRIORITY: '+
      esc(focus?.label||'NOT YET SELECTED')+'</div>'+
      '<button type="button" class="trade-button" data-page="reports">REVIEW MONTHLY REPORT</button></section>'+
      '</div><p class="eo-footnote">The event calendar shows fixed game-day milestones, not a forecast of how many customers will arrive.</p></div>';
  }
  window.MotorTradeEventsView=Object.freeze({banner,render});
})();

workshop-view.js:
'use strict';
/* v0.9.20 — Compact Workshop job desk. All actions use existing engine rules. */
(() => {
  const VC=window.MotorTradeCards, P=window.MotorTradePeople;
  if(!VC||!P)throw Error('Load cards and people before workshop view');
  const esc=VC.esc, cash=VC.money;
  const FILTERS=Object.freeze(['all','action','repair','ready','listed']);
  const stages=['unassessed','quoted','in-progress','quality-check','ready'];
  const labels={unassessed:'ASSESSMENT DUE',quoted:'REPAIR APPROVAL DUE',
    'in-progress':'REPAIRS IN PROGRESS','quality-check':'QUALITY CHECK DUE',ready:'RETAIL READY'};
  const needs=v=>v.status==='acquired'&&
    ['unassessed','quoted','quality-check'].includes(v.workshop?.stage);
  const age=(s,v)=>Math.max(0,s.day-v.acquiredDay);
  function paid(v){return ['in-progress','quality-check'].includes(v.workshop?.stage)?
    Number(v.workshop.repairCost||0):Number(v.prepSpent||0);}
  function summary(s,W){
    const cars=s.vehicles;
    return {count:cars.length,action:cars.filter(needs).length,
      repair:cars.filter(v=>v.workshop?.stage==='in-progress').length,
      qc:cars.filter(v=>v.workshop?.stage==='quality-check').length,
      ready:cars.filter(v=>v.status==='prepared'&&v.workshop?.stage==='ready').length,
      listed:cars.filter(v=>v.status==='listed'&&v.workshop?.stage==='ready').length,
      reserve:W.reserved(s),
      tech:P.activeTeam(s,'technician').length,
      free:P.availableTechnicians(s).length,
      bays:P.technicianLimit(s),
      inHouse:cars.filter(v=>v.workshop?.stage==='in-progress'&&v.workshop.method==='internal').length,
      external:cars.filter(v=>v.workshop?.stage==='in-progress'&&v.workshop.method==='external').length};
  }
  function status(v){
    const stage=v.workshop?.stage||'unassessed';
    if(stage==='ready'&&v.status==='listed')return {label:'ON SALE',tone:'listed'};
    if(stage==='ready'&&v.status==='prepared')return {label:'READY TO ADVERTISE',tone:'ready'};
    return {label:stage==='in-progress'&&v.workshop.paused?'REPAIRS PAUSED':labels[stage]||'CHECK STATUS',
      tone:stage==='ready'?'ready':stage==='in-progress'?'running':needs(v)?'due':'pending'};
  }
  function unit(s,v,selected){
    const k=status(v);
    return '<article class="ws-unit'+(selected?' ws-selected':'')+'">'+
      '<div class="ws-thumb">'+VC.photo(v,'workshop')+'</div>'+
      '<button type="button" class="ws-pick" data-action="select-workshop" data-id="'+v.id+
      '" aria-pressed="'+selected+'"><small>STOCK '+v.id+' · '+esc(v.source.toUpperCase())+
      '</small><strong>'+esc(v.title)+'</strong>'+
      '<span>'+new Intl.NumberFormat('en-GB').format(v.miles)+' MI · '+age(s,v)+' DAYS HELD</span>'+
      '<em class="ws-status ws-status-'+k.tone+'">'+k.label+'</em></button></article>';
  }
  function steps(v){
    const current=Math.max(0,stages.indexOf(v.workshop?.stage));
    return '<div class="ws-steps">'+['ASSESS','APPROVE','REPAIR','QC','READY'].map((x,i)=>
      '<span class="'+(i<current?'done':i===current?'current':'')+'">'+x+'</span>').join('')+'</div>';
  }
  function items(v){
    const p=v.profile||{};
    const seen=v.workshop.stage!=='unassessed'||!!p.inspected;
    const rows=(p.knownRepairs||[]).map(x=>'<div class="ws-repair"><span>'+
      esc(x.item)+'</span><strong>'+cash(x.cost)+'</strong></div>').join('');
    const extra=seen&&p.hiddenFault?
      '<div class="ws-repair ws-fault"><span>'+esc(p.hiddenFault.item)+
      ' · diagnosed defect</span><strong>'+cash(p.hiddenFault.cost)+'</strong></div>':'';
    return '<section><h4>REPAIR REQUIREMENTS</h4>'+rows+extra+
      (!rows?'<p>No itemised information available.</p>':'')+
      (!seen?'<p class="ws-caveat">Further defects may be identified at assessment.</p>':'')+'</section>';
  }
  function costs(v){
    const job=v.workshop;
    const diagnosed=job.stage!=='unassessed'||!!v.profile?.inspected;
    const spent=paid(v),hasBooking=['in-progress','quality-check','ready'].includes(job.stage);
    const difference=hasBooking?spent-v.prepBudget:0;
    // The legacy save records the total booked repair charge, not an itemised
    // adjustment history. Only label a difference as labour saving while the
    // job remains in-house and has no paid QC rectification.
    const confirmedSaving=hasBooking&&job.method==='internal'&&job.reworks===0&&difference<0;
    const variance=hasBooking&&difference!==0?
      '<div class="ws-cost-variance"><span>'+
      (confirmedSaving?'IN-HOUSE LABOUR SAVING':'REPAIR COST ADJUSTMENT')+
      '</span><strong>'+(difference<0?'−':'+')+cash(Math.abs(difference))+'</strong></div>':'';
    const explanation=variance?
      '<p class="ws-cost-explain">'+(confirmedSaving?
        'The in-house booking costs less than the diagnosed repair budget due to technician labour savings.':
        'Booked repair totals can differ from the diagnosed budget because of provider pricing, transfer fees or paid QC rectification.')+
      '</p>':'';
    return '<div class="ws-costs">'+
      '<div><span>ACQUISITION / ASSESSMENT PAID</span><strong>'+cash(v.cost)+'</strong></div>'+
      '<div><span>DIAGNOSED REPAIR REQUIREMENT</span><strong>'+
      (diagnosed?cash(v.prepBudget):'NOT YET ASSESSED')+'</strong></div>'+
      variance+
      '<div><span>REPAIRS PAID / BOOKED</span><strong>'+cash(spent)+'</strong></div>'+
      '<div class="ws-cost-total"><span>CAPITAL INVESTED</span><strong>'+cash(v.cost+spent)+'</strong></div>'+
      '</div>'+explanation;
  }
  function quote(s,W,v,mode){
    const q=W.quote(s,v,mode);
    const occupied=mode==='external'&&s.vehicles.filter(x=>x.id!==v.id&&
      x.workshop?.stage==='in-progress'&&x.workshop.method==='external').length>=2;
    const cannot=!q||occupied||q.cost>s.cash-W.reserved(s,v.id);
    const reason=!q?'No free technician or bay':occupied?'Both external slots occupied':
      q.cost>s.cash-W.reserved(s,v.id)?'Insufficient unreserved cash':'';
    return '<div class="ws-quote"><div class="ws-quote-head"><strong>'+
      (mode==='internal'?'IN-HOUSE TECHNICIAN':'EXTERNAL GARAGE')+'</strong><b>'+
      (q?cash(q.cost):'UNAVAILABLE')+'</b></div>'+
      (q?'<span>'+q.duration+' DAYS · '+q.partsDelay+' PARTS-WAIT DAYS</span><small>'+
        esc(q.provider)+'</small>'+
        (q.saving>0?'<small class="ws-savings">IN-HOUSE LABOUR SAVING '+cash(q.saving)+'</small>':'')+
        (q.supplement>0?'<small>EXTERNAL GARAGE UPLIFT '+cash(q.supplement)+'</small>':''):'')+
      (cannot?'<p class="ws-issue">'+esc(reason)+'</p>':'')+
      '<button type="button" class="trade-button" data-action="start-workshop" data-id="'+v.id+
      '" data-method="'+mode+'"'+(cannot?' disabled':'')+'>BOOK '+
      (mode==='internal'?'IN-HOUSE':'EXTERNAL')+' REPAIR</button></div>';
  }
  function actions(s,W,v){
    const j=v.workshop,phase=j.stage;
    if(phase==='unassessed'){
      const fee=P.active(s,'technician')?30:55;
      const can=s.cash>=W.reserved(s)+fee;
      return '<div class="ws-action"><h4>NEXT / ASSESS VEHICLE</h4>'+
        '<p>Confirm the repair requirement. The assessment costs '+cash(fee)+
        ' and is added to the acquisition cost.</p>'+
        (!can?'<p class="ws-issue">Insufficient unreserved cash for assessment.</p>':'')+
        '<button type="button" class="trade-button" data-action="assess-workshop" data-id="'+v.id+
        '"'+(!can?' disabled':'')+'>AUTHORISE ASSESSMENT · '+cash(fee)+'</button></div>';
    }
    if(phase==='quoted')return '<div class="ws-action"><h4>NEXT / APPROVE REPAIRS</h4>'+
      '<p>Choose a provider. Booking charges cash now and repairs take game days.</p>'+
      '<div class="ws-quotes">'+quote(s,W,v,'internal')+quote(s,W,v,'external')+'</div></div>';
    if(phase==='in-progress'){
      const provider=j.method==='internal'?
        (s.staff.find(x=>x.id===j.technicianId)?.name||'Technician unavailable'):
        'Independent external garage';
      return '<div class="ws-action"><h4>'+ (j.paused?'REPAIRS PAUSED':'REPAIRS BOOKED') +'</h4>'+
        '<div class="ws-progress"><div><small>PROVIDER</small><strong>'+esc(provider)+'</strong></div>'+
        '<div><small>REMAINING</small><strong>'+j.remainingDays+' GAME DAYS</strong></div>'+
        '<div><small>CHARGED</small><strong>'+cash(j.repairCost)+'</strong></div></div>'+
        '<p>'+(j.paused?'Assigned technician unavailable. Return them to duty or transfer this job.':
          'Advance game days for repairs to finish. Quality control is mandatory afterward.')+'</p>'+
        (j.method==='internal'?(()=>{
          const outside=s.vehicles.filter(x=>x.id!==v.id&&
            x.workshop?.stage==='in-progress'&&x.workshop.method==='external').length;
          const full=outside>=2,affordable=s.cash>=W.reserved(s)+125;
          return (full?'<p class="ws-issue">EXTERNAL GARAGES FULL (2/2). WAIT FOR A SLOT.</p>':'')+
            (!full&&!affordable?'<p class="ws-issue">INSUFFICIENT UNRESERVED CASH FOR £125 TRANSFER.</p>':'')+
            '<button type="button" class="trade-button trade-button-secondary" '+
            'data-action="outsource-workshop" data-id="'+v.id+'"'+
            (full||!affordable?' disabled':'')+'>TRANSFER TO EXTERNAL GARAGE · £125</button>';
        })():'')+'</div>';
    }
    if(phase==='quality-check')return '<div class="ws-action"><h4>NEXT / FINAL QUALITY CHECK</h4>'+
      '<p>Repairs are complete. QC must pass before advertising; failure may require another paid repair day.</p>'+
      '<button type="button" class="trade-button" data-action="finish-workshop" data-id="'+v.id+
      '">PERFORM FINAL QUALITY CHECK</button></div>';
    if(v.status==='listed')return '<div class="ws-action ws-ready"><h4>QC PASSED / ON SALE</h4>'+
      '<p>Quality control passed on day '+(j.completedDay??'—')+'. This vehicle is already advertised. Handle customer interest in the Sales Office.</p>'+
      '<button type="button" class="trade-button" data-page="sales" data-id="'+v.id+
      '">OPEN SALES OFFICE</button></div>';
    return '<div class="ws-action ws-ready"><h4>QC PASSED / READY TO ADVERTISE</h4>'+
      '<p>Completed on day '+(j.completedDay??'—')+'. Repairs charged '+cash(v.prepSpent)+
      '. Set an asking price in Vehicle Stock.</p>'+
      '<button type="button" class="trade-button" data-page="stock" data-id="'+v.id+
      '">VIEW VEHICLE STOCK</button></div>';
  }
  function disposal(v){
    if(v.status!=='acquired'||!['unassessed','quoted'].includes(v.workshop.stage))return '';
    const bid=window.MotorTradeEngine.wholesaleOffer(v);
    return '<details class="ws-disposal"><summary>TRADE DISPOSAL / CUT LOSSES</summary>'+
      '<p>Fictional trade offer '+cash(bid)+'. Selling now frees a space but can realise a loss.</p>'+
      '<button class="trade-button trade-button-outline" type="button" data-action="dispose-workshop" data-id="'+
      v.id+'">SELL TO TRADE · '+cash(bid)+'</button></details>';
  }
  function dossier(s,W,v){
    const k=status(v);
    return '<article class="ws-file"><div class="ws-file-head"><div><small>WORK ORDER · STOCK '+v.id+
      '</small><h3>'+esc(v.title)+'</h3></div><span class="ws-status ws-status-'+k.tone+'">'+k.label+
      '</span></div>'+steps(v)+
      '<div class="ws-detail"><div class="ws-detail-car">'+
      '<div class="ws-vehicle"><div class="ws-photo">'+VC.photo(v,'workshop')+'</div>'+
      '<div><small>GRADE '+esc(v.profile?.grade??'—')+' · '+esc(v.fuel)+' · '+esc(v.gearbox)+
      '</small><strong>'+new Intl.NumberFormat('en-GB').format(v.miles)+' MI</strong>'+
      '<span>'+age(s,v)+' DAYS HELD · '+esc(v.color||'UNKNOWN COLOUR')+'</span></div></div>'+
      items(v)+'<p class="ws-caveat">Simulated assessment and QC are not a real MOT or roadworthiness certificate.</p>'+
      '</div><div class="ws-detail-control">'+actions(s,W,v)+
      '<h4>COST CONTROL</h4>'+costs(v)+disposal(v)+'</div></div></article>';
  }
  function render(s,W,{filter='all',selectedId=null}={}){
    const q=summary(s,W),f=FILTERS.includes(filter)?filter:'all';
    const kpi='<div class="ws-kpis">'+[
      ['ACTION REQUIRED',q.action],['REPAIRS RUNNING',q.repair],
      ['QUALITY CHECK DUE',q.qc],['READY TO ADVERTISE',q.ready],['ON SALE',q.listed]
    ].map(([name,num])=>'<div><small>'+name+'</small><strong>'+num+'</strong></div>').join('')+
      '</div><div class="ws-capacity"><span>TECHNICIANS '+q.tech+' ACTIVE / '+q.free+' FREE · IN-HOUSE '+
      q.inHouse+'/'+q.bays+' BAYS</span><span>EXTERNAL GARAGES '+q.external+'/2</span>'+
      '<span>REPAIR FUNDS RESERVED '+cash(q.reserve)+'</span></div>';
    if(!s.vehicles.length)return {selectedId:null,html:kpi+
      '<div class="trade-empty ws-empty"><h2>NO VEHICLES TO PREPARE.</h2>'+
      '<p>Buy a vehicle at the Buying Desk or Auction Hall to create a workshop job.</p>'+
      '<button type="button" class="trade-button" data-page="auctions">OPEN BUYING DESK</button></div>'};
    const filters=[['all','ALL JOBS',q.count],['action','ACTION DUE',q.action],
      ['repair','IN REPAIR',q.repair],['ready','READY TO ADVERTISE',q.ready],
      ['listed','ON SALE',q.listed]];
    const toolbar='<div class="ws-toolbar"><strong>WORKSHOP JOB REGISTER</strong>'+
      '<div class="ws-filters" role="group" aria-label="Filter workshop jobs">'+filters.map(([key,label,n])=>
      '<button type="button" data-action="filter-workshop" data-filter="'+key+
      '" aria-pressed="'+(f===key)+'">'+label+' <b>'+n+'</b></button>').join('')+'</div></div>';
    const cars=s.vehicles.filter(v=>f==='all'||(f==='action'?needs(v):
      f==='repair'?v.workshop?.stage==='in-progress':
      f==='ready'?v.status==='prepared'&&v.workshop?.stage==='ready':
      v.status==='listed'&&v.workshop?.stage==='ready'))
      .slice().sort((a,b)=>{
        const pa=needs(a)?0:a.workshop.stage==='in-progress'?1:2;
        const pb=needs(b)?0:b.workshop.stage==='in-progress'?1:2;
        return pa-pb||a.acquiredDay-b.acquiredDay||a.id-b.id;
      });
    const chosen=cars.find(v=>v.id===selectedId)||cars[0]||null;
    const list=cars.length?cars.map(v=>unit(s,v,v.id===chosen?.id)).join(''):
      '<p class="ws-no-results">No jobs in this category. Select another filter.</p>';
    return {selectedId:chosen?.id??null,html:kpi+toolbar+
      '<div class="ws-layout"><aside class="ws-register"><header>JOBS <span>'+cars.length+
      ' SHOWN</span></header>'+list+'</aside>'+
      (chosen?dossier(s,W,chosen):'<div class="ws-file ws-no-results">No job selected.</div>')+
      '</div><p class="ws-footnote">Jobs take game days. Repair charges, reserves and staffing come from your saved career.</p>'};
  }
  window.MotorTradeWorkshopView=Object.freeze({render,summary,paid,FILTERS});
})();

customers-view.js:
'use strict';
/* The Motor Trade v0.9.25 — Sales Office final polish. */
(() => {
  const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const cash=x=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',
    maximumFractionDigits:0}).format(x);
  const VC=window.MotorTradeCards;
  if(!VC)throw new Error('Load vehicle-cards.js before customers-view.js');
  const statuses={
    enquiry:'NEW ENQUIRY',booked:'APPOINTMENT BOOKED',
    arrived:'CUSTOMER ON SITE',discussing:'NEGOTIATION IN PROGRESS',
    agreed:'TERMS AGREED',reserved:'DEPOSIT HELD / COLLECTION BOOKED',
    collectable:'READY FOR COLLECTION',lost:'CUSTOMER LOST'
  };
  function actions(state,vehicle,E){
    const C=E.customers,c=C.caseFor(state,vehicle.id),id=vehicle.id;
    if(!c){
      const interest=C.demand(state,vehicle);
      return interest?
        '<div class="sales-case-highlight"><strong>CONTACT POTENTIAL BUYER</strong>'+
        '<p>A potential buyer is interested in this vehicle. Contact them to log an enquiry and establish their requirements.</p>'+
        '<button type="button" class="trade-button" data-action="open-customer" data-id="'+id+
        '">CONTACT BUYER / OPEN ENQUIRY →</button></div>':
        '<div class="sales-case-quiet"><strong>NO ACTIVE RETAIL ENQUIRIES</strong>'+
        '<p>No customer wants to proceed with this particular car right now. Interest may change on another game day'+
        (E.events.isDealDay(state.day)?' or Deal Day session':'')+
        '. Review price and stock age; nothing is guaranteed.</p></div>';
    }
    const rep=E.people.salesRep(state,c);
    const who='<div class="sales-customer-meta"><span>'+esc(c.name)+'</span>'+ 
      '<span>'+esc(c.channel)+'</span><span>'+esc(statuses[c.status])+'</span>'+ 
      '<span>SALES ADVISER: '+esc(rep?.name||'Owner-managed')+
      (rep?' · '+Math.round(E.people.salesProfile(rep).commissionRate*100)+'% GROSS MARGIN COMMISSION':'')+
      '</span></div>';
    const cancel='<button type="button" class="trade-button trade-button-outline" data-action="cancel-customer" data-id="'+id+
      '">DEALERSHIP CANCELS / REFUND</button>';
    const buyerWithdraw='<button type="button" class="trade-button trade-button-secondary" data-action="customer-withdrawal" data-id="'+id+
      '">CUSTOMER CHANGES MIND</button>';
    let body='';
    switch(c.status){
      case 'enquiry':
        body='<p>'+esc(c.name)+' has enquired about this car. They have not inspected or test driven it yet.'+
          ' Book a viewing within 48 game-hours. No deposit means the vehicle remains for sale.</p>'+ 
          '<button type="button" class="trade-button" data-action="book-customer" data-id="'+id+
          '">BOOK VIEWING →</button> '+cancel;
        break;
      case 'booked':
        body='<div class="sales-case-highlight"><strong>VIEWING WITHIN 48 GAME-HOURS · NO DEPOSIT</strong>'+ 
          '<p>'+esc(c.name)+' is due on <strong>GAME DAY '+c.appointmentDay+
          '</strong>. This is an appointment, not a reservation: the car stays for sale until someone pays a deposit or completes handover.</p>'+ 
          (C.competingInterest(state,id)?'<button type="button" class="trade-button" data-action="competing-customer" data-id="'+id+
          '">SERVE ANOTHER BUYER NOW →</button><p>Another interested buyer can view and test drive now. If they do not purchase, the first booking is preserved.</p>':
          '<p>No second buyer is ready right now. The original customer can still attend their appointment.</p>')+
          '</div>'+cancel;
        break;
      case 'arrived':
        body='<p>Customer has arrived to inspect the vehicle. A test drive can reveal objections that prevent a sale.'+
          (c.standby?' Another customer has an earlier unsecured booking; it is preserved unless this buyer purchases or pays a deposit.':'')+'</p>'+ 
          '<button type="button" class="trade-button" data-action="test-drive" data-id="'+id+
          '">OFFER TEST DRIVE →</button> '+cancel;
        break;
      case 'discussing':{
        const b=E.buyers(vehicle,state);
        if(!b){body='<p>Customer is not currently available to negotiate. Try a different time.</p>';break;}
        const cashUI='<section class="sales-offer-mode"><h4>CASH PURCHASE</h4>'+
          '<small>CUSTOMER INITIAL / REVISED OFFER</small><strong>'+cash(b.cashOffer)+'</strong>'+
          '<p>Indicative maximum budget '+cash(b.cashLimit)+'. Increasing your counter risks a rejection or walkaway.</p>'+
          '<div class="trade-action-row"><button class="trade-button trade-button-secondary" type="button" data-action="counter-sale" data-id="'+id+
          '"'+(c.counters>=2?' disabled':'')+'>COUNTER +£150</button>'+
          '<button class="trade-button" type="button" data-action="agree-cash" data-id="'+id+
          '">AGREE CASH PRICE</button></div></section>';
        const part=b.exchange?'<section class="sales-offer-mode"><h4>PART-EXCHANGE PROPOSAL</h4>'+
          '<small>CUSTOMER OFFER FOR YOUR CAR</small><strong>'+cash(b.pxOffer)+'</strong>'+
          VC.mini(b.exchange,'part-ex')+
          '<p>Trade-in: '+esc(b.exchange.title)+' · '+cash(b.exchange.retail)+
          ' indicative retail · '+cash(b.exchange.prep)+' original prep estimate.</p>'+
          '<label for="px-allowance-'+id+'">AGREED PART-EX ALLOWANCE (£)</label>'+
          '<input id="px-allowance-'+id+'" class="trade-input" type="number" inputmode="numeric" min="'+
          b.exchange.floor+'" max="'+b.exchange.ask+'" value="'+b.exchange.ask+'" step="25">'+
          '<p>Allowance range '+cash(b.exchange.floor)+'–'+cash(b.exchange.ask)+
          '. Incoming car requires its own preparation and takes one forecourt space.</p>'+
          '<button type="button" class="trade-button" data-action="agree-part-ex" data-id="'+id+
          '">AGREE PART-EX TERMS</button></section>':
          '<p class="so-no-part-ex">NO PART-EXCHANGE OFFERED · Cash purchase only for this customer.</p>';
        body='<p>The test drive went well. Discuss a realistic cash price or trade-in allowance; there is no completed sale until handover.'+
          (c.standby?' The earlier unsecured appointment stays open until a deposit or completed sale.':'')+'</p>'+ 
          '<div class="sales-offer-modes">'+cashUI+part+'</div>'+cancel;
        break;
      }
      case 'agreed':
        body='<div class="sales-case-highlight"><h4>AGREEMENT REACHED</h4>'+
          '<p>Agreed '+esc(c.preferredMode==='part-ex'?'part-exchange':'cash')+
          ' sale at <strong>'+cash(c.price)+'</strong>'+
          (c.exchange?' with a '+cash(c.allowance)+' allowance for '+esc(c.exchange.title):'')+
          '. No cash has been recognised as a retail sale yet.</p>'+
          '<div class="trade-action-row"><button type="button" class="trade-button" data-action="handover-customer" data-mode="'+
          c.preferredMode+'" data-id="'+id+'">COMPLETE HANDOVER</button>'+
          '<button type="button" class="trade-button trade-button-secondary" data-action="deposit-customer" data-id="'+id+
          '">TAKE £250 DEPOSIT / LATER COLLECTION</button></div>'+
          '<p class="sales-deposit-terms">The reservation funds are held separately. Customer withdrawal may cause fair cost-based retention, while dealership fault requires a refund.</p></div>'+cancel;
        break;
      case 'reserved':
        body='<div class="sales-case-highlight"><h4>£250 CUSTOMER DEPOSIT RECEIVED</h4>'+
          '<div class="sales-payment-breakdown">'+
          '<span>Agreed price</span><strong>'+cash(c.price)+'</strong>'+
          '<span>Part-exchange allowance</span><strong>'+cash(c.allowance||0)+'</strong>'+
          '<span>Already paid</span><strong>'+cash(c.held)+'</strong>'+
          '<span>BALANCE DUE AT COLLECTION</span><strong>'+cash(C.balanceDue(c))+'</strong></div>'+
          '<p><strong>COLLECTION: GAME DAY '+c.collectionDay+'</strong> · Customer-specific preparation charged: '+cash(c.prepCost||0)+'.</p>'+
          '<p>The £250 deposit is held separately, not recognised as a vehicle sale. Buyer withdrawal can incur fair retention for recorded costs; dealership fault requires a refund.</p></div>'+buyerWithdraw+' '+cancel;
        break;
      case 'collectable':
        body='<div class="sales-case-highlight"><h4>CUSTOMER READY TO COLLECT</h4>'+
          '<div class="sales-payment-breakdown">'+
          '<span>Agreed sale price</span><strong>'+cash(c.price)+'</strong>'+
          '<span>Part-exchange allowance</span><strong>'+cash(c.allowance||0)+'</strong>'+
          '<span>Deposit already paid</span><strong>'+cash(c.held)+'</strong>'+
          '<span>BALANCE TO COLLECT TODAY</span><strong>'+cash(C.balanceDue(c))+'</strong></div>'+
          '<p><strong>COLLECTION DUE: DAY '+c.collectionDay+'</strong> · Complete handover within five game days. Collect only the outstanding balance; the held deposit is applied once.</p>'+
          '<button type="button" class="trade-button" data-action="handover-customer" data-mode="'+
          c.preferredMode+'" data-id="'+id+'">COLLECT '+cash(C.balanceDue(c))+' / HANDOVER</button></div>'+
          buyerWithdraw+' '+cancel;
        break;
      case 'lost':
        body='<div class="trade-inline-feedback trade-feedback-warning"><strong>CUSTOMER DID NOT PROCEED</strong>'+
          '<p>'+esc(c.reason||'No deal agreed.')+'</p>'+
          '<p>The next game day'+(E.events.isDealDay(state.day)?' or Deal Day session':'')+
          ' may produce another enquiry, but not automatically.</p></div>';
        break;
    }
    return who+'<div class="sales-case-content">'+body+'</div>';
  }
  const FILTERS=Object.freeze(['all','action','appointments','deposits']);
  const STEP=['LEAD / ENQUIRY','VIEWING','TEST DRIVE','AGREEMENT','COLLECTION'];
  function lead(state,v,E){
    const c=E.customers.caseFor(state,v.id),available=!c&&E.customers.demand(state,v);
    const title=c?statuses[c.status]||'CUSTOMER CASE':
      available?'BUYER INTEREST TO CONTACT':'AWAITING BUYER INTEREST';
    const step=!c?(available?0:-1):{
      enquiry:0,booked:1,arrived:1,discussing:2,agreed:3,
      reserved:4,collectable:4,lost:-1
    }[c.status]??-1;
    const actionable=available||!!c&&
      ['enquiry','arrived','discussing','agreed','collectable'].includes(c.status);
    return {c,available,title,step,actionable,
      tone:c?.status==='lost'?'lost':
        ['reserved','collectable'].includes(c?.status)?'deposit':
        actionable?'action':c?.status==='booked'?'appointment':'quiet'};
  }
  function snapshot(state,E){
    const C=E.customers,listed=state.vehicles.filter(v=>v.status==='listed');
    const rows=listed.map(v=>({vehicle:v,caseData:lead(state,v,E)}));
    const live=rows.filter(r=>r.caseData.c&&r.caseData.c.status!=='lost').length;
    const appointments=rows.filter(r=>r.caseData.c?.status==='booked').length;
    const deposits=rows.filter(r=>r.caseData.c?.held>0).length;
    return {rows,live,appointments,deposits,
      attention:rows.filter(r=>r.caseData.actionable).length,
      held:C.heldDeposits(state)};
  }
  function unit(state,entry,selected){
    const v=entry.vehicle,k=entry.caseData;
    const days=Math.max(0,state.day-v.listedDay);
    const c=k.c;
    const due=c?.status==='booked'&&c.appointmentDay!==null?' · VIEWING DAY '+c.appointmentDay:
      ['reserved','collectable'].includes(c?.status)&&c.collectionDay!==null?
        ' · COLLECTION DAY '+c.collectionDay:'';
    return '<article class="so-unit'+(selected?' so-unit-active':'')+'">'+
      '<div class="so-thumb">'+VC.photo(v,'stock')+'</div>'+
      '<button type="button" class="so-pick" data-action="select-sales" data-id="'+v.id+
      '" aria-pressed="'+String(selected)+'"><small>STOCK '+v.id+
      ' · '+days+' DAYS ADVERTISED</small><strong>'+esc(v.title)+'</strong>'+
      '<span>ASKING '+cash(v.asking)+due+'</span>'+
      '<em class="so-status so-status-'+k.tone+'">'+esc(k.title)+'</em></button></article>';
  }
  function progress(info){
    return '<div class="so-flow" aria-label="Sales progression">'+STEP.map((name,i)=>
      '<span class="'+(i<info.step?'so-flow-done':i===info.step?'so-flow-current':'')+'"'+
      (i===info.step?' aria-current="step"':'')+'>'+name+'</span>').join('')+'</div>';
  }
  function details(state,E,entry){
    const v=entry.vehicle,leadInfo=entry.caseData,c=leadInfo.c;
    const invested=v.cost+v.prepSpent;
    const indicative=v.profile?.likelySale??v.retail;
    const days=Math.max(0,state.day-v.listedDay);
    return '<article class="so-file" aria-label="Selected sales case">'+
      '<header class="so-file-head"><div><small>RETAIL FILE · STOCK '+v.id+
      (c?' · '+esc(c.channel):' · ADVERTISED VEHICLE')+'</small>'+
      '<h3>'+esc(v.title)+'</h3></div>'+
      '<span class="so-status so-status-'+leadInfo.tone+'">'+esc(leadInfo.title)+'</span></header>'+
      progress(leadInfo)+
      '<div class="so-file-grid"><section class="so-car">'+
      '<div class="so-vehicle-intro"><div class="so-car-photo">'+VC.photo(v,'stock')+'</div>'+
      '<div class="so-specs"><span>'+new Intl.NumberFormat('en-GB').format(v.miles)+
      ' MILES</span><span>'+esc(v.fuel)+' · '+esc(v.gearbox)+'</span>'+
      '<small>'+esc(v.color||'COLOUR NOT RECORDED')+' · '+days+
      ' DAYS ADVERTISED</small></div></div>'+
      '<h4>VEHICLE FINANCIALS</h4><div class="so-figures">'+
      '<div><span>ADVERTISED PRICE</span><strong>'+cash(v.asking)+'</strong></div>'+
      '<div><span>ACQUISITION + PREPARATION</span><strong>'+cash(invested)+'</strong></div>'+
      '<div><span>LIKELY ACHIEVED SALE</span><strong>'+cash(indicative)+'</strong></div>'+
      (c?.price!==null&&c?.price!==undefined?
        '<div class="so-figures-strong"><span>AGREED SALE PRICE</span><strong>'+cash(c.price)+'</strong></div>':'')+
      '</div><p class="so-caveat">Valuations are fictional. An agreed price is not a completed sale until handover.</p>'+
      '</section><section class="so-customer"><div class="so-customer-heading">'+
      '<div><small>SALES CASE MANAGEMENT</small><h4>NEXT CUSTOMER ACTION</h4></div>'+
      (c?'<span>'+esc(c.name)+'</span>':'')+'</div>'+
      actions(state,v,E)+'</section></div></article>';
  }
  function history(state){
    if(!state.sold.length)return '';
    return '<details class="so-history"><summary>RECENT COMPLETED HANDOVERS · '+
      state.sold.length+' SALES <span>VIEW HISTORY</span></summary>'+
      '<div class="so-history-list">'+state.sold.slice(-5).reverse().map(v=>
        '<div class="so-history-row"><div><strong>'+esc(v.title)+'</strong>'+
        '<small>DAY '+v.day+' · '+esc(v.color||'COLOUR NOT RECORDED')+'</small></div>'+
        '<span>SALE '+cash(v.price)+'</span><span>GROSS '+cash(v.profit)+'</span></div>'
      ).join('')+'</div></details>';
  }
  function render(state,E,{selectedId=null,filter='all'}={}){
    const s=snapshot(state,E),f=FILTERS.includes(filter)?filter:'all';
    const stats=E.customers.stats(state,state.monthPlan.startDay,state.day);
    const top='<div class="so-kpis">'+[
      ['ADVERTISED VEHICLES',s.rows.length],['ACTIVE CUSTOMER CASES',s.live],
      ['ACTION REQUIRED',s.attention],['HELD DEPOSITS',cash(s.held)]
    ].map(([name,value])=>
      '<div><small>'+name+'</small><strong>'+value+'</strong></div>').join('')+'</div>'+
      '<div class="so-activity">THIS MONTH · '+stats.enquiries+' RECORDED ENQUIRIES · '+
      stats.appointments+' VIEWINGS BOOKED · '+stats.testDrives+' TEST DRIVES · '+
      stats.completedSales+' COMPLETED HANDOVERS</div>';
    if(!s.rows.length)return {selectedId:null,html:top+
      '<div class="trade-empty so-empty"><h2>NO CARS ADVERTISED.</h2>'+
      '<p>Prepare a vehicle, pass workshop quality control, then set the retail price in Vehicle Stock.</p>'+
      '<button type="button" class="trade-button" data-page="stock">OPEN VEHICLE STOCK</button></div>'+
      history(state)};
    const filterDefs=[['all','ALL VEHICLES',s.rows.length],
      ['action','ACTION REQUIRED',s.attention],
      ['appointments','APPOINTMENTS',s.appointments],
      ['deposits','DEPOSIT HELD',s.deposits]];
    const toolbar='<div class="so-toolbar"><strong>RETAIL CASE REGISTER</strong>'+
      '<div class="so-filters" role="group" aria-label="Filter retail sales cases">'+
      filterDefs.map(([key,label,n])=>
        '<button type="button" data-action="filter-sales" data-filter="'+key+
        '" aria-pressed="'+String(key===f)+'">'+label+' <b>'+n+'</b></button>').join('')+'</div></div>';
    const filtered=s.rows.filter(r=>f==='all'||(f==='action'?r.caseData.actionable:
      f==='appointments'?r.caseData.c?.status==='booked':
      r.caseData.c?.held>0)).slice().sort((a,b)=>{
        const p=x=>x.caseData.actionable?0:x.caseData.c?.held>0?1:
          x.caseData.c?.status==='booked'?2:3;
        return p(a)-p(b)||a.vehicle.listedDay-b.vehicle.listedDay||
          a.vehicle.id-b.vehicle.id;
      });
    const selected=filtered.find(r=>r.vehicle.id===selectedId)||filtered[0]||null;
    const list=filtered.length?filtered.map(r=>unit(state,r,r.vehicle.id===selected?.vehicle.id)).join(''):
      '<p class="so-empty-filter">No vehicles match this filter. Select All Vehicles to review the full register.</p>';
    const deadline=E.events.isDealDay(state.day)?
      '<div class="so-deal-day">DEAL DAY · '+esc(E.events.outlook(state).label)+
      ' · '+esc(E.events.dealSession(state).time)+
      ' — Walk-in enquiries can change between sessions.</div>':'';
    return {selectedId:selected?.vehicle.id??null,html:top+deadline+toolbar+
      '<div class="so-layout"><aside class="so-register" aria-label="Advertised vehicle and customer cases">'+
      '<header>ADVERTISED STOCK <span>'+filtered.length+' SHOWN</span></header>'+
      '<div class="so-register-list">'+list+'</div></aside>'+
      (selected?details(state,E,selected):
        '<div class="so-file so-empty-filter">No selected customer case.</div>')+'</div>'+
      history(state)};
  }
  window.MotorTradeCustomersView=Object.freeze({render,FILTERS,lead,snapshot});
})();

premises-view.js:
'use strict';
/* v0.9.35 — My Dealership compact owner HQ and facility investment desk.
 * Every amount is derived from the saved game state and existing economic
 * rules. Rendering never applies an upgrade or changes a saved career.
 */
(() => {
  const cash=n=>new Intl.NumberFormat('en-GB',{
    style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
  const nfmt=n=>new Intl.NumberFormat('en-GB').format(n);
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[c]));
  const label=(a,b,note='')=>
    '<div class="hq-metric"><small>'+a+'</small><strong>'+b+
    '</strong><span>'+note+'</span></div>';
  const line=(a,b,extra='')=>
    '<div class="hq-cost-line'+extra+'"><span>'+a+'</span><strong>'+b+'</strong></div>';
  function figures(state,site){
    const p=site.costs(state);
    const monthly=window.MotorTradeMonthly?.statement(state);
    const reserve=window.MotorTradeWorkshop?.reserved(state)??0;
    const dailyWages=(state.staff||[]).reduce((n,person)=>
      n+Math.ceil(person.monthlySalary/30),0);
    const forecourt=site.capacity(state);
    const workshop=site.bays(state);
    const stock=state.vehicles.length;
    const activeRepairs=state.vehicles.filter(v=>
      v.workshop?.method==='internal'&&
      ['in-progress','quality-check'].includes(v.workshop.stage)).length;
    return {p,monthly,reserve,dailyWages,forecourt,workshop,stock,
      freeSpaces:Math.max(0,forecourt-stock),
      activeRepairs,
      cashAfterRepairReserves:state.cash-reserve,
      runningDaily:p.total+dailyWages,
      arrears:(state.premises?.arrears??0)+(state.payrollArrears??0)};
  }
  function card(state,site,kind){
    const q=site.quote(state,kind);
    const forecourt=kind==='forecourt';
    const current=forecourt?site.capacity(state):site.bays(state);
    const title=forecourt?'FORECOURT EXPANSION':'WORKSHOP EXPANSION';
    const short=forecourt?
      'Increase the number of vehicles you can hold at once.':
      'Increase physical repair bays; technicians are still required.';
    const unit=forecourt?'VEHICLE SPACES':'REPAIR BAYS';
    if(q.maximum)return '<article class="hq-upgrade hq-upgrade-max">'+
      '<header class="hq-upgrade-head"><div><small>FACILITY / '+
      (forecourt?'STOCK CAPACITY':'VEHICLE PREPARATION')+'</small><h3>'+title+
      '</h3></div><span class="hq-status hq-ready">MAXIMUM</span></header>'+
      '<div class="hq-upgrade-capacity"><strong>'+current+' '+unit+
      '</strong><span>FULLY EXPANDED</span></div><p>'+short+
      ' Current running costs continue each game day.</p>'+
      '<div class="hq-upgrade-max-note">No further expansion is currently available.</div></article>';
    const unlocked=q.eligible&&!q.shortfall;
    const reason=!q.eligible?'REQUIRES '+q.requiredReputation+' REPUTATION':
      q.shortfall?'SHORT BY '+cash(q.shortfall):'READY TO EXPAND';
    const status=!q.eligible?'hq-unavailable':q.shortfall?'hq-waiting':'hq-ready';
    const what=forecourt?'forecourt spaces':'repair bays';
    const value=q.current+' → '+q.next+' '+what;
    const message=!q.eligible?'Reach '+q.requiredReputation+
      ' reputation before authorising this upgrade.':
      q.shortfall?'Cash shortfall '+cash(q.shortfall)+
        '; protected repairs, wages and rent must be covered.':
      'Both reputation and cash requirements are met.';
    return '<article class="hq-upgrade"><header class="hq-upgrade-head"><div>'+
      '<small>FACILITY / '+(forecourt?'STOCK CAPACITY':'VEHICLE PREPARATION')+
      '</small><h3>'+title+'</h3></div><span class="hq-status '+status+'">'+
      escape(unlocked?'ELIGIBLE':!q.eligible?'REPUTATION LOCKED':'CASH REQUIRED')+
      '</span></header>'+
      '<div class="hq-upgrade-capacity"><strong>'+value+'</strong><span>'+short+'</span></div>'+
      '<div class="hq-upgrade-costs hq-upgrade-headline-costs">'+
      line('ONE-OFF INVESTMENT',cash(q.cost))+
      line('EXTRA COST PER GAME DAY',cash(q.dailyIncrease))+'</div>'+
      '<div class="'+(unlocked?'hq-upgrade-success':'hq-upgrade-warning')+'">'+message+'</div>'+
      '<button type="button" class="trade-button hq-invest-button" '+
      'data-action="upgrade-premises" data-kind="'+kind+'"'+
      (unlocked?'':' disabled')+'>'+
      (unlocked?'APPROVE '+cash(q.cost)+' INVESTMENT':reason)+'</button>'+
      '<details class="hq-upgrade-details"><summary>VIEW INVESTMENT REQUIREMENTS</summary>'+
      '<div class="hq-upgrade-costs">'+
      line('CASH NEEDED INCL. BUFFERS',cash(q.requiredCash))+
      line('REPUTATION REQUIRED',q.requiredReputation+' / 100')+
      '</div><p>Cash protection includes outstanding workshop preparation, payroll '+
      'obligations, the required wage cover and additional premises costs.</p>'+
      '</details></article>';
  }
  function render(state,site){
    const r=figures(state,site),p=r.p,monthly=r.monthly;
    const forecourt=site.quote(state,'forecourt'),workshop=site.quote(state,'workshop');
    const possible=[forecourt,workshop].filter(q=>!q.maximum&&q.eligible&&!q.shortfall).length;
    const nextState=r.arrears?'PAYMENT PRESSURE':
      state.cash<r.runningDaily?'CASH RUNWAY ALERT':
      r.freeSpaces===0?'FORECOURT FULL':
      possible?'EXPANSION POSSIBLE':'OPERATIONS ACTIVE';
    const metrics='<div class="hq-metrics">'+
      label('FORECOURT OCCUPANCY',r.stock+' / '+r.forecourt,
        r.freeSpaces+' '+(r.freeSpaces===1?'space':'spaces')+' available for buying')+
      label('WORKSHOP CAPACITY',r.workshop+' BAYS',
        r.activeRepairs+' in-house '+(r.activeRepairs===1?'job':'jobs')+' in progress')+
      label('DEALERSHIP CASH',cash(state.cash),
        cash(r.cashAfterRepairReserves)+' after workshop reserves')+
      label('DAILY RUNNING COST',cash(r.runningDaily),
        cash(p.total)+' premises + '+cash(r.dailyWages)+' wages')+
      '</div>';
    const head='<div class="hq-brief"><div><small>LIVE BUSINESS OPERATIONS</small>'+
      '<strong>RUNNING YOUR DEALERSHIP</strong>'+
      '<p>Monitor your physical capacity, commitments and investment options.</p></div>'+
      '<span class="hq-brief-status'+(r.arrears||state.cash<r.runningDaily?' hq-brief-alert':'')+'">'+
      nextState+'</span></div>';
    const cost='<section class="hq-cost-panel"><div class="hq-section-heading">'+
      '<div><small>FIXED COSTS / CASH DISCIPLINE</small><h3>OPERATING COMMITMENTS</h3></div>'+
      '<button type="button" class="hq-text-link" data-page="finance">FULL FINANCES</button></div>'+
      '<div class="hq-commit-grid">'+
      line('PREMISES / DAY',cash(p.total))+
      line('STAFF WAGES / DAY',cash(r.dailyWages))+
      line('WORKSHOP FUNDS RESERVED',cash(r.reserve))+
      line('MONTHLY PREMISES GUIDE',cash(p.monthlyGuide))+
      line('OUTSTANDING OBLIGATIONS',cash(r.arrears),r.arrears?' hq-due':'')+
      line('MONTH-TO-DATE PREMISES COST',cash(monthly?.premisesExpense??0))+
      '</div><p class="hq-context">Daily premises and staff costs continue even when no cars sell. '+
