    const upgradeHead='<div class="hq-section-heading hq-upgrade-section-head">'+
      '<div><small>FACILITY INVESTMENT / OWNER APPROVAL</small>'+
      '<h3>EXPANSION & RUNNING COSTS</h3></div>'+
      '<span>'+possible+' '+(possible===1?'OPTION':'OPTIONS')+' CURRENTLY AFFORDABLE</span></div>';
    const more='<details class="hq-guidance"><summary>HOW PREMISES EXPANSION WORKS</summary>'+
      '<p>Forecourt expansion raises how many vehicles can be held. Workshop expansion '+
      'adds repair bays but does not hire technicians. Each upgrade requires a reputation '+
      'threshold, a one-off investment and sufficient money to protect existing repair work, '+
      'unpaid bills, seven days of new premises costs and three days of the full wage bill. '+
      'Only the investment is debited immediately; future rent and utilities increase per game day. '+
      'Blocked upgrades cannot be bought. These are fictional operating figures, not UK property quotations.</p>'+
      '</details>';
    const shortcuts='<nav class="hq-shortcuts" aria-label="Dealership departments">'+
      '<span>CONTINUE OPERATIONS</span>'+[
      ['stock','VEHICLE STOCK'],['workshop','WORKSHOP'],
      ['staff','YOUR STAFF'],['reports','MANAGEMENT REPORTS']].map(([page,title])=>
      '<button type="button" data-page="'+page+'">'+title+'</button>').join('')+'</nav>';
    return '<div class="hq-control">'+head+metrics+cost+upgradeHead+
      '<div class="hq-upgrades">'+card(state,site,'forecourt')+
        card(state,site,'workshop')+'</div>'+shortcuts+more+'</div>';
  }
  window.MotorTradePremisesView=Object.freeze({figures,render,card});
})();

auction-hall-view.js:
'use strict';
/* The Motor Trade v0.9.9 — one-at-a-time, user-paced vehicle auction hall. */
(() => {
  const VC=window.MotorTradeCards;
  if(!VC)throw new Error('Load vehicle-cards.js before auction-hall-view.js');
  const money=VC.money,esc=VC.esc;
  const status={
    won:'HAMMERED TO YOU',lost:'RIVAL WON',passed:'PASSED',unsold:'UNSOLD',owned:'PREVIOUS PURCHASE'
  };
  function resultRow(r){
    const className=r.kind==='won'?'auction-result-won':
      r.kind==='lost'?'auction-result-lost':'auction-result-neutral';
    return '<div class="auction-result-row '+className+'"><span>LOT '+esc(r.lotNumber)+
      '</span><div><strong>'+esc(r.title)+'</strong><small>'+esc(status[r.kind]||r.kind)+
      (r.hammer?' · HAMMER '+money(r.hammer):'')+'</small></div><b>'+
      (r.kind==='won'?money(r.total)+' ALL-IN':'£0 SPENT')+'</b></div>';
  }
  function render(state,E,reportCard,previewId=null){
    const h=state.auctionHall,lots=E.marketFor(state).auctions;
    const own=state.auctionHistory.filter(x=>x.kind==='won');
    const nextDay=E.nextAuctionDay(state.day);
    const nextWeekday=(nextDay-1)%7===0?'MONDAY':'TUESDAY';
    const history=state.auctionHistory.slice(-10).reverse();
    const won=h.results.filter(r=>r.kind==='won').length;
    const header='<div class="auction-hall-head"><div><span>INDEPENDENT MOTOR AUCTION · GAME DAY '+
      state.day+'</span><h2>AUCTION <em>HALL.</em></h2>'+
      '<p>One auction per game week, normally Monday (Tuesday when Monday is Deal Day). Bid until either dealer drops out. '+
      'Each lot stays open until resolved, with no real-time timer.</p></div>'+
      '<div class="auction-head-metrics"><div><small>LOTS TODAY</small><strong>'+lots.length+'</strong></div>'+
      '<div><small>ACTIVE LOT</small><strong>'+(h.phase==='finished'||!lots.length?'—':E.lotNumber(h.index))+'</strong></div>'+
      '<div><small>WON TODAY</small><strong>'+won+'</strong></div>'+
      '<div><small>CAREER AUCTION WINS</small><strong>'+own.length+'</strong></div></div></div>';
    const notice='<p class="trade-alert">All amounts are simulated GBP. A winning bid becomes binding when the hammer falls. '+
      'Confirm the separate invoice for the winning bid PLUS buyer fee before the car joins your workshop. Preparation funds are protected, not spent at the auction. '+
      'A paid inspection is optional and non-refundable. A lot without a met vendor reserve remains unsold. '+
      'No fees are charged for losing or passing. Competitor bidding is fixed for the day and cannot be rerolled.</p>';
    const catalogue=lots.length?'<div class="auction-catalogue"><h3>NUMBERED LOT CATALOGUE</h3>'+
      '<div class="auction-catalogue-list">'+lots.map((lot,i)=>{
        const r=h.results[i],active=i===h.index&&h.phase!=='finished';
        const spent=state.vehicles.some(v=>v.origin===lot.id)||state.sold.some(v=>v.origin===lot.id);
        return '<article class="auction-catalogue-item '+(active?'auction-catalogue-active':'')+
          (r?' auction-catalogue-done':'')+'"><span>LOT '+E.lotNumber(i)+'</span>'+
          '<strong>'+esc(lot.title)+'</strong>'+
          '<small>'+esc(lot.fuel)+' · '+esc(lot.gearbox)+' · GRADE '+lot.profile.grade+
          ' · GUIDE '+money(lot.guide)+'</small><b>'+ (r?status[r.kind]:active?'ON THE ROSTRUM':spent?'ALREADY OWNED':'UPCOMING')+
          '</b><button type="button" class="auction-catalogue-review" data-action="preview-auction" data-id="'+
          esc(lot.id)+'">VIEW LOT REPORT</button></article>';
      }).join('')+'</div></div>':'';
    if(!lots.length)
      return header+notice+'<div class="trade-empty auction-closed"><h2>AUCTION HOUSE CLOSED TODAY.</h2>'+
        '<p>Auctions run once each game week, normally Monday; never weekends. NEXT SESSION: '+nextWeekday+' · GAME DAY '+nextDay+
        ' (in '+(nextDay-state.day)+' game day'+(nextDay-state.day===1?'':'s')+'). '+
        (state.day%30===0?'Deal Day is also closed to auction bidding. ':'')+
        'Private sellers remain available through the Buying Desk.</p>'+
        '<button type="button" class="trade-button" data-page="auctions">OPEN BUYING DESK</button></div>'+
        (history.length?'<div class="panel-card auction-results"><h3>PREVIOUS HAMMER RESULTS</h3>'+history.map(resultRow).join('')+'</div>':'');
    if(h.phase==='finished')
      return header+notice+catalogue+
        '<div class="panel-card auction-finished"><h3>HAMMER RESULTS · SESSION COMPLETE</h3>'+
        '<p>Every lot has now left the auction ring. Any cars you purchased are in Vehicle Stock for assessment and repair.</p>'+
        h.results.map(resultRow).join('')+
        '<div class="auction-final-actions"><button type="button" class="trade-button" data-page="stock">VIEW VEHICLE STOCK</button>'+
        '<button type="button" class="trade-button trade-button-secondary" data-page="auctions">PRIVATE SELLER DESK</button></div></div>';
    const lot=lots[h.index],current=h.currentBid||lot.guide;
    const previewLot=lots.find(x=>x.id===previewId&&x.id!==lot.id)||null;
    const preview=previewLot?'<section class="panel-card auction-preview"><div class="auction-preview-head"><div><span>CATALOGUE INSPECTION · NOT ON THE ROSTRUM</span><h3>LOT '+
      E.lotNumber(lots.indexOf(previewLot))+' · '+esc(previewLot.title)+
      '</h3></div><button type="button" class="trade-button trade-button-secondary" data-action="close-auction-preview">CLOSE PREVIEW</button></div>'+
      '<div class="auction-preview-body">'+VC.heading(previewLot,'auction',
      'CATALOGUE LOT '+E.lotNumber(lots.indexOf(previewLot)))+
      reportCard(previewLot,'auction',previewLot.guide+250)+
      '<p>Review this lot ahead of its turn. You cannot bid on it until the current lot is finished.</p></div></section>':'';
    const paymentDue=h.phase==='payment';
    const expectedNext=paymentDue?current:current+100,inspection=!!state.reports?.[lot.id];
    const q=E.quote(lot,'auction',expectedNext,inspection);
    const intelligence=E.people.buyerEstimate(state,lot.rival);
    const already=state.vehicles.some(v=>v.origin===lot.id)||
      state.sold.some(v=>v.origin===lot.id);
    const statusText=h.phase==='result'?(status[h.results.at(-1).kind]||'LOT ENDED'):
      h.phase==='catalogue'?'AWAITING THE AUCTIONEER':
      paymentDue?'HAMMER FALLEN · PAYMENT REQUIRED':
      h.leader==='rival'?'RIVAL DEALER LEADS':'YOU LEAD';
    const controls=paymentDue?
      '<button type="button" class="trade-button auction-primary" data-action="settle-auction">FINALISE PAYMENT · '+
      money(current+lot.fee)+'</button>':
      h.phase==='catalogue'?
      '<button type="button" class="trade-button auction-primary" data-action="start-auction">OPEN BIDDING — LOT '+
      E.lotNumber(h.index)+'</button>'+
      '<button type="button" class="trade-button trade-button-outline" data-action="pass-auction">SKIP THIS LOT</button>':
      h.phase==='bidding'?
      '<button type="button" class="trade-button auction-primary" data-action="bid-live-auction" data-increment="100">BID +£100</button>'+
      '<button type="button" class="trade-button" data-action="bid-live-auction" data-increment="250">BID +£250</button>'+
      '<button type="button" class="trade-button trade-button-secondary" data-action="bid-live-auction" data-increment="500">BID +£500</button>'+
      '<button type="button" class="trade-button trade-button-outline" data-action="pass-auction">PASS / LEAVE LOT</button>':
      '<button type="button" class="trade-button auction-primary" data-action="next-auction-lot">'+
      (h.index+1>=lots.length?'FINISH SESSION & VIEW RESULTS':'NEXT LOT '+E.lotNumber(h.index+1))+
      '</button>';
    const cashWarning=paymentDue?'':state.vehicles.length>=state.capacity?
      '<p class="auction-risk">YOUR FORECOURT IS FULL. You cannot bid again until you sell stock.</p>':
      E.workshop.reserved(state)+expectedNext+lot.fee+
        lot.profile.basePrep+(lot.profile.hiddenFault?.cost||0)>state.cash?
      '<p class="auction-risk">The next £100 bid may exceed available cash after buyer fees and reserved preparation. Consider passing.</p>':'';
    const log=h.feed.length?'<div class="auction-feed" aria-live="polite">'+
      h.feed.slice(-12).map(x=>'<p>'+esc(x)+'</p>').join('')+'</div>':
      '<div class="auction-feed"><p>Inspect the lot before opening the bidding. When you bid, competitors respond immediately.</p></div>';
    const settlement=paymentDue?'<div class="auction-hammer-result auction-hammer-won">'+
      '<strong>HAMMER DOWN — RIVAL DEALER HAS DROPPED OUT</strong><p>Winning hammer '+money(current)+
      ' + buyer fee '+money(lot.fee)+' = TOTAL DUE '+money(current+lot.fee)+
      '. Finalise payment to deduct this amount and transfer the car to Vehicle Stock for workshop assessment. '+
      'The auction cannot continue or advance the game day until this invoice is paid.</p></div>':'';
    const resolved=h.phase==='result'?'<div class="auction-hammer-result '+(h.results.at(-1).kind==='won'?'auction-hammer-won':'')+'">'+
      '<strong>'+esc(status[h.results.at(-1).kind])+'</strong><p>'+
      esc(h.results.at(-1).detail)+'</p></div>':'';
    const lotView='<div class="auction-active-grid">'+
      '<article class="panel-card auction-current">'+
      '<div class="auction-rostrum"><span>ON THE ROSTRUM · LOT '+E.lotNumber(h.index)+
      ' / '+lots.length+'</span><strong>'+esc(statusText)+'</strong></div>'+
      '<div class="auction-car-content">'+VC.heading(lot,'auction','LOT '+E.lotNumber(h.index)+' · '+esc(lot.id))+
      '<div class="auction-prices"><div><small>GUIDE</small><strong>'+money(lot.guide)+'</strong></div>'+
      '<div><small>BUYER FEE</small><strong>'+money(lot.fee)+'</strong></div>'+
      '<div><small>KNOWN PREP ESTIMATE</small><strong>'+money(lot.profile.basePrep+(inspection?(lot.profile.hiddenFault?.cost||0):0))+'</strong></div>'+
      '<div><small>LIKELY RETAIL SALE</small><strong>'+money(lot.profile.likelySale)+'</strong></div></div>'+
      reportCard(lot,'auction',expectedNext)+
      '</div></article>'+
      '<aside class="panel-card auction-bid-box"><div class="auction-bid-box-top"><small>LIVE HAMMER POSITION</small>'+
      '<strong>'+money(current)+'</strong><span>'+esc(statusText)+'</span></div>'+
      '<div class="auction-bid-maths"><div><span>'+(paymentDue?'WINNING HAMMER':'NEXT £100 BID')+'</span><b>'+money(expectedNext)+'</b></div>'+
      '<div><span>PLUS BUYER FEE</span><b>'+money(lot.fee)+'</b></div>'+
      '<div><span>PLUS EXPECTED PREPARATION</span><b>'+money(q.prep)+'</b></div>'+
      '<div><span>PROJECTED GROSS CONTRIBUTION</span><b class="'+(q.expectedMargin<0?'auction-negative':'')+'">'+money(q.expectedMargin)+'</b></div></div>'+
      (intelligence?'<div class="people-bid-intel">VEHICLE BUYER INTELLIGENCE: COMPETITOR BID RANGE '+
        money(intelligence.lower)+'–'+money(intelligence.upper)+
        '. Forecast only — not the actual reserve or final bid.</div>':'')+
      settlement+resolved+cashWarning+
      '<div class="auction-controls">'+controls+'</div>'+
      '<div class="auction-activity"><h3>AUCTIONEER ACTIVITY</h3>'+log+'</div></aside></div>';
    const results=h.results.length?'<div class="panel-card auction-results"><h3>TODAY\'S HAMMER HISTORY</h3>'+
      h.results.map(resultRow).join('')+'</div>':'';
    const recent=history.filter(x=>x.day<state.day).length?
      '<div class="panel-card auction-results"><h3>RECENT SESSION RESULTS</h3>'+
      history.filter(x=>x.day<state.day).slice(0,6).map(resultRow).join('')+'</div>':'';
    return header+notice+catalogue+preview+lotView+results+recent;
  }
  window.MotorTradeAuctionHallView=Object.freeze({render});
})();

buying-desk-view.js:
'use strict';
/* v0.9.16 — Compact direct-seller acquisition workspace.
 * Pure rendering: all prices, affordability and purchasing go through the
 * existing engine. No simulated DVLA, DVSA or HPI service is implied.
 */
(() => {
  const VC=window.MotorTradeCards;
  if(!VC)throw new Error('Load vehicle-cards.js before buying-desk-view.js');
  const money=VC.money,esc=VC.esc;
  const miles=n=>new Intl.NumberFormat('en-GB').format(n)+' mi';
  function openingOffer(car){
    // Use the advertised ask, not the owner's undisclosed floor.
    const discount=Math.max(100,Math.min(500,Math.round(car.ask*.06/25)*25));
    return Math.max(100,Math.min(car.ask,Math.round((car.ask-discount)/25)*25));
  }
  function fundingWarning(state,model){
    if(state.vehicles.length>=state.capacity)
      return 'FORECOURT FULL — sell stock before buying again.';
    if(!model.affordable)
      return 'INSUFFICIENT CASH — required workshop funding exceeds available cash. Reduce your offer or release stock.';
    return '';
  }
  function condition(car){
    const grade=car.profile?.grade??car.grade;
    return grade<=2?'GOOD':grade===3?'AVERAGE':'ATTENTION';
  }
  function position(quote){
    if(quote.expectedMargin<0)return {kind:'loss',label:'PROJECTED LOSS',text:'At this offer, the expected retail proceeds do not cover acquisition, expected repairs and any paid inspection. Avoid this purchase or renegotiate.'};
    if(quote.price>quote.maxBid)return {kind:'risk',label:'ABOVE BUYING CEILING',text:'Your offer exceeds the suggested buying ceiling by '+money(quote.price-quote.maxBid)+'. The deal may still show a gross margin, but it falls below your target trading contribution.'};
    return {kind:'good',label:'WITHIN BUYING CEILING',text:'The offer is within the modelled buying ceiling. Profit is still uncertain until the car is prepared and actually sold.'};
  }
  function figures(car,state,E,offer){
    const inspected=!!state.reports?.[car.id];
    const quote=E.quote(car,'seller',offer,inspected);
    const reserved=E.workshop.reserved(state);
    // Buying cash: offer now; projected prep must be retained for the workshop.
    // The engine's hard affordability gate also protects any actual hidden fault.
    const remaining=state.cash-reserved-offer-quote.prep;
    // Match the engine's full reserve gate while keeping hidden faults private.
    const requiredPrep=car.profile.basePrep+(car.profile.hiddenFault?.cost||0);
    const affordable=state.cash>=reserved+offer+requiredPrep;
    return {quote,inspected,remaining,reserved,affordable,position:position(quote)};
  }
  function toolbar(state,E,sellers,selected){
    const negotiating=sellers.filter(x=>state.negotiations?.[x.id]?.status==='counter'&&
      !state.vehicles.some(v=>v.origin===x.id)).length;
    const available=sellers.filter(x=>!state.vehicles.some(v=>v.origin===x.id)&&
      state.negotiations?.[x.id]?.status!=='walked').length;
    const reserved=E.workshop.reserved(state);
    const cards=[
      ['PRIVATE SELLER LEADS',sellers.length,'AVAILABLE '+available],
      ['ACTIVE COUNTEROFFERS',negotiating,negotiating?'DECISION NEEDED':'NO OPEN COUNTERS'],
      ['FORECOURT SPACES',state.capacity-state.vehicles.length,
        state.vehicles.length+' / '+state.capacity+' OCCUPIED'],
      ['WORKING CASH',money(Math.max(0,state.cash-reserved)),
        reserved?'REPAIRS RESERVED '+money(reserved):'NO REPAIR CASH COMMITTED']
    ];
    return '<div class="buy-desk-stats">'+cards.map(([label,value,note])=>
      '<div class="buy-stat"><small>'+label+'</small><strong>'+value+
      '</strong><span>'+note+'</span></div>').join('')+'</div>';
  }
  function leadStatus(car,state){
    const negotiation=state.negotiations?.[car.id];
    if(state.vehicles.some(v=>v.origin===car.id)||state.sold.some(v=>v.origin===car.id))
      return ['ACQUIRED','done'];
    if(negotiation?.status==='walked')return ['SELLER LEFT','closed'];
    if(negotiation?.status==='counter')return ['COUNTER '+money(negotiation.counter),'counter'];
    return ['NEW LEAD','new'];
  }
  function leadList(state,E,sellers,selectedId){
    return '<aside class="buy-leads" aria-labelledby="buy-leads-title">'+
      '<div class="buy-leads-heading"><div><small>DIRECT BUYING</small>'+
      '<h2 id="buy-leads-title">SELLER SHORTLIST</h2></div>'+
      '<span>'+sellers.length+' LEADS</span></div>'+
      '<div class="buy-lead-list">'+sellers.map((car,i)=>{
        const [label,kind]=leadStatus(car,state);
        const selected=car.id===selectedId;
        const approach=E.sellerApproach(state,car);
        return '<button type="button" class="buy-lead '+(selected?'buy-lead-selected ':'')+
          'buy-lead-'+kind+'" data-action="select-seller" data-id="'+esc(car.id)+
          '" aria-pressed="'+selected+'">'+
          '<div class="buy-lead-top"><span>LEAD '+String(i+1).padStart(2,'0')+
          ' · '+esc(approach.label)+'</span><b>'+esc(label)+'</b></div>'+
          '<strong>'+esc(car.title)+'</strong>'+
          '<div class="buy-lead-facts"><span>'+miles(car.miles)+
          '</span><span>GRADE '+car.profile.grade+
          '</span><span>'+esc(car.fuel)+'</span></div>'+
          '<div class="buy-lead-bottom"><span>OWNER ASKS</span><b>'+money(car.ask)+'</b></div>'+
          '</button>';
      }).join('')+'</div>'+
      '<p class="buy-leads-tip">These are fictional customer leads, not live classified adverts. Selecting a vehicle does not reserve it.</p>'+
    '</aside>';
  }
  function pricing(car,state,E,offer){
    const {quote,inspected,remaining,reserved,position:signal}=figures(car,state,E,offer);
    const quotes=[
      ['OWNER ASKING',money(car.ask)],
      ['TRADE VALUE',money(quote.trade)],
      ['LIKELY ACHIEVED SALE',money(quote.likelySale)],
      ['SUGGESTED MAX OFFER',money(quote.maxBid)]
    ];
    return '<div class="buy-valuation" aria-label="Vehicle buying appraisal">'+
      '<div class="buy-valuation-heading"><div><small>THE NUMBERS</small><strong>BUYING APPRAISAL</strong></div>'+
      '<span>'+esc(inspected?'INSPECTED':'UNINSPECTED')+'</span></div>'+
      '<div class="buy-value-grid">'+quotes.map(([label,value])=>
        '<div><small>'+label+'</small><strong>'+value+'</strong></div>').join('')+'</div>'+
      '<div class="buy-budget-table">'+
        '<div><span>Offer being considered</span><b id="desk-offer-'+esc(car.id)+'">'+money(offer)+'</b></div>'+
        '<div><span>Expected preparation / risk allowance</span><b id="desk-prep-'+esc(car.id)+'">'+money(quote.prep)+'</b></div>'+
        '<div><span>Inspection paid</span><b>'+money(quote.inspection)+'</b></div>'+
        '<div><span>Modelled total investment</span><b id="desk-total-'+esc(car.id)+'">'+money(quote.total)+'</b></div>'+
        '<div class="buy-budget-total"><span>PROJECTED GROSS CONTRIBUTION</span>'+
          '<b id="desk-projection-'+esc(car.id)+'" class="'+(quote.expectedMargin<0?'buy-negative':'')+'">'+money(quote.expectedMargin)+'</b></div>'+
        '<div><span>Indicative cash after offer and prep reserves</span><b id="desk-headroom-'+esc(car.id)+'"'+
          (remaining<0?' class="buy-negative"':'')+'>'+money(remaining)+'</b></div>'+
      '</div>'+
      '<div id="desk-signal-'+esc(car.id)+'" class="buy-decision buy-decision-'+signal.kind+'">'+
        '<strong>'+signal.label+'</strong><p>'+esc(signal.text)+'</p></div>'+
      '<p class="buy-budget-note">Gross contribution is an estimate before staff, premises, VAT/tax, retail finance and aftersales liabilities. Uninspected repair budgets include a risk allowance; actual faults can cost more. Existing repair reserves ('+
        money(reserved)+') are protected separately from your offer. Indicative headroom uses forecast preparation; purchase approval protects the full workshop commitment, which may be higher before inspection.</p></div>';
  }
  function tradingControls(car,state,E,offer,reportCard,leadFeedback){
    const [status,kind]=leadStatus(car,state);
    const deal=state.negotiations?.[car.id];
    const closed=['done','closed'].includes(kind);
    const approach=E.sellerApproach(state,car);
    const f=figures(car,state,E,offer);
    const cannot=fundingWarning(state,f);
    const proposed=deal?.status==='counter'?
      '<div class="buy-counter"><small>OWNER COUNTEROFFER · ROUND '+deal.rounds+'</small>'+
        '<strong>SELLER COUNTEROFFER: '+money(deal.counter)+'</strong>'+
        '<p>The owner has not accepted your offer. Accept the counter, revise your offer, or walk away. No money has changed hands.</p></div>':'';
    const notices=kind==='done'?
      '<div class="trade-inline-feedback trade-feedback-success">PURCHASED — vehicle is now in Vehicle Stock. Assess and prepare it before listing.</div>':
      kind==='closed'?'<div class="trade-inline-feedback trade-feedback-warning">OWNER WALKED AWAY — this lead is closed for today.</div>':'';
    const controls=closed?
      '<button type="button" class="trade-button" disabled>ENQUIRY CLOSED</button>'+
      (kind==='done'?'<button type="button" class="trade-button trade-button-secondary" data-page="stock">VIEW VEHICLE STOCK</button>':''):
      '<div class="buy-offer-actions">'+
        '<label for="seller-offer-'+esc(car.id)+'">YOUR OFFER (£)'+
        '<input class="trade-input" id="seller-offer-'+esc(car.id)+'" value="'+offer+'" type="number"'+
        ' inputmode="numeric" min="100" max="'+car.ask+'" step="25"></label>'+
        '<button type="button" class="trade-button" data-action="buy-seller" data-id="'+esc(car.id)+'">'+
          (deal?.status==='counter'?'REVISE OFFER':'MAKE AN OFFER')+'</button></div>'+
      '<p class="buy-opening-hint">SUGGESTED OPENING OFFER '+money(openingOffer(car))+' · Editable — use the appraisal to set your own price.</p>'+
      (deal?.status==='counter'?
        '<div class="buy-counter-actions"><button type="button" class="trade-button trade-button-secondary" data-action="accept-seller-counter" data-id="'+esc(car.id)+'">ACCEPT '+money(deal.counter)+'</button>'+
        '<button type="button" class="trade-button trade-button-outline" data-action="walk-seller" data-id="'+esc(car.id)+'">WALK AWAY</button></div>':'');
    return '<div class="buy-trading">'+
      '<div class="buy-seller-story"><span>SELLER POSITION · '+esc(approach.label)+'</span>'+
        '<p>'+esc(approach.description)+'</p></div>'+
      '<div class="buy-trading-heading"><strong>NEGOTIATE THE PURCHASE</strong>'+
        '<small>NO BUYER FEE · CASH PURCHASE</small></div>'+
      proposed+notices+leadFeedback(car.id)+
      '<p id="desk-funding-warning-'+esc(car.id)+'" class="trade-purchase-warning"'+
        (cannot&&!closed?'':' hidden')+'>'+esc(closed?'':cannot)+'</p>'+
      controls+
      '<div class="buy-deal-terms"><strong>WHEN A DEAL IS AGREED</strong><p>Purchase cash is debited once, your vehicle joins stock and the workshop must assess it. An owner may counter or withdraw after an unreasonable offer. A paid inspection is non-refundable.</p></div>'+
    '</div>';
  }
  function render(state,E,opts={}){
    const sellers=E.marketFor(state).sellers;
    const active=opts.selectedId&&sellers.some(x=>x.id===opts.selectedId)?
      opts.selectedId:sellers[0]?.id??null;
    const intro=toolbar(state,E,sellers,active);
    if(!sellers.length)return {selectedId:null,html:intro+
      '<div class="buy-no-leads"><h2>NO PRIVATE SELLERS THIS SESSION.</h2>'+
      '<p>Lead volume varies with daily footfall and Deal Day conditions. Do not invent a purchase or force a vehicle deal. Return next session or review existing stock.</p>'+
      '<button class="trade-button trade-button-secondary" data-page="stock">OPEN VEHICLE STOCK</button></div>'};
    const car=sellers.find(x=>x.id===active);
    const draft=opts.drafts&&Number.isSafeInteger(opts.drafts[active])?
      opts.drafts[active]:null;
    const negotiation=state.negotiations?.[active];
    const offer=draft!==null?draft:
      negotiation?.status==='counter'?negotiation.counter:openingOffer(car);
    const report=opts.reportCard(car,'seller',offer);
    const heading='<div class="buy-detail-top"><span>VEHICLE REVIEW · '+esc(car.id)+'</span>'+
      '<span>GRADE '+car.profile.grade+'/5 · '+condition(car)+'</span></div>';
    const detail='<section class="buy-seller-focus" aria-label="Selected private seller">'+heading+
      '<div class="buy-focus-content"><div class="buy-vehicle">'+VC.heading(car,'seller','SELLER VEHICLE · '+esc(car.id))+
      '<p class="buy-car-note">'+esc(car.note||'')+'</p>'+
      '<div class="buy-inspection-prompt"><strong>BEFORE YOU BUY</strong>'+
        '<p>Inspect mileage, service history, MOT advisories and condition. A paid inspection may reveal a hidden repair before you commit.</p></div>'+
      report+'</div>'+
      '<div class="buy-deal-workspace">'+
        pricing(car,state,E,offer)+
        tradingControls(car,state,E,offer,opts.reportCard,opts.leadFeedback)+
      '</div></div></section>';
    return {selectedId:active,html:intro+
      '<div class="buy-main-grid">'+leadList(state,E,sellers,active)+detail+'</div>'+
      '<p class="buy-disclosure">All seller identities, inspection reports and valuations are fictional. Representative vehicle photography is not evidence of the exact vehicle. No live DVSA, DVLA or HPI verification is performed.</p>'};
  }
  window.MotorTradeBuyingDeskView=Object.freeze({render,figures,position,openingOffer,fundingWarning});
})();

