'use strict';
/* v0.9.18 — Vehicle Stock: single source of truth for inventory and capital.
 * All figures are derived from existing career records; no new save fields.
 */
(() => {
  const VC=window.MotorTradeCards;
  if(!VC)throw new Error('Load vehicle-cards.js before stock-view.js');
  const esc=VC.esc,money=VC.money;
  const mileage=n=>new Intl.NumberFormat('en-GB').format(n)+' mi';
  const FILTERS=Object.freeze(['all','prep','ready','listed']);
  const labelSource={auction:'AUCTION PURCHASE',seller:'PRIVATE SELLER','part-ex':'PART EXCHANGE'};
  function group(v){
    if(v.status==='listed')return 'listed';
    if(v.status==='prepared')return 'ready';
    return 'prep';
  }
  function phase(v){
    if(v.status==='listed')return {label:'ON SALE',tone:'listed',next:'SALES OFFICE'};
    if(v.status==='prepared')return {label:'READY TO ADVERTISE',tone:'ready',next:'SET RETAIL PRICE'};
    const stage=v.workshop?.stage;
    const words={
      unassessed:'AWAITING ASSESSMENT',
      quoted:'REPAIR APPROVAL DUE',
      'in-progress':v.workshop?.paused?'REPAIRS PAUSED':'REPAIRS IN PROGRESS',
      'quality-check':'FINAL QUALITY CHECK DUE'
    };
    return {label:words[stage]||'WORKSHOP REQUIRED',tone:'prep',next:'WORKSHOP'};
  }
  function figures(v){
    const stage=v.workshop?.stage;
    const booked=['in-progress','quality-check'].includes(stage);
    // Repairs are charged when booked but prepSpent is recorded only on QC.
    // They must never disappear from cash invested while a job is underway.
    const paidRepairs=booked?Number(v.workshop.repairCost||0):Number(v.prepSpent||0);
    const futurePrep=v.status==='acquired'&&['unassessed','quoted'].includes(stage)?
      Number(v.prepBudget||0):0;
    const invested=Number(v.cost||0)+paidRepairs;
    const likely=Number(v.profile?.likelySale??v.retail);
    const likelySale=v.status==='listed'&&Number.isSafeInteger(v.asking)?
      Math.min(v.asking,likely):likely;
    return {acquisition:v.cost,paidRepairs,invested,futurePrep,
      likelySale,contribution:likelySale-invested-futurePrep};
  }
  function summary(state){
    const vehicles=state.vehicles;
    return {count:vehicles.length,spaces:Math.max(0,state.capacity-vehicles.length),
      prep:vehicles.filter(v=>group(v)==='prep').length,
      ready:vehicles.filter(v=>group(v)==='ready').length,
      listed:vehicles.filter(v=>group(v)==='listed').length,
      invested:vehicles.reduce((n,v)=>n+figures(v).invested,0),
      reserved:vehicles.reduce((n,v)=>n+figures(v).futurePrep,0)};
  }
  function inventoryRow(v,state,selected){
    const p=phase(v),age=Math.max(0,state.day-v.acquiredDay);
    const f=figures(v),ageClass=age>=45?'stock-age-critical':age>=30?'stock-age-warning':'';
    return '<article class="stock-unit'+(selected?' stock-unit-selected':'')+'">'+
      '<div class="stock-unit-thumb">'+VC.photo(v,'stock')+'</div>'+
      '<button type="button" class="stock-unit-select" data-action="select-stock" data-id="'+v.id+
        '" aria-pressed="'+selected+'">'+
        '<span class="stock-unit-kicker">STOCK '+v.id+' · '+esc(labelSource[v.source]||v.source.toUpperCase())+'</span>'+
        '<strong>'+esc(v.title)+'</strong>'+
        '<small>'+mileage(v.miles)+' · '+esc(v.fuel)+' · '+esc(v.gearbox)+'</small>'+
        '<span class="stock-unit-bottom"><span class="stock-status stock-status-'+p.tone+'">'+p.label+'</span>'+
        '<b class="'+ageClass+'">'+age+' DAYS</b></span>'+
        '<span class="stock-unit-cost">INVESTED '+money(f.invested)+'</span>'+
      '</button></article>';
  }
  function costRow(label,amount,strong=false){
    return '<div'+(strong?' class="stock-cost-emphasis"':'')+'><span>'+esc(label)+
      '</span><strong>'+money(amount)+'</strong></div>';
  }
  function controls(v,state){
    const p=phase(v),stage=v.workshop?.stage;
    if(v.status==='acquired'){
      const guidance=stage==='in-progress'?
        (v.workshop.paused?'Repairs paused — review staffing or transfer the job.':
          v.workshop.remainingDays+' game day(s) remaining before quality control.'):
        stage==='quality-check'?'Repairs finished; final quality control is due.':
        stage==='quoted'?'Review the workshop quote and authorise repairs.':
        'Start with a workshop assessment before authorising repairs.';
      return '<div class="stock-action-box"><h4>NEXT DECISION · '+esc(p.next)+'</h4>'+
        '<p>'+esc(guidance)+'</p>'+
        '<button type="button" class="trade-button" data-page="workshop" data-id="'+v.id+
        '">OPEN WORKSHOP</button></div>';
    }
    const caseRecord=state.customerCases?.[String(v.id)];
    const locked=v.status==='listed'&&caseRecord&&
      ['agreed','reserved','collectable'].includes(caseRecord.status);
    const price=Number.isSafeInteger(v.asking)?v.asking:v.retail;
    return '<div class="stock-action-box"><h4>NEXT DECISION · '+p.next+'</h4>'+
      (v.status==='listed'?'<p>Advertising is live. Buyer interest and agreements are managed in the Sales Office.</p>':
        '<p>Quality control has passed. Set your asking price to advertise the car.</p>')+
      (locked?'<p class="stock-lock-note">PRICING LOCKED · An active customer agreement must be resolved in the Sales Office.</p>':'')+
      '<div class="stock-price-action"><label for="stock-price-'+v.id+
      '">RETAIL ASKING PRICE (£)<input class="trade-input" id="stock-price-'+v.id+
      '" type="number" inputmode="numeric" min="500" max="75000" step="50" value="'+price+'"'+
      (locked?' disabled':'')+'></label>'+
      '<button type="button" class="trade-button" data-action="list-stock" data-id="'+v.id+
      '"'+(locked?' disabled':'')+'>'+(v.status==='listed'?'UPDATE PRICE':'ADVERTISE VEHICLE')+
      '</button></div>'+
      (v.status==='listed'?'<button type="button" class="trade-button trade-button-secondary" data-page="sales" data-id="'+v.id+
      '">OPEN SALES OFFICE</button>':'')+'</div>';
  }
  function dossier(v,state,reportCard){
    const f=figures(v),p=phase(v),age=Math.max(0,state.day-v.acquiredDay);
    const grade=v.profile?.grade??3;
    const source=labelSource[v.source]||v.source.toUpperCase();
    const risk=age>=45?'HIGH STOCK AGE · CAPITAL IS TIED UP':
      age>=30?'STOCK AGE WARNING · REVIEW PRICING AND DEMAND':'';
    return '<section class="stock-dossier" aria-label="Selected vehicle file">'+
      '<div class="stock-dossier-top"><div><span>VEHICLE FILE · STOCK '+v.id+'</span>'+
      '<strong>'+esc(v.title)+'</strong></div><span class="stock-status stock-status-'+p.tone+'">'+p.label+'</span></div>'+
      '<div class="stock-dossier-grid"><div class="stock-dossier-vehicle">'+
      VC.heading(v,'stock',source+' · STOCK '+v.id)+
      '<p class="stock-dossier-note">'+esc(v.note||'')+'</p>'+
      '<div class="stock-facts"><div><small>ACQUIRED</small><strong>GAME DAY '+v.acquiredDay+'</strong></div>'+
      '<div><small>DAYS HELD</small><strong class="'+(age>=30?'stock-age-warning':'')+'">'+age+'</strong></div>'+
      '<div><small>SOURCE</small><strong>'+esc(source)+'</strong></div>'+
      '<div><small>CONDITION</small><strong>GRADE '+grade+' / 5</strong></div></div>'+
      (risk?'<div class="stock-aged-alert">'+risk+'</div>':'')+
      reportCard(v,'stock',v.asking??v.retail)+'</div>'+
      '<div class="stock-dossier-finance"><div class="stock-finance-heading">'+
      '<small>STOCK UNIT FINANCIALS</small><h3>THE NUMBERS.</h3></div>'+
      '<div class="stock-cost-table">'+
      costRow('Acquisition incl. inspection / assessment',f.acquisition)+
      costRow('Repairs already paid / booked',f.paidRepairs)+
      costRow('CASH INVESTED TO DATE',f.invested,true)+
      costRow('Unspent preparation requirement',f.futurePrep)+
      costRow('Modelled likely achieved sale',f.likelySale)+
      '<div class="stock-cost-emphasis stock-margin'+(f.contribution<0?' stock-margin-loss':'')+
      '"><span>PROJECTED GROSS CONTRIBUTION</span><strong>'+money(f.contribution)+'</strong></div>'+
      '</div>'+
      '<p class="stock-finance-note">Cash invested includes paid repair bookings even before final QC. Unspent preparation is a protected estimate, not money already paid. Likely sale is a fictional projection'+
      (v.status==='listed'?' capped at your asking price':'')+
      '. Gross contribution excludes wages, premises, tax, aftersales and other overheads.</p>'+
      controls(v,state)+
      '</div></div></section>';
  }
  function render(state,{filter='all',selectedId=null,reportCard=()=>''}={}){
    const value=FILTERS.includes(filter)?filter:'all';
    const stats=summary(state);
    const metrics=[
      ['VEHICLES',stats.count,'CAPACITY '+state.capacity],
      ['CASH INVESTED',money(stats.invested),'IN EXISTING STOCK'],
      ['UNSPENT PREP',money(stats.reserved),'WORKSHOP FUNDING'],
      ['ADVERTISED',stats.listed,'RETAIL MARKET'],
      ['FREE SPACES',stats.spaces,'READY FOR PURCHASE']
    ];
    const head='<div class="stock-kpi-strip">'+metrics.map(([label,number,note])=>
      '<div class="stock-kpi"><small>'+label+'</small><strong>'+number+
      '</strong><span>'+note+'</span></div>').join('')+'</div>';
    if(!state.vehicles.length)return {selectedId:null,html:head+
      '<div class="trade-empty stock-empty"><h2>YOUR FORECOURT IS EMPTY.</h2>'+
      '<p>Purchase a vehicle at the weekly Auction Hall or negotiate directly with a private seller. New purchases automatically enter this stock register.</p>'+
      '<div class="stock-empty-actions"><button type="button" class="trade-button" data-page="auctions">OPEN BUYING DESK</button>'+
      '<button type="button" class="trade-button trade-button-secondary" data-page="auctionHall">OPEN AUCTION HALL</button></div></div>'};
    const filters=[['all','ALL STOCK',stats.count],['prep','IN PREPARATION',stats.prep],
      ['ready','RETAIL READY',stats.ready],['listed','ADVERTISED',stats.listed]];
    const toolbar='<div class="stock-toolbar"><div><small>LIVE FORECOURT REGISTER</small>'+
      '<strong>'+state.vehicles.length+' ACTIVE UNITS</strong></div>'+
      '<div class="stock-filters" role="group" aria-label="Filter stock">'+
      filters.map(([name,label,count])=>'<button type="button" data-action="filter-stock" data-filter="'+name+
        '" aria-pressed="'+(value===name)+'">'+label+' <b>'+count+'</b></button>').join('')+'</div></div>';
    const eligible=state.vehicles.filter(v=>value==='all'||group(v)===value)
      .slice().sort((a,b)=>a.acquiredDay-b.acquiredDay||a.id-b.id);
    const selected=eligible.find(v=>v.id===selectedId)||eligible[0]||null;
    const list=eligible.length?eligible.map(v=>inventoryRow(v,state,selected?.id===v.id)).join(''):
      '<div class="stock-list-empty">No vehicles in this category. Choose another filter to review your active stock.</div>';
    return {selectedId:selected?.id??null,html:head+toolbar+
      '<div class="stock-workspace"><aside class="stock-register" aria-label="Current vehicle inventory">'+
      '<div class="stock-register-title">STOCK REGISTER <span>'+eligible.length+' SHOWN</span></div>'+
      '<div class="stock-register-list">'+list+'</div></aside>'+
      (selected?dossier(selected,state,reportCard):
        '<div class="stock-dossier stock-list-empty">Choose another category to view a vehicle file.</div>')+
      '</div><p class="stock-disclosure">Vehicle history, values and customer demand are simulated. Vehicle photos are representative and are not vehicle-specific evidence.</p>'};
  }
  window.MotorTradeStockView=Object.freeze({render,figures,summary,phase,FILTERS});
})();

finance-view.js:
'use strict';
/* v0.9.27 — Read-only business finance desk.
 * Distinguishes cash, earmarked reserves, stock investment, held deposits,
 * overdue obligations, gross trading margin and operating contribution.
 * No new saved fields and no new economic transactions.
 */
(() => {
  const money=n=>new Intl.NumberFormat('en-GB',{
    style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
  const esc=x=>String(x).replace(/[&<>"']/g,ch=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[ch]));
  const FILTERS=Object.freeze(['all','in','out','noncash']);
  const signed=n=>(n>0?'+':'')+money(n);
  const tone=n=>n<0?' fin-negative':n>0?' fin-positive':'';
  function snapshot(state,E){
    const r=E.monthly.statement(state);
    const reserved=E.workshop.reserved(state);
    const staffDaily=state.staff.reduce((n,v)=>n+E.people.dailyCost(v),0);
    const premisesDaily=E.premises.costs(state).total;
    const arrears=state.payrollArrears+(state.premises?.arrears||0);
    const held=E.customers.heldDeposits(state);
    const auction=state.auctionHall;
    const lot=auction?.phase==='payment'?E.auctionLot(state):null;
    const auctionInvoice=lot?auction.currentBid+lot.fee:0;
    return {cash:state.cash,reserved,afterReserve:state.cash-reserved,
      stock:r.stockCapital,held,arrears,staffDaily,premisesDaily,
      dailyCommitment:staffDaily+premisesDaily,
      grossLifetime:E.totalMargin(state),lifetimeSales:state.sales,
      auctionInvoice,report:r,
      cashReconciles:r.openingCash+r.cashIn-r.cashOut===state.cash};
  }
  function tile(label,number,sub,extra=''){
    return '<div class="fin-tile'+extra+'"><small>'+esc(label)+'</small>'+
      '<strong>'+esc(number)+'</strong><span>'+esc(sub)+'</span></div>';
  }
  function line(label,number,extra=''){
    return '<div class="fin-pair'+extra+'"><span>'+esc(label)+'</span>'+
      '<strong>'+esc(number)+'</strong></div>';
  }
  function summary(state,E){
    const x=snapshot(state,E),r=x.report;
    const month='MONTH '+r.month+' · DAYS '+r.startDay+'–'+r.endDay;
    const noRepairReserve=x.reserved===0;
    const workingLabel=noRepairReserve?'WORKING CASH AVAILABLE':'CASH AFTER REPAIR RESERVES';
    const workingDetail=noRepairReserve?'No workshop funds reserved · before upcoming bills':
      'After earmarked repairs · before upcoming bills';
    const operatingDetail=r.operatingContribution<0?
      'NEGATIVE THIS MONTH · After staff and premises costs':
      r.operatingContribution>0?
        'POSITIVE THIS MONTH · After staff and premises costs':
        'BREAK-EVEN SO FAR · After staff and premises costs';
    const top='<div class="fin-primary">'+
      tile('CASH BALANCE',money(x.cash),'Dealership cash held today · includes repair reserves',' fin-tile-hero')+
      tile(workingLabel,money(x.afterReserve),workingDetail,
        x.afterReserve<0?' fin-tile-alert':'')+
      tile('INVESTED IN UNSOLD VEHICLES',money(x.stock),
        state.vehicles.length+' vehicle'+(state.vehicles.length===1?'':'s')+' still owned')+
      tile('MONTH OPERATING CONTRIBUTION',money(r.operatingContribution),operatingDetail,
        r.operatingContribution<0?' fin-tile-loss':'')+
      '</div>';
    const cashflow='<section class="fin-panel fin-cashflow"><div class="fin-panel-head">'+
      '<div><small>'+month+'</small><h3>WHERE YOUR CASH WENT</h3></div>'+
      '<button type="button" class="fin-text-button" data-page="reports">FULL MONTHLY REPORT</button></div>'+
      '<div class="fin-flow">'+
      '<div><small>MONTH START</small><strong>'+money(r.openingCash)+'</strong></div>'+
      '<span aria-hidden="true">+</span>'+
      '<div><small>CASH RECEIVED</small><strong class="fin-positive">'+money(r.cashIn)+'</strong></div>'+
      '<span aria-hidden="true">−</span>'+
      '<div><small>CASH PAID OUT</small><strong class="fin-negative">'+money(r.cashOut)+'</strong></div>'+
      '<span aria-hidden="true">=</span>'+
      '<div class="fin-flow-total"><small>CASH NOW</small><strong>'+money(x.cash)+'</strong></div>'+
      '</div>'+
      '<div class="fin-flow-footer"><span>NET CASH CHANGE <b class="'+tone(r.netCashChange)+'">'+
      signed(r.netCashChange)+'</b></span><span>'+r.soldUnits+' / '+r.targetUnits+
      ' VEHICLES SOLD TOWARDS MONTHLY TARGET</span></div></section>';
    const notice=x.arrears?
      '<p class="fin-warning">UNPAID BILLS: '+money(x.arrears)+
        ' of staff or premises obligations remain outstanding.</p>':'';
    const auctionNotice=x.auctionInvoice?
      '<p class="fin-warning">AUCTION INVOICE PENDING: '+money(x.auctionInvoice)+
        ' must be settled separately before further buying.</p>':'';
    const commitments='<section class="fin-panel"><div class="fin-panel-head"><div>'+
      '<small>CASH COMMITMENTS</small><h3>WHAT IS ALREADY SPOKEN FOR?</h3></div>'+
      '<button type="button" class="fin-text-button" data-page="workshop">WORKSHOP</button></div>'+
      line('Workshop cash earmarked',money(x.reserved))+
      line('Wages per game day',money(x.staffDaily))+
      line('Premises per game day',money(x.premisesDaily))+
      line('Outstanding bills',money(x.arrears),x.arrears?' fin-due':'')+
      notice+auctionNotice+
      '<p class="fin-detail">Repair reserves are still included in your cash balance. Daily costs are future expenses, not money deducted twice.</p>'+
      '</section>';
    const performance='<section class="fin-panel"><div class="fin-panel-head"><div>'+
      '<small>TRADING & CUSTOMER FUNDS</small><h3>WHAT YOU HAVE EARNED</h3></div>'+
      '<button type="button" class="fin-text-button" data-page="stock">VIEW STOCK</button></div>'+
      line('Completed retail handovers',String(x.lifetimeSales))+
      line('Realised gross trade margin',money(x.grossLifetime),x.grossLifetime<0?' fin-due':'')+
      line('Customer deposits held separately',money(x.held))+
      line('This month gross trade margin',money(r.grossMargin))+
      '<p class="fin-detail">Gross margin is not cash in the bank or net profit. Deposits are held outside dealership cash until handover.</p>'+
      '</section>';
    const footer='<p class="fin-disclosure">Simulation figures only. Operating contribution is not statutory net profit: VAT, tax, finance, depreciation, warranties and other consumer liabilities are not fully modelled.</p>';
    return {snapshot:x,html:top+cashflow+'<div class="fin-secondary">'+
      commitments+performance+'</div>'+footer};
  }
  function category(note){
    if(/^(Retail |Customer deposit applied|Customer-specific |Fair cancellation)/.test(note))return 'CUSTOMER / SALE';
    if(/^(Auction purchase|Direct purchase|Part-exchange acquisition|Pre-purchase inspection)/.test(note))return 'VEHICLE BUYING';
    if(/^(Workshop |Preparation and inspection)/.test(note))return 'WORKSHOP';
    if(/^(Staff |Sales commission|Recruitment )/.test(note))return 'STAFF';
    if(/^Premises /.test(note))return 'PREMISES';
    return 'OTHER';
  }
  function rows(state,filter){
    const f=FILTERS.includes(filter)?filter:'all';
    return [...state.ledger].reverse().filter(row=>f==='all'||(
      f==='in'?row.delta>0:f==='out'?row.delta<0:row.delta===0));
  }
  function ledger(state,{filter='all',expanded=false}={}){
    const f=FILTERS.includes(filter)?filter:'all';
    const all=rows(state,f),visible=expanded?all:all.slice(0,6);
    const count=f==='all'?state.ledger.length:all.length;
    const tabs=[['all','ALL ENTRIES'],['in','MONEY IN'],['out','MONEY OUT'],['noncash','NON-CASH']];
    const controls='<div class="fin-ledger-top"><div><small>ALL RECONCILED TRANSACTIONS</small>'+
      '<h3>TRANSACTION HISTORY</h3></div><div class="fin-ledger-filters" role="group" aria-label="Filter financial transactions">'+
      tabs.map(([key,label])=>'<button type="button" data-action="filter-ledger" data-filter="'+key+
        '" aria-pressed="'+String(f===key)+'">'+label+'</button>').join('')+'</div></div>';
    const entries=visible.length?visible.map(entry=>
      '<div class="fin-entry"><time>DAY '+String(entry.day).padStart(2,'0')+'</time>'+
      '<div class="fin-entry-desc"><small>'+category(entry.note)+'</small><span>'+esc(entry.note)+'</span></div>'+
      '<strong class="'+(entry.delta>0?'fin-positive':entry.delta<0?'fin-negative':'fin-neutral')+'">'+
        (entry.delta===0?'£0 · NON-CASH':(entry.delta>0?'+':'−')+money(Math.abs(entry.delta)))+
      '</strong></div>').join(''):
      '<p class="fin-ledger-empty">'+(state.ledger.length?
        'No transactions match this filter.':'No transactions recorded yet. Your opening cash was '+
        money(state.cash)+'.')+'</p>';
    const toggle=all.length>6?'<button type="button" class="fin-show-more" data-action="toggle-ledger" '+
      'aria-expanded="'+String(expanded)+'">'+
      (expanded?'SHOW RECENT 6 ENTRIES':'VIEW ALL '+count+' ENTRIES')+'</button>':'';
    return {controls,html:entries+'<div class="fin-ledger-bottom">'+
      '<span>SHOWING '+visible.length+' OF '+count+' ENTRIES</span>'+toggle+'</div>'};
  }
  window.MotorTradeFinanceView=Object.freeze({snapshot,summary,ledger,FILTERS});
})();

dashboard-view.js:
'use strict';
/* The Motor Trade v0.9.11 — read-only dashboard decision model.
 * Everything is derived from a current career. No additional saved state,
 * invented transactions, timers or approximate "net profit" claims.
 */
(() => {
  const esc=value=>String(value).replace(/[&<>"']/g,ch=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const money=n=>new Intl.NumberFormat('en-GB',{
    style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
  // A unit target and a profitable month are different claims. This indicator
  // reports vehicle volume only; operating contribution is a separate KPI.
  function salesProgress(report,daysToGo){
    if(report.targetUnits===0)return {text:'No unit target set',positive:false};
    const over=report.soldUnits-report.targetUnits;
    if(over>0)return {text:'✓ Unit target exceeded by '+over+' vehicle'+(over===1?'':'s'),positive:true};
    if(over===0)return {text:'✓ Unit target reached',positive:true};
    const remaining=-over;
    return {text:remaining+' sale'+(remaining===1?'':'s')+' to target · '+daysToGo+
      ' game day'+(daysToGo===1?'':'s')+' left',positive:false};
  }
  function snapshot(state,E){
    const report=E.monthly.statement(state);
    const events=E.events,customers=Object.values(state.customerCases||{});
    const vehicles=state.vehicles||[];
    const listed=vehicles.filter(v=>v.status==='listed').length;
    const awaitingPrep=vehicles.filter(v=>v.status==='acquired').length;
    const unassessed=vehicles.filter(v=>v.workshop?.stage==='unassessed').length;
    const quoted=vehicles.filter(v=>v.workshop?.stage==='quoted').length;
    const qc=vehicles.filter(v=>v.workshop?.stage==='quality-check').length;
    const prepared=vehicles.filter(v=>v.status==='prepared').length;
    const booked=customers.filter(c=>c.status==='booked'&&
      Number.isSafeInteger(c.appointmentDay)&&c.appointmentDay>=state.day).length;
    const dueViewing=customers.filter(c=>c.status==='booked'&&
      Number.isSafeInteger(c.appointmentDay)&&c.appointmentDay<=state.day+1).length;
    const unread=state.messages.filter(m=>!m.read).length;
    const reserved=E.workshop.reserved(state);
    const arrears=(state.payrollArrears||0)+(state.premises?.arrears||0);
    const age=vehicles.filter(v=>v.status==='listed'&&state.day-v.acquiredDay>=14).length;
    const auctionOpen=E.auctionDay(state.day)&&state.auctionHall?.phase!=='finished';
    const auctionDay=auctionOpen?state.day:E.nextAuctionDay(state.day);
    const auctionWeekday=(auctionDay-1)%7===0?'MON':'TUE';
    const daysToGo=Math.max(0,state.monthPlan.endDay-state.day);
    const unitsLeft=Math.max(0,report.targetUnits-report.soldUnits);
    const tasks=[];
    const add=(rank,key,title,description,page,action,tone='normal')=>
      tasks.push({rank,key,title,description,page,action,tone});
    if(state.auctionHall?.phase==='payment'){
      const lot=E.auctionLot(state);
      const due=lot?state.auctionHall.currentBid+lot.fee:null;
      add(0,'auction-invoice','Settle your auction purchase',
        due==null?'A winning hammer invoice needs payment before trading can continue.':
          money(due)+' due including the buyer fee. Vehicle awaits workshop transfer.',
        'auctionHall','PAY INVOICE','urgent');
    }
    if(events.meetingDue(state))
      add(1,'board-meeting','Complete management meeting',
        'Agree this month’s management focus before advancing the game day.',
        'events','OPEN MEETING','urgent');
    if(events.isDealDay(state.day)){
      const closing=state.deadlineSession>=events.PHASES.length-1;
      add(2,'deal-day',closing?'Close the trading month':'Run your Deal Day session',
        closing?'The final session is complete. Review and close the month.':
          'Deal Day session '+(state.deadlineSession+1)+' of '+events.PHASES.length+
          ' · '+events.dealSession(state).time+'.',
        'events',closing?'CLOSE MONTH':'OPEN DEAL DAY','urgent');
    }
    if(state.payrollArrears>0)
      add(3,'payroll','Outstanding staff wages',
        money(state.payrollArrears)+' remains owed to employees.',
        'staff','REVIEW PAYROLL','urgent');
    if(state.premises?.arrears>0)
      add(4,'rent','Unpaid premises overheads',
        money(state.premises.arrears)+' in rent and utilities outstanding.',
        'business','VIEW COSTS','urgent');
    if(dueViewing)
      add(5,'viewing',dueViewing+' customer viewing'+(dueViewing===1?'':'s')+' due',
        'Manage booked viewings and any buyers ready for negotiation.',
        'sales','OPEN SALES','attention');
    if(unassessed||quoted||qc)
      add(6,'workshop',unassessed+quoted+qc+' vehicle'+(unassessed+quoted+qc===1?'':'s')+' need workshop decisions',
        [unassessed?'Assess '+unassessed:0,quoted?'Quote '+quoted:0,qc?'Quality-check '+qc:0]
          .filter(Boolean).join(' · ')+'.',
        'workshop','OPEN WORKSHOP','attention');
    if(prepared)
      add(7,'prepared',prepared+' prepared vehicle'+(prepared===1?'':'s')+' not yet listed',
        'Set retail asking prices to start attracting buyers.',
        'stock','LIST VEHICLES','attention');
    if(vehicles.length===0)
      add(8,'empty-stock','Your forecourt is empty',
        'No cars in stock or ready for retail. Review sourcing options and buying costs.',
        E.auctionDay(state.day)?'auctionHall':'auctions','SOURCE STOCK','attention');
    if(age)
      add(9,'aged-stock',age+' ageing listed vehicle'+(age===1?'':'s'),
        'On the forecourt for 14+ days. Check prices and buyer interest.',
        'stock','REVIEW PRICES','attention');
    if(unread)
      add(10,'inbox',unread+' unread message'+(unread===1?'':'s'),
        'Review recent management and trading communications.',
        'inbox','READ INBOX');
    if(unitsLeft&&daysToGo<=5)
      add(11,'monthly-target',unitsLeft+' sale'+(unitsLeft===1?'':'s')+' needed for monthly target',
        daysToGo+' game day'+(daysToGo===1?'':'s')+' remaining. The operating contribution must also be positive.',
        'reports','REVIEW TARGET','attention');
    if(auctionOpen&&state.auctionHall?.phase!=='payment')
      add(12,'auction-live','Weekly auction session is open',
        'Review numbered lots and bidding limits before purchasing.',
        'auctionHall','ENTER AUCTION');
    if(tasks.length<3&&booked)
      add(13,'appointments',booked+' upcoming booked viewing'+(booked===1?'':'s'),
        'Your sales team has appointments in the pipeline.',
        'sales','VIEW PIPELINE');
    if(report.operatingContribution<0&&report.soldUnits>0&&daysToGo<=5)
      add(13,'negative-contribution','Trading costs exceed your vehicle margin',
        'Current-month operating contribution is '+money(report.operatingContribution)+
          '. Review costs and selling margins before the month closes.',
        'finance','REVIEW OPERATING COSTS','attention');
    // Only suggest the next auction if there is room to buy; never pad the
    // management desk with generic advice when the dealership is healthy.
    if(tasks.length<3&&!auctionOpen&&vehicles.length<state.capacity&&
       auctionDay>state.day&&state.auctionHall?.phase!=='payment'){
      const gap=auctionDay-state.day;
      add(14,'next-auction','Prepare for Day '+auctionDay+' auction',
        (auctionWeekday==='TUE'?'Tuesday':'Monday')+' session in '+gap+
          ' game day'+(gap===1?'':'s')+'. Plan your maximum bid, fees and repair budget.',
        'auctionHall','VIEW AUCTION SCHEDULE');
    }
    tasks.sort((a,b)=>a.rank-b.rank);
    return {
      day:state.day,report,listed,awaitingPrep,unassessed,prepared,booked,unread,
      reserved,arrears,age,unitsLeft,daysToGo,auctionOpen,auctionDay,
      auctionWeekday,tasks:tasks.slice(0,3)
    };
  }
  function priorities(model){
    if(!model.tasks.length)return '<div class="dashboard-all-clear">'+
      '<strong>No urgent decisions outstanding</strong><small>Your current stock, '+
      'appointments and bills show no action requiring immediate attention.</small></div>';
    return model.tasks.map((t,i)=>
      '<button type="button" class="dashboard-action-row dashboard-action-'+esc(t.tone)+
      '" data-page="'+esc(t.page)+'" aria-label="'+esc(t.title)+' — '+esc(t.action)+'">'+
      '<span class="dashboard-action-number">'+String(i+1).padStart(2,'0')+'</span>'+
      '<span class="dashboard-action-copy"><strong>'+esc(t.title)+'</strong>'+
      '<small>'+esc(t.description)+'</small></span>'+
      '<span class="dashboard-action-link">'+esc(t.action)+' <span aria-hidden="true">↗</span></span></button>'
    ).join('');
  }
  function operations(model,state){
    // Only surface indicators that are not already represented in the
    // KPI detail text or the expandable career summary.
    const items=[
      ['LISTED FOR SALE',model.listed,'stock'],
      ['BOOKED VIEWINGS',model.booked,'sales'],
      ['OUTSTANDING BILLS',money(model.arrears),'finance']
    ];
    return items.map(([label,value,page])=>
      '<button type="button" class="dashboard-operations-item" data-page="'+page+
      '" aria-label="'+label+': '+esc(value)+'"><small>'+label+'</small>'+
      '<strong>'+esc(value)+'</strong></button>').join('');
  }
  window.MotorTradeDashboardView=Object.freeze({snapshot,salesProgress,priorities,operations});
})();

inbox-office.js:
'use strict';
/* v0.9.13 — read-only owner communications plus real workshop authorisation.
 * The accounts office reports ledger-backed transactions only. Reading mail
 * never pays an invoice. Repair approval delegates to the existing engine.
 */
(() => {
  const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',
    maximumFractionDigits:0}).format(n);
  const esc=x=>String(x).replace(/[&<>"']/g,c=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const categories=['all','unread','action','operations','staff','accounts','sales','reports'];
  const labels={all:'ALL MAIL',unread:'UNREAD',action:'NEEDS APPROVAL',operations:'WORKSHOP & BUYING',
    staff:'STAFF',accounts:'ACCOUNTS',sales:'CUSTOMERS',reports:'REPORTS'};
  const infer=m=>{
    if(['operations','staff','accounts','sales','reports'].includes(m.category))return m.category;
    const sender=m.from.toUpperCase();
    if(/ACCOUNTS|FINANCE/.test(sender))return 'accounts';
    if(/SALES|CUSTOMER/.test(sender))return 'sales';
    if(/STAFF|HR|TECHNICIAN|PEOPLE/.test(sender))return 'staff';
    if(/REPORT|MANAGEMENT/.test(sender))return 'reports';
    return 'operations';
  };
  const moraleId=m=>{
    const match=/^supervisor-morale:(\d+):\d+$/.exec(m.reference||'');
    return match?Number(match[1]):null;
  };
  const quoteId=m=>{
    const match=/^repair:(\d+)$/.exec(m.reference||'');
    return match?Number(match[1]):null;
  };
  function actionFor(m,state){
    const id=quoteId(m);
    return id===null?null:
      state.vehicles.find(v=>v.id===id&&v.status==='acquired'&&
        v.workshop?.stage==='quoted')||null;
  }
  function needsAction(m,state){
    if(actionFor(m,state))return true;
    const id=moraleId(m);
    return id!==null&&!m.decision&&state.payrollArrears===0&&
      !!state.staff.find(e=>e.id===id&&e.morale>0&&e.morale<=45)&&
      !!state.staff.find(e=>e.role==='supervisor'&&state.day>=e.startDay&&
        (e.trainingUntil===null||state.day>=e.trainingUntil));
  }
  function nextId(state){return state.messages.reduce((highest,m)=>Math.max(highest,m.id),0)+1;}
  function emit(state,entry){
    if(entry.reference&&state.messages.some(m=>m.reference===entry.reference))return false;
    state.messages.push({id:nextId(state),day:state.day,read:false,
      from:entry.from,subject:entry.subject,preview:entry.preview,
      body:entry.body,linkPage:entry.linkPage||null,category:entry.category,
      reference:entry.reference||null});
    // Limit long-play mailboxes; retain pending authorisations and unread mail.
    if(state.messages.length>280){
      const removable=state.messages.findIndex(m=>m.read&&!needsAction(m,state));
      if(removable>=0)state.messages.splice(removable,1);
    }
    return true;
  }
  const noteFor=(row)=>{
    const note=row.note,amount=Math.abs(row.delta);
    if(!Number.isSafeInteger(amount)||amount<=0)return null;
    if(row.delta>0&&!note.startsWith('Retail balance received on collection:'))return null;
    let subject,preview,body,from='ACCOUNTS OFFICE',linkPage='finance',category='accounts';
    if(note.startsWith('Auction purchase:')){
      subject='PAID COPY · Auction purchase settlement';
      preview=money(amount)+' paid for a hammered vehicle, including buyer fee.';
      body='PAYMENT CONFIRMATION — AUCTION HOUSE\n\n'+note+
        '\nAmount already paid: '+money(amount)+
        '.\nStatus: PAID — posted to the dealership cash ledger. The buyer fee is included in the acquisition amount. This is an invoice copy, not a new payment request.';
    }else if(note.startsWith('Workshop repair booking:')){
      subject='PAID COPY · Workshop repair authorisation';
      preview=money(amount)+' paid to book a confirmed repair job.';
      body='SUPPLIER PAYMENT CONFIRMATION\n\n'+note+
        '\nAmount already paid: '+money(amount)+
        '.\nStatus: PAID — workshop booking recorded in the cash ledger. No further payment is due on this copy. See Workshop for repair progress.';
      linkPage='workshop';
    }else if(note.startsWith('Recruitment and onboarding:')){
      from='PEOPLE & PAYROLL';category='staff';linkPage='staff';
      subject='New employee onboarded · Cost confirmed';
      preview=money(amount)+' onboarding fee paid; basic wages continue daily.';
      body='Recruitment has been processed.\n\n'+note+
        '\nOnboarding fee already paid: '+money(amount)+
        '.\nThe new employee begins work on the following game day. Their contracted wages are accounted for through payroll; this email does not create another charge.';
    }else if(note.startsWith('Staff welfare intervention:')){
      from='PEOPLE & PAYROLL';category='staff';linkPage='staff';
      subject='PAID COPY · Approved staff welfare budget';
      preview=money(amount)+' one-off employee support spend, approved by the owner.';
      body='APPROVED STAFF WELFARE EXPENDITURE\n\n'+note+
        '\nAmount settled: '+money(amount)+
        '.\nStatus: PAID. The supervisor is responsible for implementing the agreed rota and welfare support. No additional invoice is payable.';
    }else if(note.startsWith('Staff development:')){
      from='PEOPLE & PAYROLL';category='staff';linkPage='staff';
      subject='Staff training booked · Cost confirmed';
      preview=money(amount)+' spent on authorised employee development.';
      body='Staff training has been approved and paid.\n\n'+note+
        '\nCost already posted: '+money(amount)+
        '.\nReview employee availability and improved skills in Staff & Recruitment.';
    }else if(note.startsWith('Premises investment:')){
      subject='PAID COPY · Premises investment';
      preview=money(amount)+' capital spend recorded; daily overhead may rise.';
      body='CAPITAL EXPENDITURE CONFIRMATION\n\n'+note+
        '\nAmount already paid: '+money(amount)+
        '.\nStatus: PAID. This is capital expenditure and not a second rent payment or an immediate operating expense.';
      linkPage='business';
    }else if(note.startsWith('Workshop assessment:')){
      from='WORKSHOP SUPERVISOR';category='operations';linkPage='workshop';
      subject='Diagnostic inspection completed';
      preview=money(amount)+' assessment fee charged to the vehicle.';
      body='Workshop assessment completed.\n\n'+note+
        '\nDiagnostic charge already paid: '+money(amount)+
        '.\nIf the vehicle requires repairs, a separate approval request will follow. This is a receipt, not a new invoice.';
    }else if(note.startsWith('Retail balance received on collection:')){
      from='SALES OFFICE';category='sales';linkPage='sales';
      subject='Customer vehicle handover · Funds received';
      preview=money(amount)+' net cash balance banked on collection.';
      body='VEHICLE HANDOVER RECEIPT\n\n'+note+
        '\nThe customer balance was received and posted to the ledger. Any previously held deposit was applied separately. Review the sale and staff commission in Management Reports.';
    }else return null;
    return {from,category,subject,preview,body,linkPage};
  };
  function sync(state,engine){
    let changed=false;
    // Only process NEW entries: never resend old ledger history when an old
    // saved career is upgraded. Cursor is persisted for reload idempotency.
    const from=Math.min(state.inboxLedgerCursor||0,state.ledger.length);
    for(let i=from;i<state.ledger.length;i++){
      const row=state.ledger[i],data=noteFor(row);
      if(data)changed=emit(state,{...data,reference:'ledger:'+i})||changed;
    }
    if(state.inboxLedgerCursor!==state.ledger.length){
      state.inboxLedgerCursor=state.ledger.length;changed=true;
    }
    for(const car of state.vehicles){
      if(car.status!=='acquired'||car.workshop?.stage!=='quoted')continue;
      const internal=engine.prepQuote(state,car.id,'internal');
      const external=engine.prepQuote(state,car.id,'external');
      const text=[
        'Our assessment of '+car.title+' is complete. I need your approval before any repair booking or supplier payment.',
        '',
        internal?'IN-HOUSE TECHNICIAN: '+money(internal.cost)+' · '+internal.duration+' game days.':'IN-HOUSE: no technician/bay currently available.',
        external?'EXTERNAL GARAGE: '+money(external.cost)+' · '+external.duration+' game days.':'EXTERNAL: supplier capacity is currently unavailable.',
        '',
        'The estimate is based on the vehicle condition report. The chosen quote is checked against available cash and outstanding repair commitments when you approve it. No repair booking has been paid for yet.'
      ].join('\n');
      changed=emit(state,{from:'WORKSHOP SUPERVISOR',category:'operations',
        subject:'APPROVAL NEEDED · '+car.title,
        preview:'Choose in-house repairs or the external garage before work starts.',
        body:text,linkPage:'workshop',reference:'repair:'+car.id})||changed;
    }
    const week=Math.floor((state.day-1)/7);
    // One factual management update each game week, not daily bookkeeping
    // spam. Also gives older active careers useful current correspondence
    // immediately after migrating to the expanded Inbox.
    if(state.day>=8){
      const statement=engine.monthly.statement(state);
      const period=week+1;
      const shortfall=Math.max(0,statement.targetUnits-statement.soldUnits);
      const summary='Cash '+money(state.cash)+' · Stock '+state.vehicles.length+'/'+state.capacity+
        ' · Month sales '+statement.soldUnits+'/'+statement.targetUnits+'.';
      changed=emit(state,{from:'ACCOUNTS OFFICE',category:'reports',
        subject:'Weekly management accounts · Week '+period,
        preview:summary,
        body:'OWNER FINANCIAL BRIEF — GAME WEEK '+period+'\n\n'+summary+
          '\nGross trading margin this month: '+money(statement.grossMargin)+
          '.\nOperating contribution after recorded staff and premises expenses: '+
          money(statement.operatingContribution)+
          '.\nStaff wage arrears: '+money(state.payrollArrears)+
          '.\nUnpaid rent and utilities: '+money(state.premises?.arrears||0)+
          '.\nUnit target progress: '+(shortfall?shortfall+' still required':
            statement.soldUnits>statement.targetUnits?'exceeded by '+
              (statement.soldUnits-statement.targetUnits):'reached')+
          '.\n\nFigures are from the current business ledger and monthly report. This is an advisory summary, not a payment request or statutory account.',
        linkPage:'reports',reference:'weekly-brief:'+week})||changed;
    }
    if(state.payrollArrears>0)
      changed=emit(state,{from:'PEOPLE & PAYROLL',category:'staff',
        subject:'ACTION REQUIRED · Outstanding wages',
        preview:money(state.payrollArrears)+' payroll liability needs management attention.',
        body:'Payroll has not been fully settled.\n\nUnpaid staff wages: '+money(state.payrollArrears)+
          '.\nThe game will attempt payment from unreserved cash on subsequent game days. Unpaid wages reduce staff morale and reputation. Review staffing and cash-flow decisions; reading this email does not settle the liability.',
        linkPage:'staff',reference:'wage-arrears:'+week})||changed;
    if(state.premises?.arrears>0)
      changed=emit(state,{from:'ACCOUNTS OFFICE',category:'accounts',
        subject:'ACTION REQUIRED · Premises payment shortfall',
        preview:money(state.premises.arrears)+' in unpaid rent/utilities.',
        body:'Our premises charges have accrued but insufficient unreserved cash was available to pay the full balance.\n\nOutstanding: '+money(state.premises.arrears)+
          '.\nAmounts continue to be paid through the existing daily accounts process when cash is available. This email is NOT a payment button or duplicate invoice.',
        linkPage:'finance',reference:'premises-arrears:'+week})||changed;
    const supervisor=engine.people.supervisor(state);
    for(const employee of state.staff){
      if(employee.role==='supervisor'||employee.morale<=0||employee.morale>45)continue;
      const plan=engine.people.moraleProposal(state,employee.id);
      if(plan){
        const body=[
          'I have met with '+employee.name+' following a staff welfare review.',
          '',
          'CURRENT MORALE: '+employee.morale+'/100',
          'PROPOSED ACTION: '+supervisor.name+' will adjust the rota, provide a structured one-to-one support meeting and authorise a modest staff recognition budget.',
          'ONE-OFF COST: '+money(plan.cost),
          'ESTIMATED MORALE IMPROVEMENT: +'+plan.gain+' points (to '+Math.min(100,employee.morale+plan.gain)+'/100).',
          '',
          'Small daily check-ins are already handled by the supervisor. This one-off programme requires your permission because it uses company funds.',
          'Please approve or decline. Declining does not charge the business or immediately remove the employee, but the underlying retention risk remains.'
        ].join('\n');
        changed=emit(state,{from:'STAFF SUPERVISOR · '+supervisor.name,category:'staff',
          subject:'APPROVAL · '+employee.name+' welfare plan',
          preview:'Morale '+employee.morale+'/100 · '+money(plan.cost)+' proposed · your decision required.',
          body,linkPage:'staff',reference:'supervisor-morale:'+employee.id+':'+week})||changed;
      }else if(state.payrollArrears===0&&!supervisor){
        changed=emit(state,{from:'PEOPLE & PAYROLL',category:'staff',
          subject:'SUPERVISOR VACANCY · '+employee.name+' at risk',
          preview:'Morale '+employee.morale+'/100. Hire a supervisor to manage employee welfare.',
          body:'I wanted to flag a people issue that needs a manager assigned.\n\n'+
            employee.name+' currently has a morale score of '+employee.morale+
            '/100. There is no active staff supervisor to meet with them, review the rota or identify what is causing the concern.\n\n'+
            'My recommendation is to appoint a supervisor from the recruitment shortlist. Once they have started, they can handle the conversation and send you a costed proposal if further support requires company funds.\n\n'+
            'There is no charge to approve from this email. Please review the supervisor candidates when you can.',
          linkPage:'staff',reference:'supervisor-gap:'+employee.id+':'+week})||changed;
      }else if(state.payrollArrears>0){
        // Root cause must be resolved before recognition spending can help.
        // Payroll-arrears escalation above already informs the owner.
      }
    }
    for(const c of Object.values(state.customerCases||{})){
      if(c?.status==='booked'&&Number.isSafeInteger(c.appointmentDay)&&c.appointmentDay>=state.day)
        changed=emit(state,{from:'SALES OFFICE',category:'sales',
          subject:'Customer viewing booked · '+c.name,
          preview:'Viewing scheduled for game day '+c.appointmentDay+'. No deposit has been paid.',
          body:'Sales has arranged a viewing with '+c.name+' for game day '+c.appointmentDay+
            '.\n\nThere is no holding deposit at this stage, so the vehicle remains for sale. Confirm attendance and complete a test drive through the Sales Office. Customer attendance is not guaranteed.',
          linkPage:'sales',reference:'viewing:'+c.vehicleId+':'+c.id})||changed;
    }
    return changed;
  }
  function filtered(messages,state,filter){
    const results=[...messages].filter(m=>filter==='all'||
      (filter==='unread'?!m.read:filter==='action'?needsAction(m,state):infer(m)===filter));
    return results.sort((a,b)=>
      Number(needsAction(b,state))-Number(needsAction(a,state))||b.day-a.day||b.id-a.id);
  }
  function counters(messages,state){
    return Object.fromEntries(categories.map(category=>
      [category,filtered(messages,state,category).length]));
  }
  // Saved emails from earlier releases can contain literal "\n" text.
  // Correct this at display time, keeping the original saved correspondence.
  function readableBody(source){
    return String(source??'').replace(/\\r\\n/g,'\n')
      .replace(/\\n/g,'\n').replace(/\\r/g,'\n')
      .replace(/\r\n?/g,'\n').trim();
  }
  function emailSender(message){
    const from=String(message.from||'Dealership Office');
    const supervisor=/^STAFF SUPERVISOR · (.+)$/.exec(from);
    if(supervisor)return {name:supervisor[1],team:'Staff Supervisor',initials:supervisor[1]
      .split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase()};
    const text=from.toLowerCase().replace(/\b[a-z]/g,c=>c.toUpperCase());
    const initials=from==='PEOPLE & PAYROLL'?'HR':from==='ACCOUNTS OFFICE'?'AC':
      from==='SALES OFFICE'?'SO':from==='WORKSHOP SUPERVISOR'?'WS':'MT';
    return {name:text,team:infer(message)==='reports'?'Management Reporting':'Dealership Operations',initials};
  }
  function emailDate(day){
    const date=new Date(Date.UTC(2026,10,9)+(day-1)*86400000);
    return new Intl.DateTimeFormat('en-GB',{weekday:'short',day:'numeric',
      month:'short',year:'numeric',timeZone:'UTC'}).format(date);
  }
  function preparedBody(message){
    let text=readableBody(message.body);
    // Repair the original, saved supervisor-vacancy emails as well as newly
    // generated ones. Do not change morale figures or invent a staff decision.
    if((message.reference||'').startsWith('supervisor-gap:')){
      const person=String(message.subject).replace(/^SUPERVISOR VACANCY\s*·\s*/i,'')
        .replace(/\s+at risk$/i,'');
      const morale=/morale\s+(\d+)\/100/i.exec(text)?.[1]||
        /morale\s+(\d+)\/100/i.exec(message.preview||'')?.[1];
      return 'I wanted to bring a staffing concern to your attention. '+
        person+' currently has a morale score of '+(morale?morale+'/100':'below our expected level')+'.'+
        '\n\nWe do not have an active staff supervisor to speak with them, review the rota or follow up on the underlying issues.'+
        '\n\nI recommend appointing a supervisor from the available applicants. Once appointed and on duty, they can manage the matter directly and put a costed proposal to you if additional spending is justified.'+
        '\n\nNo payment or personnel action is being requested by this email. The recruitment decision is yours.';
    }
    return text;
  }
  function formatMail(message,state){
    const category=infer(message);
    const sender=emailSender(message);
    const decision=message.decision||'';
    const status=decision?decision.toUpperCase():
      needsAction(message,state)?'AWAITING YOUR APPROVAL':
      message.subject.startsWith('PAID COPY')?'PAID · FOR YOUR RECORDS':'FOR INFORMATION';
    const body=preparedBody(message);
    const blocks=body.split(/\n{2,}/).filter(x=>x.trim());
    const renderLine=line=>{
      const value=line.trim();
      if(!value)return '';
      if(/^[A-Z][A-Z 0-9/&£+·—-]{5,65}$/.test(value))
        return '<h3 class="mail-subject-heading">'+esc(value)+'</h3>';
      const match=/^([A-Z][A-Z 0-9/&-]{2,49}:)\s*(.*)$/.exec(value);
      if(match)
        return '<div class="mail-key-value"><span>'+esc(match[1].slice(0,-1))+
          '</span><strong>'+esc(match[2])+'</strong></div>';
      return '<p>'+esc(value)+'</p>';
    };
    const contents=blocks.map(part=>
      '<div class="mail-paragraph-group">'+part.split('\n').map(renderLine).join('')+
      '</div>').join('');
    const isGreeting=/^(?:hi|hello|dear|good morning|good afternoon)\b/i.test(body);
    const greeting=isGreeting?'':'<p class="mail-greeting">Hello,</p>';
    const isoDate=new Date(Date.UTC(2026,10,9)+(message.day-1)*86400000)
      .toISOString().slice(0,10);
    return '<article class="inbox-email" aria-label="Business email from '+esc(sender.name)+'">'+
      '<header class="inbox-email-header">'+
        '<div class="inbox-email-avatar" aria-hidden="true">'+esc(sender.initials)+'</div>'+
        '<div class="inbox-email-address"><strong>'+esc(sender.name)+'</strong>'+
          '<small>'+esc(sender.team)+'</small>'+
          '<span>To: Dealership Owner · '+esc(state.name)+'</span></div>'+
        '<time class="inbox-email-time" datetime="'+isoDate+'">'+
          esc(emailDate(message.day))+'</time>'+
      '</header>'+
      '<div class="inbox-email-status"><span>'+esc(status)+'</span>'+
        '<span>INTERNAL CORRESPONDENCE</span></div>'+
      '<div class="inbox-email-body">'+greeting+contents+
        '<div class="inbox-email-signature"><span>Kind regards,</span>'+
        '<strong>'+esc(sender.name)+'</strong>'+
        '<small>'+esc(sender.team)+'</small></div>'+
      '</div>'+
    '</article>';
  }
  function quoteControls(message,state,engine){
    const car=actionFor(message,state);
    const moraleEmployeeId=moraleId(message);
    if(moraleEmployeeId!==null){
      const employee=state.staff.find(e=>e.id===moraleEmployeeId);
      if(message.decision)return '<div class="inbox-resolved">SUPERVISOR PLAN '+
        esc(message.decision.toUpperCase())+'. This is a recorded decision; '+
        'no duplicate expense is possible. Check the current employee status in Staff & Recruitment.</div>';
      const plan=engine.people.moraleProposal(state,moraleEmployeeId);
      if(!plan)return '<div class="inbox-resolved">This staff welfare recommendation is no longer actionable. '+
        'Review the latest supervisor report, payroll situation and employee roster.</div>';
      return '<div class="inbox-approval inbox-staff-approval">'+
        '<div class="inbox-approval-intro"><strong>OWNER AUTHORISATION REQUIRED</strong>'+ 
        '<small>'+esc(plan.manager.name)+' proposes a '+money(plan.cost)+
        ' one-off rota-support and staff welfare intervention for '+esc(employee.name)+
        '. Morale '+employee.morale+'/100 → '+Math.min(100,employee.morale+plan.gain)+
        '/100. Routine check-ins remain delegated.</small></div>'+ 
        '<div class="inbox-approval-choices">'+
        '<button class="trade-button" data-action="decide-staff-welfare" data-decision="approve" data-id="'+
          message.id+'">APPROVE · '+money(plan.cost)+'</button>'+ 
        '<button class="trade-button trade-button-outline" data-action="decide-staff-welfare" data-decision="decline" data-id="'+
          message.id+'">DECLINE · £0</button></div></div>';
    }
    if(quoteId(message)===null)return '';
    if(!car)return '<div class="inbox-resolved">This repair request is no longer pending. '+
      'Review the vehicle’s actual status in Workshop.</div>';
    const internal=engine.prepQuote(state,car.id,'internal');
    const external=engine.prepQuote(state,car.id,'external');
    const choices=[['internal',internal,'APPROVE IN-HOUSE'],['external',external,'APPROVE EXTERNAL GARAGE']];
    return '<div class="inbox-approval"><div class="inbox-approval-intro"><strong>OWNER DECISION REQUIRED</strong>'+
      '<small>Select a workshop quote. Approval books and pays the job through the existing workshop account — no separate invoice payment.</small></div>'+
      '<div class="inbox-approval-choices">'+choices.map(([method,q,label])=>
        '<button type="button" class="trade-button" data-action="approve-inbox-repair"'+
        ' data-id="'+car.id+'" data-method="'+method+'"'+(!q?' disabled':'')+'>'+
        label+(q?' · '+money(q.cost)+' / '+q.duration+' DAYS':' · NOT AVAILABLE')+'</button>').join('')+
      '</div></div>';
  }
  window.MotorTradeInbox=Object.freeze({
    categories,labels,infer,quoteId,moraleId,actionFor,needsAction,sync,filtered,counters,
    quoteControls,formatMail,readableBody,emailDate,emit,esc
  });
})();
